{"command":"cat > /workspace/src/core.py <<'EOF'
"""Core of the tag generator: registry, options, entries, writers."""
import sys, os, re, time, stat, fnmatch
import ctags_data

PROGRAM = 'executable'
VERSION = '6.2.0'
REVISION = '1cdb801'
OUTPUT_VERSION = '1.1'

def set_program_name(argv0):
    global PROGRAM
    PROGRAM = os.path.basename(argv0) if argv0 else 'ctags'

out_stream = None  # binary stdout

def errprint(msg):
    sys.stderr.write(msg + '\n')
    sys.stderr.flush()

def warning(msg):
    errprint('%s: Warning: %s' % (PROGRAM, msg))

def notice(msg):
    if not OPT.quiet:
        errprint('%s: Notice: %s' % (PROGRAM, msg))

def verbose(msg):
    if OPT.verbose:
        sys.stderr.write(msg)

class FatalError(Exception):
    def __init__(self, msg, code=1):
        Exception.__init__(self, msg)
        self.msg = msg
        self.code = code

def error(msg, code=1):
    raise FatalError(msg, code)

def isalpha(c): return ('a' <= c <= 'z') or ('A' <= c <= 'Z')
def isdigit(c): return '0' <= c <= '9'
def isalnum(c): return isalpha(c) or isdigit(c)
def isident(c): return isalnum(c) or c == '_'
def isspace(c): return c in ' \t\n\r\f\v'
def isxdigit(c): return isdigit(c) or ('a' <= c <= 'f') or ('A' <= c <= 'F')

def ascii_lower(s):
    return s.translate(_LOWER)
def ascii_upper(s):
    return s.translate(_UPPER)
_LOWER = {i: i + 32 for i in range(65, 91)}
_UPPER = {i: i - 32 for i in range(97, 123)}

# ---------------------------------------------------------------------------
# Registry

class Role:
    __slots__ = ('name', 'desc', 'enabled', 'ver', 'kind')
    def __init__(self, name, enabled, ver, desc):
        self.name = name; self.enabled = enabled; self.ver = ver; self.desc = desc

class Kind:
    __slots__ = ('letter', 'name', 'enabled', 'refonly', 'master', 'ver', 'desc', 'roles', 'lang', 'index', 'sep')
    def __init__(self, letter, name, enabled, refonly, master, ver, desc):
        self.letter = letter; self.name = name; self.enabled = enabled
        self.refonly = refonly; self.master = master; self.ver = ver; self.desc = desc
        self.roles = []
        self.lang = None
        self.index = 0
    def role(self, name):
        for r in self.roles:
            if r.name == name:
                return r
        return None

class Field:
    __slots__ = ('letter', 'name', 'enabled', 'jstype', 'fixed', 'op', 'ver', 'desc', 'lang', 'datatype')
    def __init__(self, letter, name, enabled, jstype, fixed, op, ver, desc, lang=None):
        self.letter = letter; self.name = name; self.enabled = enabled; self.jstype = jstype
        self.fixed = fixed; self.op = op; self.ver = ver; self.desc = desc; self.lang = lang
        self.datatype = 'str'

class Extra:
    __slots__ = ('letter', 'name', 'enabled', 'fixed', 'ver', 'desc', 'lang')
    def __init__(self, letter, name, enabled, fixed, ver, desc, lang=None):
        self.letter = letter; self.name = name; self.enabled = enabled
        self.fixed = fixed; self.ver = ver; self.desc = desc; self.lang = lang

class Param:
    __slots__ = ('name', 'desc', 'value', 'handler')
    def __init__(self, name, desc):
        self.name = name; self.desc = desc; self.value = None; self.handler = None

class Language:
    def __init__(self, name):
        self.name = name
        self.enabled = True
        self.version = '0.0'
        self.kinds = []
        self.fields = []
        self.extras = []
        self.params = []
        self.extensions = []
        self.patterns = []
        self.rexprs = []
        self.aliases = []
        self.nulltag = False
        self.parser = None      # callable(ctx)
        self.module = None      # module name to import lazily
        self.base = None        # for subparsers
        self.subparsers = []    # list of (Language, direction)
        self.optlib = None      # regex based definition (OptlibDef)
        self.used = False       # pseudo tags emitted
        self.user_defined = False
        self.pretend = None
        self.scope_seps = {}    # (parentLetter, childLetter) -> sep
        self.default_sep = '.'
        self.selectors = []
        self.initialized = False
        self.auto_fqtag = False
        self.foreign = []
        self.prelude = []
        self.sequel = []
        self.direction = None
    def kind(self, key):
        """Find kind by letter or name."""
        k = self._kmap.get(key) if hasattr(self, '_kmap') else None
        if k is not None:
            return k
        for kk in self.kinds:
            if kk.name == key:
                return kk
        for kk in self.kinds:
            if kk.letter == key:
                return kk
        return None
    def rebuild(self):
        self._kmap = {}
        for i, k in enumerate(self.kinds):
            k.lang = self
            k.index = i
            self._kmap.setdefault(k.name, k)
        for k in self.kinds:
            if k.letter not in self._kmap:
                self._kmap[k.letter] = k
    def field(self, name):
        for f in self.fields:
            if f.name == name:
                return f
        return None
    def extra(self, name):
        for e in self.extras:
            if e.name == name:
                return e
        return None
    def param(self, name):
        for p in self.params:
            if p.name == name:
                return p
        return None

LANGS = []
LANG_BY_NAME = {}
COMMON_FIELDS = []
COMMON_FIELD = {}
COMMON_EXTRAS = []
COMMON_EXTRA = {}

def find_language(name):
    if name is None:
        return None
    l = LANG_BY_NAME.get(name.lower())
    return l

def add_language(L):
    LANGS.append(L)
    LANG_BY_NAME[L.name.lower()] = L

def init_registry():
    for d in ctags_data.LANGS:
        L = Language(d['name'])
        L.enabled = d['enabled']
        L.version = d['version']
        for (letter, name, en, refonly, master, ver, desc) in d['kinds']:
            L.kinds.append(Kind(letter, name, en, refonly, master, ver, desc))
        L.rebuild()
        for (kl, kname, rname, en, ver, desc) in d['roles']:
            k = None
            for kk in L.kinds:
                if kk.name == kname and kk.letter == kl:
                    k = kk; break
            if k is None:
                k = L.kind(kname)
            if k is not None:
                r = Role(rname, en, ver, desc)
                r.kind = k
                k.roles.append(r)
        for (letter, name, en, jstype, fixed, op, ver, desc) in d['fields']:
            f = Field(letter, name, en, jstype, fixed, op, ver, desc, L)
            if jstype == '-i-': f.datatype = 'int'
            elif jstype == '--b': f.datatype = 'bool'
            elif jstype == 's-b': f.datatype = 'str+bool'
            L.fields.append(f)
        for (letter, name, en, fixed, ver, desc) in d['extras']:
            L.extras.append(Extra(letter, name, en, fixed, ver, desc, L))
        for (name, desc) in d['params']:
            L.params.append(Param(name, desc))
        L.extensions = list(d['extensions'])
        L.patterns = list(d['patterns'])
        L.rexprs = [tuple(x) for x in d['rexprs']]
        L.aliases = list(d['aliases'])
        L.nulltag = d['nulltag']
        add_language(L)
    for (letter, name, en, jstype, fixed, op, ver, desc) in ctags_data.COMMON_FIELDS:
        f = Field(letter, name, en, jstype, fixed, op, ver, desc, None)
        COMMON_FIELDS.append(f)
    for (letter, name, en, fixed, ver, desc) in ctags_data.COMMON_EXTRAS:
        e = Extra(letter, name, en, fixed, ver, desc, None)
        COMMON_EXTRAS.append(e)
        COMMON_EXTRA[name] = e
    for f in COMMON_FIELDS:
        COMMON_FIELD[f.letter if f.name == 'NONE' else f.name] = f
    for (sub, base, direction) in ctags_data.SUBPARSERS:
        S = find_language(sub); B = find_language(base)
        if S and B:
            if S.base is None:
                S.base = B
            S.direction = direction
            B.subparsers.append((S, direction))

# Field order used internally (pseudo tag listing and json)
FIELD_ORDER = ['N', 'F', 'P', 'C', 'f', 'l', 'n', 't', 'K', 'z', 'k', 'i', 'a', 'm', 'S', 's', 'Z', 'p', 'r', 'R', 'E', 'x', 'e', 'T', 'o']

def cfield(letter):
    for f in COMMON_FIELDS:
        if f.letter == letter:
            return f
    return None

def field_enabled(letter):
    f = cfield(letter)
