                return seps[key]
    return lang.default_sep if lang is not None else '.'

def tag_scope(t):
    """Return (kind, scopename) of a tag or (None, None)."""
    if t.scope:
        p = t.ctx.cork[t.scope]
        return p.kind, full_name(p)
    if t.scope_name is not None:
        return t.scope_kind, t.scope_name
    return None, None

def full_name(t):
    if t.qual_name is not None:
        return t.qual_name
    k, s = tag_scope(t)
    if s is None:
        return t.name
    L = t.lang
    if t.scope:
        p = t.ctx.cork[t.scope]
        return s + kind_sep(p.lang if p.lang is L else L, p.kind, t.kind) + t.name
    return s + kind_sep(L, k, t.kind) + t.name

def kind_name(k):
    if k is None:
        return None
    if isinstance(k, Kind):
        return k.name
    return k

# ---------------------------------------------------------------------------
# Escaping

def escape_ctags_name(s, first=True):
    out = []
    for i, c in enumerate(s):
        o = ord(c)
        if c == '\\':
            out.append('\\\\')
        elif o < 0x20 or o == 0x7f:
            if c == '\t': out.append('\\t')
            elif c == '\n': out.append('\\n')
            elif c == '\r': out.append('\\r')
            elif c == '\a': out.append('\\a')
            elif c == '\b': out.append('\\b')
            elif c == '\v': out.append('\\v')
            elif c == '\f': out.append('\\f')
            else: out.append('\\x%02X' % o)
        elif i == 0 and first and c == '!':
            out.append('\\x21')
        else:
            out.append(c)
    return ''.join(out)

def escape_field_value(s):
    if s is None:
        return ''
    need = False
    for c in s:
        if c == '\\' or ord(c) < 0x20 or c == '\x7f':
            need = True
            break
    if not need:
        return s
    return escape_ctags_name(s, first=False)

def json_escape(s):
    out = ['"']
    for c in s:
        o = ord(c)
        if c == '"': out.append('\\"')
        elif c == '\\': out.append('\\\\')
        elif o < 0x20:
            if c == '\n': out.append('\\n')
            elif c == '\t': out.append('\\t')
            elif c == '\r': out.append('\\r')
            elif c == '\b': out.append('\\b')
            elif c == '\f': out.append('\\f')
            else: out.append('\\u%04X' % o)
        else:
            out.append(c)
