def utf8_extend(b, n):
    """Return cut position >= n so as not to split a UTF-8 sequence."""
    L = len(b)
    while n < L and 0x80 <= ord(b[n]) <= 0xBF:
        n += 1
    return n

def truncate_after_name(line, name):
    p = line.find(name)
    if p < 0:
        return line
    p += len(name)
    if p < len(line):
        p += 1
    return line[:p]

def tag_source_line(t):
    if t.pattern is not None:
        src = t.pattern
    else:
        src = t.ctx.line_text(t.line)
    if t.truncate:
        src = truncate_after_name(src, t.name)
    return src

def make_pattern(t, backward=None):
    if backward is None:
        backward = OPT.backward
    src = tag_source_line(t)
    # cut at line terminator
    complete = False
    for i, c in enumerate(src):
        if c == '\n' or c == '\r':
            src = src[:i]
            complete = True
            break
    limit = OPT.pattern_length_limit
    if limit and len(src) > limit:
        cut = utf8_extend(src, limit)
        if cut < len(src):
            src = src[:cut]
            complete = False
    delim = '?' if backward else '/'
    out = [delim, '^']
    n = len(src)
    for i, c in enumerate(src):
        if c == '\\':
            out.append('\\\\')
        elif c == delim:
            out.append('\\' + delim)
        elif c == '$' and i == n - 1 and complete:
            out.append('\\$')
        else:
            out.append(c)
    if complete:
        out.append('$')
    out.append(delim)
    return ''.join(out)

def compact_line(t):
    src = tag_source_line(t)
    for i, c in enumerate(src):
        if c == '\n' or c == '\r':
            src = src[:i]
            break
    out = []
    j = 0
    n = len(src)
    while j < n and isspace(src[j]):
        j += 1
    prev_space = False
    while j < n:
        c = src[j]
        if isspace(c):
            if not prev_space:
                out.append(' ')
            prev_space = True
        else:
            out.append(c)
            prev_space = False
        j += 1
    return ''.join(out)
