                if f.name == fname and f.lang and f.lang.name == lname:
                    return str(v) if v is not True else ''
        return None
    if t.pfields:
        for f, v in t.pfields:
            if f.name == name:
                return str(v) if v is not True else ''
    return None

_xfmt_re = re.compile(r'%(-?)(\d*)(?:\{([^}]*)\}|(.))')

def format_xref(t):
    fmt = OPT.xformat if OPT.xformat is not None else XFORMAT_DEFAULT
    out = []
    i = 0
    n = len(fmt)
    while i < n:
        c = fmt[i]
        if c != '%':
            out.append(c); i += 1; continue
        m = _xfmt_re.match(fmt, i)
        if not m:
            out.append(c); i += 1; continue
        i = m.end()
        left, width, lname, letter = m.groups()
        if letter == '%':
            out.append('%'); continue
        if lname is not None:
            v = xref_named_field(t, lname)
        else:
            v = xref_field(t, letter)
        if v is None:
            v = '-'
        if width:
            w = int(width)
            v = v.ljust(w) if left else v.rjust(w)
        out.append(v)
    return ''.join(out)

def format_etags_entry(t):
    src = tag_source_line(t)
    for i, c in enumerate(src):
        if c == '\n' or c == '\r':
            src = src[:i]
            break
    return '%s\x7f%s\x01%d,%d\n' % (src, t.name, t.line, t.ctx.line_start(t.line) if t.pattern is None else t.lineoff)
