"""Implementation of the --list-* options."""
from core import *
import core

def colprint(header, rows, right=(), machinable=None, with_header=None, header_always=False):
    if machinable is None:
        machinable = OPT.machinable
    if with_header is None:
        with_header = OPT.with_list_header
    out = []
    if machinable:
        if with_header or header_always:
            out.append('\t'.join(header))
        for r in rows:
            out.append('\t'.join(r))
        write_out(''.join(l + '\n' for l in out))
        return
    allrows = ([header] if (with_header or header_always) else []) + rows
    if not allrows:
        return
    n = len(header)
    widths = [0] * n
    for r in [header] + rows:
        for i in range(n):
            if len(r[i]) > widths[i]:
                widths[i] = len(r[i])
    for r in allrows:
        cells = []
        for i in range(n):
            if i == n - 1:
                cells.append(r[i])
            elif i in right:
                cells.append(r[i].rjust(widths[i]))
            else:
                cells.append(r[i].ljust(widths[i]))
        out.append(' '.join(cells))
    write_out(''.join(l + '\n' for l in out))

def yn(b):
    return 'yes' if b else 'no'

def visible_langs():
    return [L for L in LANGS if L.name not in ('UniversalCtags', 'CTagsSelfTest', 'YamlFrontMatter')]

def sorted_langs_ci():
    return sorted(visible_langs(), key=lambda L: ascii_lower(L.name))

def sorted_langs_cs():
    return sorted(visible_langs(), key=lambda L: L.name)

def resolve_lang_arg(arg, optname):
    if arg is None or arg == '' or arg == 'all':
        return None
    L = find_language(arg)
    if L is None:
        error('Unknown language "%s" in "%s" option' % (arg, optname))
    return L

def list_languages():
    out = []
    for L in sorted_langs_ci():
        out.append(L.name + ('' if L.enabled else ' [disabled]'))
    write_out(''.join(l + '\n' for l in out))

def kind_line(k, indent=''):
    s = '%s%s  %s' % (indent, k.letter, k.desc)
    if not k.enabled:
        s += ' [off]'
    return s

def list_kinds(arg):
    L = resolve_lang_arg(arg, 'list-kinds')
    out = []
    if L is not None:
        for k in L.kinds:
            out.append(kind_line(k))
    else:
        for L in visible_langs():
            out.append(L.name + ('' if L.enabled else ' [disabled]'))
            for k in L.kinds:
                out.append(kind_line(k, '    '))
    write_out(''.join(l + '\n' for l in out))

def kind_full_rows(L, with_lang):
    rows = []
    for k in sorted(L.kinds, key=lambda k: k.letter):
        r = [k.letter, k.name, yn(k.enabled), yn(k.refonly), str(len(k.roles)), k.master, str(k.ver), k.desc]
        if with_lang:
            r = [L.name] + r
        rows.append(r)
    return rows

def list_kinds_full(arg):
    L = resolve_lang_arg(arg, 'list-kinds-full')
    if L is not None:
        colprint(['#LETTER', 'NAME', 'ENABLED', 'REFONLY', 'NROLES', 'MASTER', 'VER', 'DESCRIPTION'],
                 kind_full_rows(L, False), right=(6,), header_always=True)
    else:
        rows = []
        for L in sorted_langs_cs():
            rows += kind_full_rows(L, True)
        colprint(['#LANGUAGE', 'LETTER', 'NAME', 'ENABLED', 'REFONLY', 'NROLES', 'MASTER', 'VER', 'DESCRIPTION'],
