    if machinable is None:
        machinable = OPT.machinable
    if with_header is None:
        with_header = OPT.with_list_header
    out = []
    if machinable:
        if with_header or header_always:
            out.append('\t'.join(header))
        for r in rows:
            out.append('\t'.join(r))
        write_out(''.join(l + '\n' for l in out))
        return
    allrows = ([header] if (with_header or header_always) else []) + rows
    if not allrows:
        return
    n = len(header)
    widths = [0] * n
    for r in [header] + rows:
        for i in range(n):
            if len(r[i]) > widths[i]:
                widths[i] = len(r[i])
    for r in allrows:
        cells = []
        for i in range(n):
            if i == n - 1:
                cells.append(r[i])
            elif i in right:
                cells.append(r[i].rjust(widths[i]))
            else:
                cells.append(r[i].ljust(widths[i]))
        out.append(' '.join(cells))
