        for f in COMMON_FIELDS:
            if not f.fixed:
                f.enabled = False
    for mode, item, isname in iter_spec(spec):
        en = (mode == '+')
        if item == '*' and not isname:
            for f in COMMON_FIELDS:
                if not f.fixed:
                    f.enabled = en
            continue
        target = None
        if isname:
            if '.' in item:
                lname, fname = item.split('.', 1)
                L = find_language(lname)
                if L is not None:
                    target = L.field(fname)
            else:
                for f in COMMON_FIELDS:
                    if f.name == item:
                        target = f
                        break
            if target is None:
                warning('Unsupported parameter \'{%s}\' for "%s" option' % (item, optname))
                continue
        else:
            for f in COMMON_FIELDS:
                if f.letter == item:
                    target = f
                    break
            if target is None:
                warning('Unsupported parameter \'%s\' for "%s" option' % (item, optname))
                continue
        if target.fixed:
            if not en:
                warning('Cannot disable fixed field: \'%s\'{%s}' % (target.letter, target.name))
            continue
        target.enabled = en

def apply_lang_fields(L, spec, optname):
