    if spec_resets(spec):
        for LL in langs:
            for f in LL.fields:
                f.enabled = False
    for mode, item, isname in iter_spec(spec):
        en = (mode == '+')
        if item == '*' and not isname:
            for LL in langs:
                for f in LL.fields:
                    f.enabled = en
            continue
        if not isname:
            warning('only long name can be used in --%s option' % optname)
            continue
        found = False
        for LL in langs:
            f = LL.field(item)
            if f is not None:
                f.enabled = en
                found = True
        if not found:
            warning('Unsupported parameter \'{%s}\' for "%s" option' % (item, optname))

def apply_extras(spec, optname='extras'):
    if spec_resets(spec):
        for e in COMMON_EXTRAS:
            if not e.fixed:
                e.enabled = False
            if e.name == 'pseudo':
                EXTRAS_EXPLICIT['pseudo'] = True
