                e.enabled = False
    for mode, item, isname in iter_spec(spec):
        en = (mode == '+')
        if item == '*' and not isname:
            for LL in langs:
                for e in LL.extras:
                    e.enabled = en
            continue
        found = False
        for LL in langs:
            for e in LL.extras:
                if (isname and e.name == item) or (not isname and e.letter == item and e.letter != '-'):
                    e.enabled = en
                    found = True
        if not found:
            if isname:
                warning('Unsupported parameter \'{%s}\' for "%s" option' % (item, optname))
            else:
                warning('Unsupported parameter \'%s\' for "%s" option' % (item, optname))

def apply_kinds(L, spec, optname):
    if spec_resets(spec):
        for k in L.kinds:
            k.enabled = False
    for mode, item, isname in iter_spec(spec):
        en = (mode == '+')
        if item == '*' and not isname:
            for k in L.kinds:
                k.enabled = en
            continue
        found = False
        for k in L.kinds:
            if (isname and k.name == item) or (not isname and k.letter == item):
                k.enabled = en
                found = True
        if not found:
            if isname:
                warning("Unsupported kind: '%s' for --%s option" % (item, optname))
            else:
                warning("Unsupported kind: '%s' for --%s option" % (item, optname))

def apply_roles(L, kspec, spec, optname):
    langs = LANGS if L is None else [L]
    for LL in langs:
        kinds = []
        if kspec == '*':
            kinds = LL.kinds
        else:
            for mode, item, isname in iter_spec(kspec):
                for k in LL.kinds:
                    if (isname and k.name == item) or (not isname and k.letter == item):
                        kinds.append(k)
        for k in kinds:
            if spec_resets(spec):
                for r in k.roles:
                    r.enabled = False
            for mode, item, isname in iter_spec(spec):
                en = (mode == '+')
                if item == '*' and not isname:
                    for r in k.roles:
                        r.enabled = en
                    continue
                if not isname:
                    error('unexpected character %s in --%s option' % (item, optname))
                r = k.role(item)
                if r is not None:
                    r.enabled = en

def set_lang_enabled(L, en):
    if en and L.name == 'Cargo':
        warning('Enabling Cargo subparser may enable TOML parser.')
    if en and L.name == 'TOML':
        warning('The current implementation of the TOML parser is broken.')
    L.enabled = en

def apply_languages(spec):
    items = spec.split(',')
    first = True
    for item in items:
        if item == '':
            continue
        mode = None
        if item[0] in '+-':
            mode = item[0]
            item = item[1:]
        if first and mode is None:
            warning('Enabling Cargo subparser may enable TOML parser.')
            warning('The current implementation of the TOML parser is broken.')
            for L in LANGS:
                L.enabled = False
        first = False
        en = (mode != '-')
        if item == 'all':
            if mode is not None:
                warning('Enabling Cargo subparser may enable TOML parser.')
                warning('The current implementation of the TOML parser is broken.')
            for L in LANGS:
                L.enabled = en
            continue
        L = find_language(item)
        if L is None:
            warning('Unknown language "%s" in "languages" option' % item)
            continue
        set_lang_enabled(L, en)

# ---------------------------------------------------------------------------
# language maps

def remove_ext_everywhere(ext, except_lang=None):
    for L in LANGS:
        if L is except_lang:
            continue
        if ext in L.extensions:
            L.extensions = [e for e in L.extensions if e != ext]

def remove_pattern_everywhere(pat, except_lang=None):
    for L in LANGS:
        if L is except_lang:
            continue
        if pat in L.patterns:
            L.patterns = [p for p in L.patterns if p != pat]

def apply_langmap(spec):
    for m in split_langmap(spec):
        if ':' not in m:
            error('Invalid language map specification: %s' % m)
        lname, maps = m.split(':', 1)
        L = find_language(lname)
        if L is None:
            error('Unknown language "%s" in "langmap" option' % lname)
        if maps.startswith('+'):
            maps = maps[1:]
        elif maps == 'default':
            continue
        else:
            L.extensions = []
            L.patterns = []
        i = 0
        while i < len(maps):
            c = maps[i]
            if c == '(':
                j = maps.find(')', i)
                if j < 0:
                    j = len(maps)
                pat = maps[i + 1:j]
                remove_pattern_everywhere(pat, L)
                if pat not in L.patterns:
                    L.patterns.append(pat)
                i = j + 1
            elif c == '.':
                j = i + 1
                while j < len(maps) and maps[j] not in '.(':
                    j += 1
                ext = maps[i + 1:j]
                remove_ext_everywhere(ext, L)
                if ext not in L.extensions:
                    L.extensions.append(ext)
                i = j
            else:
                j = i
                while j < len(maps) and maps[j] not in '.(':
                    j += 1
                pat = maps[i:j]
                remove_pattern_everywhere(pat, L)
                if pat not in L.patterns:
                    L.patterns.append(pat)
                i = j

def split_langmap(spec):
    out = []
    depth = 0
    cur = ''
    for c in spec:
        if c == '(':
            depth += 1
        elif c == ')':
            depth -= 1
        if c == ',' and depth == 0:
            out.append(cur)
            cur = ''
        else:
            cur += c
    if cur:
        out.append(cur)
    return out

def apply_map(L, spec):
    mode = None
    if spec and spec[0] in '+-':
        mode = spec[0]
        spec = spec[1:]
    if mode is None:
        L.extensions = []
        L.patterns = []
    if spec.startswith('(') and spec.endswith(')'):
        pat = spec[1:-1]
        if mode == '-':
            L.patterns = [p for p in L.patterns if p != pat]
        elif pat not in L.patterns:
            L.patterns.append(pat)
    elif spec.startswith('%'):
        # rexpr
        rx = spec[1:]
        case = 'sensitive'
        if rx.endswith('%i'):
            rx = rx[:-2]; case = 'insensitive'
        elif rx.endswith('%'):
            rx = rx[:-1]
        if mode == '-':
            L.rexprs = [r for r in L.rexprs if r[0] != rx]
        else:
            L.rexprs.append((rx, case))
    elif spec.startswith('.'):
        ext = spec[1:]
        if mode == '-':
            L.extensions = [e for e in L.extensions if e != ext]
        elif ext not in L.extensions:
            L.extensions.append(ext)
    else:
        if mode == '-':
            L.patterns = [p for p in L.patterns if p != spec]
        elif spec not in L.patterns:
            L.patterns.append(spec)

def apply_alias(L, spec):
    if spec == 'default':
        return
    mode = None
    if spec and spec[0] in '+-':
        mode = spec[0]
        spec = spec[1:]
    if mode is None:
        L.aliases = []
    if mode == '-':
        L.aliases = [a for a in L.aliases if a != spec]
    elif spec not in L.aliases:
        L.aliases.append(spec)
