                warning('Unsupported parameter \'%s\' for "%s" option' % (item, optname))
                continue
        if target.fixed:
            if not en:
                warning('Cannot disable fixed field: \'%s\'{%s}' % (target.letter, target.name))
            continue
        target.enabled = en

def apply_lang_fields(L, spec, optname):
    langs = LANGS if L is None else [L]
    if spec_resets(spec):
        for LL in langs:
            for f in LL.fields:
                f.enabled = False
    for mode, item, isname in iter_spec(spec):
        en = (mode == '+')
        if item == '*' and not isname:
            for LL in langs:
                for f in LL.fields:
                    f.enabled = en
            continue
        if not isname:
            warning('only long name can be used in --%s option' % optname)
            continue
        found = False
        for LL in langs:
            f = LL.field(item)
            if f is not None:
                f.enabled = en
                found = True
        if not found:
            warning('Unsupported parameter \'{%s}\' for "%s" option' % (item, optname))

def apply_extras(spec, optname='extras'):
    if spec_resets(spec):
        for e in COMMON_EXTRAS:
            if not e.fixed:
                e.enabled = False
            if e.name == 'pseudo':
                EXTRAS_EXPLICIT['pseudo'] = True
    for mode, item, isname in iter_spec(spec):
        en = (mode == '+')
        if item == '*' and not isname:
            for e in COMMON_EXTRAS:
                e.enabled = en
            EXTRAS_EXPLICIT['pseudo'] = True
            continue
        target = None
        if isname:
            if '.' in item:
                lname, ename = item.split('.', 1)
                L = find_language(lname)
                if L is not None:
                    target = L.extra(ename)
            else:
                target = COMMON_EXTRA.get(item)
            if target is None:
                warning('Unsupported parameter \'{%s}\' for "%s" option' % (item, optname))
                continue
        else:
            for e in COMMON_EXTRAS:
                if e.letter == item:
                    target = e
                    break
            if target is None:
                warning('Unsupported parameter \'%s\' for "%s" option' % (item, optname))
                continue
        target.enabled = en
        if target.name == 'pseudo':
            EXTRAS_EXPLICIT['pseudo'] = True

def apply_lang_extras(L, spec, optname):
    langs = LANGS if L is None else [L]
    if spec_resets(spec):
        for LL in langs:
            for e in LL.extras:
                e.enabled = False
    for mode, item, isname in iter_spec(spec):
        en = (mode == '+')
        if item == '*' and not isname:
            for LL in langs:
                for e in LL.extras:
                    e.enabled = en
            continue
        found = False
        for LL in langs:
            for e in LL.extras:
                if (isname and e.name == item) or (not isname and e.letter == item and e.letter != '-'):
                    e.enabled = en
                    found = True
        if not found:
            if isname:
                warning('Unsupported parameter \'{%s}\' for "%s" option' % (item, optname))
            else:
                warning('Unsupported parameter \'%s\' for "%s" option' % (item, optname))

def apply_kinds(L, spec, optname):
    if spec_resets(spec):
        for k in L.kinds:
            k.enabled = False
    for mode, item, isname in iter_spec(spec):
        en = (mode == '+')
        if item == '*' and not isname:
            for k in L.kinds:
                k.enabled = en
            continue
        found = False
        for k in L.kinds:
            if (isname and k.name == item) or (not isname and k.letter == item):
                k.enabled = en
                found = True
        if not found:
            if isname:
                warning("Unsupported kind: '%s' for --%s option" % (item, optname))
            else:
                warning("Unsupported kind: '%s' for --%s option" % (item, optname))

def apply_roles(L, kspec, spec, optname):
    langs = LANGS if L is None else [L]
    for LL in langs:
        kinds = []
        if kspec == '*':
            kinds = LL.kinds
        else:
            for mode, item, isname in iter_spec(kspec):
                for k in LL.kinds:
                    if (isname and k.name == item) or (not isname and k.letter == item):
                        kinds.append(k)
        for k in kinds:
            if spec_resets(spec):
                for r in k.roles:
                    r.enabled = False
            for mode, item, isname in iter_spec(spec):
                en = (mode == '+')
                if item == '*' and not isname:
                    for r in k.roles:
                        r.enabled = en
                    continue
                if not isname:
                    error('unexpected character %s in --%s option' % (item, optname))
                r = k.role(item)
                if r is not None:
                    r.enabled = en

def set_lang_enabled(L, en):
    if en and L.name == 'Cargo':
        warning('Enabling Cargo subparser may enable TOML parser.')
    if en and L.name == 'TOML':
        warning('The current implementation of the TOML parser is broken.')
    L.enabled = en

def apply_languages(spec):
    items = spec.split(',')
    first = True
    for item in items:
        if item == '':
            continue
        mode = None
        if item[0] in '+-':
            mode = item[0]
            item = item[1:]
        if first and mode is None:
            warning('Enabling Cargo subparser may enable TOML parser.')
            warning('The current implementation of the TOML parser is broken.')
            for L in LANGS:
                L.enabled = False
        first = False
        en = (mode != '-')
        if item == 'all':
            if mode is not None:
                warning('Enabling Cargo subparser may enable TOML parser.')
                warning('The current implementation of the TOML parser is broken.')
            for L in LANGS:
                L.enabled = en
            continue
        L = find_language(item)
        if L is None:
            warning('Unknown language "%s" in "languages" option' % item)
            continue
        set_lang_enabled(L, en)

