    elif name == 'list-map-extensions': listing.list_maps(val, 'ext')
    elif name == 'list-map-patterns': listing.list_maps(val, 'pat')
    elif name == 'list-map-rexprs': listing.list_maps(val, 'rexpr')
    elif name == 'list-aliases': listing.list_aliases(val)
    elif name == 'list-params': listing.list_params(val)
    elif name == 'list-subparsers': listing.list_subparsers(val)
    elif name == 'list-pseudo-tags': listing.list_pseudo_tags()
    elif name == 'list-features': listing.list_features()
    elif name == 'list-output-formats': listing.list_output_formats()
