def process_long(arg, from_file=False):
    body = arg[2:]
    if '=' in body:
        name, val = body.split('=', 1)
    else:
        name, val = body, None
    import optlib
    # optlib family
    if optlib.handle_option(name, val):
        return
    if name in LIST_OPTIONS:
        if name == 'list-roles' and val is None:
            val = 'all'
        do_list(name, val)
        return
    if name == 'output-format':
        if val not in ('u-ctags', 'e-ctags', 'etags', 'xref', 'json'):
            errprint('%s: unknown output format name supplied for "output-format=%s"' % (core.PROGRAM, val))
            raise FatalError(None)
        OPT.out_format = val
        return
    if name == 'format':
        if val not in ('1', '2'):
            error('Unsupported value for "format" option')
        OPT.tag_file_format = int(val)
        return
    if name == 'sort':
        if val is None or val in ('yes', 'on', 'true', '1'):
            OPT.sort = 'yes'
        elif val in ('no', 'off', 'false', '0'):
            OPT.sort = 'no'
        elif val == 'foldcase':
            OPT.sort = 'foldcase'
        else:
            error('Invalid value for "sort" option')
        return
    if name == 'excmd':
        if val is None:
            error('Invalid value for "excmd" option: ')
        v = val
        if 'number'.startswith(v) and v: OPT.excmd = 'number'
        elif 'pattern'.startswith(v) and v: OPT.excmd = 'pattern'
        elif v in ('mix', 'mixed') or ('mix'.startswith(v) and v): OPT.excmd = 'mixed'
        elif 'combine'.startswith(v) and v: OPT.excmd = 'combine'
        else:
            error('Invalid value for "excmd" option: %s' % val)
        return
    if name == 'fields':
        apply_fields(val or '')
        return
    if name.startswith('fields-'):
        lname = name[7:]
        if lname == 'all':
            apply_lang_fields(None, val or '', name)
            return
        L = find_language(lname)
        if L is None:
            warning('Unknown language: %s (ignoring "--%s")' % (lname, name))
            return
        apply_lang_fields(L, val or '', name)
        return
    if name == 'extras' or name == 'extra':
        apply_extras(val or '', name)
        return
    if name.startswith('extras-'):
        lname = name[7:]
        if lname == 'all':
            apply_lang_extras(None, val or '', name)
            return
        L = find_language(lname)
        if L is None:
            warning('Unknown language: %s (ignoring "--%s")' % (lname, name))
            return
        apply_lang_extras(L, val or '', name)
        return
    if name.startswith('kinds-'):
        lname = name[6:]
        if lname == 'all':
            v = val or ''
            for mode, item, isname in iter_spec(v):
                if not ((item == '*' and not isname) or (item == 'F' and not isname) or (isname and item == 'file')):
                    error("only '*', 'F', \"{file}\" or their combination is acceptable as kind letter for --kinds-all")
            for mode, item, isname in iter_spec(v):
                if item == '*':
                    for L in LANGS:
                        for k in L.kinds:
                            k.enabled = (mode == '+')
            return
        L = find_language(lname)
        if L is None:
            warning('Unknown language "%s" in "%s" option' % (lname, name))
            return
        apply_kinds(L, val or '', name)
        return
    if name.endswith('-kinds'):
        lname = name[:-6]
        L = find_language(lname)
        if L is None:
            warning('Unknown language "%s" in "%s" option' % (lname, name))
            return
        apply_kinds(L, val or '', name)
        return
    if name.startswith('roles-'):
        rest = name[6:]
        if '.' not in rest:
            error('no kind is specified in --%s' % name)
        lname, kspec = rest.split('.', 1)
        L = None
        if lname != 'all':
            L = find_language(lname)
            if L is None:
                warning('Unknown language "%s" in "%s" option' % (lname, name))
                return
        if kspec != '*' and not kspec.startswith('{') and len(kspec) > 1:
            error("garbage after the kind specification '%s' in --%s option" % (kspec[0], name))
        apply_roles(L, kspec, val or '', name)
        return
    if name == 'languages':
        apply_languages(val or '')
        return
    if name == 'language-force':
        if val is None or val == 'auto':
            OPT.language_force = None
            return
        L = find_language(val)
        if L is None:
            error('Unknown language "%s" in "language-force" option' % val)
        OPT.language_force = L
        return
    if name == 'langmap':
        apply_langmap(val or '')
        return
    if name.startswith('map-'):
        L = find_language(name[4:])
        if L is None:
            error('Unknown language "%s" in "%s" option' % (name[4:], name))
        apply_map(L, val or '')
        return
    if name.startswith('alias-'):
        L = find_language(name[6:])
        if L is None:
            error('Unknown language "%s" in "%s" option' % (name[6:], name))
        apply_alias(L, val or '')
        return
    if name == 'guess-language-eagerly':
        OPT.guess_eagerly = True
        return
    if name in ('recurse',):
        OPT.recurse = bool_value(val, name)
        return
    if name == 'links':
        OPT.links = bool_value(val, name)
        return
    if name == 'maxdepth':
        try:
            OPT.maxdepth = int(val)
        except (TypeError, ValueError):
            error('-maxdepth: Invalid maxdepth')
        return
    if name == 'exclude':
        if val is None:
            return
        if val.startswith('@'):
            try:
                with open(val[1:], 'rb') as f:
                    for l in f.read().decode('latin-1').splitlines():
                        if l.strip():
                            core.EXCLUDES.append(l.strip())
            except OSError:
                error('cannot open "%s"' % val[1:])
        elif val == '':
            core.EXCLUDES = []
        else:
            core.EXCLUDES.append(val)
        return
    if name == 'exclude-exception':
        if val:
            OPT.exclude_exceptions.append(val)
        return
    if name == 'filter':
        OPT.filter = bool_value(val, name)
        return
    if name == 'filter-terminator':
        OPT.filter_terminator = val
        return
    if name == 'append':
        OPT.append = bool_value(val, name)
        return
    if name == 'tag-relative':
        if val is None or val in ('yes', 'on', 'true'):
            OPT.tag_relative = 'yes'
        elif val in ('no', 'off', 'false'):
            OPT.tag_relative = 'no'
        elif val in ('always', 'never'):
            OPT.tag_relative = val
        else:
            error('Invalid value for "tag-relative" option')
        return
    if name == 'pattern-length-limit':
        try:
            OPT.pattern_length_limit = int(val)
            if OPT.pattern_length_limit < 0:
                raise ValueError
        except (TypeError, ValueError):
            error('-pattern-length-limit: Invalid pattern length limit')
        return
    if name == 'pseudo-tags':
        v = val or ''
        if not v.startswith('+') and not v.startswith('-'):
            for k in PSEUDO_ENABLED:
                PSEUDO_ENABLED[k] = False
        mode = '+'
        for item in re.findall(r'[+-]|\{[^}]*\}|[^+-{]+', v):
            if item in '+-':
                mode = item
                continue
            nm = item.strip('{}')
            if nm == '*':
                for k in PSEUDO_ENABLED:
                    PSEUDO_ENABLED[k] = (mode == '+')
                continue
            if nm not in PSEUDO_ENABLED:
                error('Unknown pseudo tag name: %s' % nm)
            PSEUDO_ENABLED[nm] = (mode == '+')
        return
    if name == 'put-field-prefix':
        OPT.put_field_prefix = True
        return
    if name == 'etags-include':
        OPT.etags_include.append(val)
        return
    if name == 'input-encoding':
        OPT.input_encoding = val
        return
    if name.startswith('input-encoding-'):
        return
    if name == 'output-encoding':
        OPT.output_encoding = val
        if OPT.input_encoding is None:
            warning('--input-encoding is not specified')
        return
    if name == 'options' or name == 'options-maybe':
        if val == 'NONE':
            if not from_file and not getattr(OPT, 'options_none_seen', False):
                notice('No options will be read from files or environment')
            return
        read_options_path(val, name == 'options-maybe')
        return
    if name == 'optlib-dir':
        return
    if name == 'if0':
        OPT.if0 = bool_value(val, name)
        return
    if name == 'line-directives':
        OPT.line_directives = bool_value(val, name)
        return
    if name == 'machinable':
        OPT.machinable = bool_value(val, name)
        return
    if name == 'with-list-header':
        OPT.with_list_header = bool_value(val, name)
        return
    if name == 'print-language':
        OPT.print_language = True
        return
    if name == 'quiet':
        OPT.quiet = bool_value(val, name)
        return
    if name == 'verbose':
        OPT.verbose = bool_value(val, name)
        return
    if name == 'totals':
        if val is None or val in ('yes', 'on', 'true'):
            OPT.totals = 'yes'
        elif val == 'extra':
            OPT.totals = 'extra'
        elif val in ('no', 'off', 'false'):
            OPT.totals = None
        else:
            error('Invalid value for "totals" option')
        return
    if name.startswith('param-'):
        rest = name[6:]
        if '.' in rest:
            lname, pname = rest.split('.', 1)
