SHORT_WITH_ARG = set('fohIDLx') - set('x')

def process_short(args, i):
    """Process the short option at args[i]; returns new index."""
    arg = args[i]
    j = 1
    while j < len(arg):
        c = arg[j]
        if c in 'foLhID':
            rest = arg[j + 1:]
            if rest == '':
                i += 1
