import core

def fnmatch_cs(name, pat):
    return fnmatch.fnmatchcase(name, pat)

def candidates_by_name(name):
    """Return list of (Language, kind) where kind is 'pattern' or 'extension'."""
    base = os.path.basename(name)
    cands = []
    for L in LANGS:
        if not L.enabled:
            continue
        hit = None
        for p in L.patterns:
            if fnmatch_cs(base, p):
                hit = 'pattern'
                break
        if hit is None:
            dot = base.rfind('.')
            if dot >= 0:
                ext = base[dot + 1:]
                # extensions are compared case sensitively; also try multi-dot ext
                for e in L.extensions:
                    if e == ext:
                        hit = 'extension'
                        break
                if hit is None:
                    for e in L.extensions:
                        if '.' in e and base.endswith('.' + e):
                            hit = 'extension'
                            break
        if hit is None and L.rexprs:
            for rx, case in L.rexprs:
                try:
                    if re.search(rx, name, 0 if case == 'sensitive' else re.I):
                        hit = 'rexpr'
                        break
                except re.error:
                    pass
        if hit:
            cands.append((L, hit))
    if any(h == 'pattern' or h == 'rexpr' for _, h in cands):
        cands = [(L, h) for (L, h) in cands if h != 'extension']
    return cands

