"""Program entry point."""
import sys, os
import core
from core import *
import options
import detect

PARSERS = {}   # language name -> (module, function)

def register_parsers():
    import parsers
    for lname, spec in parsers.REGISTRY.items():
        PARSERS[lname] = spec

def get_parser(L):
    spec = PARSERS.get(L.name)
    if spec is None:
        return None
    if callable(spec):
        return spec
    mod, fn = spec
    m = __import__('parsers.' + mod, fromlist=[fn])
    f = getattr(m, fn)
    PARSERS[L.name] = f
    return f

def run_parser(ctx, L):
    import optlib
    f = get_parser(L)
    if f is not None:
        f(ctx)
    if L.optlib is not None:
        optlib.run_optlib(ctx, L)
    # subparsers that are regex based and attached to this base
    for (S, d) in L.subparsers:
        if S.enabled and S.optlib is not None and S.user_defined:
            ctx.cur_lang = S
            optlib.run_optlib(ctx, S)
            ctx.cur_lang = L

def tag_relative_mode():
    if OPT.tag_relative is not None:
        return OPT.tag_relative
    return 'yes' if OPT.out_format == 'etags' else 'no'

def out_path(path):
    mode = tag_relative_mode()
    if mode == 'no':
        return path
    if mode == 'never':
        if os.path.isabs(path):
            return path
        return os.path.normpath(os.path.join(os.getcwd(), path))
    if OUT.stdout:
        return path
    if mode == 'yes' and os.path.isabs(path):
        return path
    tagdir = os.path.dirname(os.path.abspath(OUT.path))
    ap = os.path.abspath(path)
    try:
        return os.path.relpath(ap, tagdir)
    except ValueError:
        return path

def qualified_allowed(L):
    return getattr(L, 'qualified', False)

def flush_ctx(ctx):
    OUT.begin_file(ctx)
    qual = extra_enabled('qualified')
    for t in ctx.cork[1:]:
        if t is None:
            continue
        if tag_writable(t):
            OUT.write_tag(t)
            if qual and not t.skip_qualified and qualified_allowed(t.lang):
                k, s = tag_scope(t)
                if s is not None:
                    q = copy_tag(t)
                    q.name = full_name(t)
                    q.add_extra('qualified')
                    if tag_writable(q):
                        OUT.write_tag(q)
    if extra_enabled('inputFile') and OPT.out_format != 'xref':
        ft = Tag(os.path.basename(ctx.path), FILE_KIND, ctx.lang, 1)
        ft.ctx = ctx
        ft.line_entry = True
        ft.end = ctx.nlines
        ft.epoch = int(ctx.mtime)
        ft.add_extra('inputFile')
        OUT.write_tag(ft)
    OUT.end_file(ctx)

def copy_tag(t):
    q = Tag(t.name, t.kind, t.lang, t.line)
    for s in Tag.__slots__:
        try:
            setattr(q, s, getattr(t, s))
        except AttributeError:
            pass
    q.extras = list(t.extras) if t.extras else None
    return q

def read_input(path):
    with open(path, 'rb') as f:
        data = f.read()
    return data.decode('latin-1')

STATS = {'files': 0, 'lines': 0, 'bytes': 0}

def parse_file(path, L=None):
    if L is None:
        L = detect.get_file_language(path)
    if OPT.print_language:
        write_out('%s: %s\n' % (path, L.name if L is not None else 'NONE'))
        return
    if L is None:
        return
    try:
        text = read_input(path)
        mtime = os.stat(path).st_mtime
    except OSError as e:
        warning('cannot open input file "%s" : %s' % (path, e.strerror))
        return
    ctx = ParserContext(L, path, text, out_path(path), mtime)
    STATS['files'] += 1
    STATS['lines'] += ctx.nlines
    STATS['bytes'] += len(text)
    OUT.lang_ptags(L)
    try:
        run_parser(ctx, L)
    except RecursionError:
        pass
    flush_ctx(ctx)

def excluded(path, name):
    for p in core.EXCLUDES:
        if detect.fnmatch_cs(name, p) or ('/' in p and detect.fnmatch_cs(path, p)):
            for e in OPT.exclude_exceptions:
                if detect.fnmatch_cs(name, e) or detect.fnmatch_cs(path, e):
                    return False
            return True
    return False

def join_path(d, n):
    if d == '.':
        return n
    if d.endswith('/'):
        return d + n
    return d + '/' + n

def recurse_dir(d, depth):
    if OPT.maxdepth is not None and depth >= OPT.maxdepth:
        return
    try:
        names = os.listdir(d)
    except OSError as e:
        warning('cannot open directory "%s" : %s' % (d, e.strerror))
        return
    for n in names:
        if n in ('.', '..'):
            continue
        p = join_path(d, n)
        if excluded(p, n):
            continue
        if os.path.islink(p) and not OPT.links:
            continue
        if os.path.isdir(p):
            recurse_dir(p, depth + 1)
        elif os.path.isfile(p):
            parse_file(p)

def process_file_arg(arg):
    if not os.path.exists(arg) and not os.path.islink(arg):
        warning('cannot open input file "%s" : No such file or directory' % arg)
        return
    name = os.path.basename(arg.rstrip('/')) or arg
    if os.path.isdir(arg):
        if OPT.recurse:
            if excluded(arg, name) and arg not in ('.',):
                return
            recurse_dir(arg, 0)
        else:
            if OPT.verbose:
                pass
            notice_dir(arg)
        return
