    """Scan from s[i] (after a separator) to next separator. Returns (text, newindex or None)."""
    out = []
    quoted = False
    n = len(s)
    while i < n:
        c = s[i]
        if quoted:
            if c == sep:
                out.append(sep)
            elif c == 't':
                out.append('\t')
            elif multiline and c == 'n':
                out.append('\n')
            else:
                out.append('\\'); out.append(c)
            quoted = False
        elif c == '\\':
            quoted = True
        elif c == sep:
            return ''.join(out), i
        else:
            out.append(c)
        i += 1
    if quoted:
        out.append('\\')
    return ''.join(out), None

