            p.fatal = (v or '').strip('"')
        elif k == 'warning':
            p.warning = (v or '').strip('"')
        elif k == '_language':
            p.lang = v
        elif k == 'postrun':
            p.postrun = True
        elif k == '_guest':
            pass
        else:
            warning('Unknown flag specified in %s: %s' % (ctxname, k))

def parse_regex_option(L, val, kind_mode, optname, table=None):
    """kind_mode: 'line', 'mline', 'mtable'."""
    if not val:
        error('empty regex in --%s' % optname)
    sep = val[0]
    multiline = kind_mode != 'line'
    rx, i = scan_sep(val, 1, sep, multiline)
    if i is None:
        error('%s: Regex pattern is not terminated: %s' % (L.name, val)) if False else None
        warning('%s: Regular expression pattern is not terminated: %s' % (L.name, val))
        return None
    name, j = scan_sep(val, i + 1, sep, multiline)
    if j is None:
        # no kind spec; name till end
        kspec = ''
        flagstr = ''
    else:
        kspec, k = scan_sep(val, j + 1, sep, multiline)
        if k is None:
            flagstr = ''
        else:
            flagstr = val[k + 1:]
    flags = parse_flags(flagstr)
    p = compile_pat(L, rx, flags, multiline)
    p.name = name
    has_kind = (kspec != '' or name != '')
    if kspec == '' and name == '':
        p.kind = None
    else:
        p.kind = parse_kind_spec(L, kspec)
    apply_pat_flags(L, p, flags, optname)
    p.source = val
    return p

def find_lang_or_warn(lname, optname):
    L = find_language(lname)
    if L is None:
        error('Unknown language "%s" in "%s" option' % (lname, optname))
    return L

def parse_langdef(val):
    name = val
    flags = []
    if '{' in val:
        name = val[:val.index('{')]
        flags = parse_flags(val[val.index('{'):])
    if find_language(name) is not None:
        error('Language "%s" already defined' % name)
    if not name:
        error('No language specified for "langdef" option')
    L = Language(name)
    L.user_defined = True
    L.version = '0.0'
    L.rebuild()
    get_def(L)
    for k, v in flags:
        if k == 'base':
            B = find_language(v)
            if B is None:
                error('Unknown language "%s" in "langdef" option' % v)
            L.base = B
            B.subparsers.append((L, 'base <> sub {bidirectional}'))
            L.direction = 'base <> sub {bidirectional}'
        elif k in ('dedicated', 'shared', 'bidirectional'):
            d = {'dedicated': 'base <= sub {dedicated}', 'shared': 'base => sub {shared}',
                 'bidirectional': 'base <> sub {bidirectional}'}[k]
            L.direction = d
            if L.base is not None:
                L.base.subparsers = [(S, dd if S is not L else d) for (S, dd) in L.base.subparsers]
        elif k == 'version':
            L.version = v
        elif k == '_autoFQTag':
            L.qualified = True
        elif k == '_foreignLanguage':
            pass
    add_language(L)
    return L

def handle_option(name, val):
    if name == 'langdef':
        parse_langdef(val or '')
        return True
    for prefix, mode in (('regex-', 'line'), ('mline-regex-', 'mline')):
        if name.startswith(prefix):
            lname = name[len(prefix):]
            L = find_lang_or_warn(lname, name)
            p = parse_regex_option(L, val or '', mode, name)
            if p is None:
                return True
            d = get_def(L)
            if mode == 'line':
                d.line.append(p)
            else:
                if p.mgroup is None:
                    warning('%s: no {mgroup=N} flag given in --mline-regex-<LANG>=%s... (addTagRegexOption)' % (L.name, val))
                    p.mgroup = 0
                d.mline.append(p)
            return True
    if name.startswith('kinddef-'):
        L = find_lang_or_warn(name[8:], name)
        v = val or ''
        flags = []
        if '{' in v:
            flags = parse_flags(v[v.index('{'):])
            v = v[:v.index('{')]
        parts = v.split(',', 2)
        if len(parts) < 2:
            error('no kind name specified in "--%s" option' % name)
        letter = parts[0]
        kname = parts[1]
        desc = parts[2] if len(parts) > 2 else kname
        k = define_kind(L, letter, kname, desc)
        for fk, fv in flags:
            if fk == '_refonly':
                k.refonly = True
            elif fk == 'version':
                try: k.ver = int(fv)
                except ValueError: pass
        return True
    if name.startswith('_tabledef-'):
        L = find_lang_or_warn(name[10:], name)
        d = get_def(L)
        if val not in d.tables:
            d.tables[val] = []
            d.table_order.append(val)
        return True
    if name.startswith('_mtable-regex-'):
        L = find_lang_or_warn(name[14:], name)
        d = get_def(L)
        v = val or ''
        if '/' not in v:
            error('no table name in --%s' % name)
        tname, rest = v.split('/', 1)
        if tname not in d.tables:
            error('no such regex table in %s: %s' % (L.name, tname))
        p = parse_regex_option(L, '/' + rest, 'mtable', name, tname)
        if p is not None:
            d.tables[tname].append(p)
        return True
    if name.startswith('_mtable-extend-'):
        L = find_lang_or_warn(name[15:], name)
        d = get_def(L)
        dst, src = (val or '').split('+', 1)
        if dst in d.tables and src in d.tables:
            d.tables[dst].extend(('__extend__', src) for _ in [0])
        return True
    if name.startswith('_fielddef-'):
        L = find_lang_or_warn(name[10:], name)
        v = val or ''
        flags = []
        if '{' in v:
            flags = parse_flags(v[v.index('{'):])
            v = v[:v.index('{')]
        fname, desc = (v.split(',', 1) + [''])[:2]
        f = Field('-', fname, True, 's--', False, '--', 0, desc, L)
        for fk, fv in flags:
            if fk == 'datatype':
                f.datatype = fv
                f.jstype = {'str': 's--', 'int': '-i-', 'bool': '--b', 'str+bool': 's-b'}.get(fv, 's--')
        L.fields.append(f)
        return True
    if name.startswith('_extradef-'):
        L = find_lang_or_warn(name[10:], name)
        v = val or ''
        if '{' in v:
            v = v[:v.index('{')]
        ename, desc = (v.split(',', 1) + [''])[:2]
        L.extras.append(Extra('-', ename, False, False, 0, desc, L))
        return True
    if name.startswith('_roledef-'):
        rest = name[9:]
        lname, kspec = rest.split('.', 1)
        L = find_lang_or_warn(lname, name)
        k = L.kind(kspec.strip('{}'))
        if k is None:
            error('no such kind: %s' % kspec)
        v = val or ''
        if '{' in v:
            v = v[:v.index('{')]
        rname, desc = (v.split(',', 1) + [''])[:2]
        r = Role(rname, True, 0, desc)
        r.kind = k
        k.roles.append(r)
        return True
    if name.startswith('_paramdef-'):
        L = find_lang_or_warn(name[10:], name)
        pname, desc = ((val or '').split(',', 1) + [''])[:2]
        L.params.append(Param(pname, desc))
        return True
    if name.startswith('_scopesep-'):
        L = find_lang_or_warn(name[10:], name)
        v = val or ''
        if ':' in v:
            kinds, sep = v.split(':', 1)
            if '/' in kinds:
                pk, ck = kinds.split('/', 1)
            else:
                pk, ck = '*', kinds
            L.scope_seps[(pk, ck)] = sep
        return True
    if name.startswith('_pretend-'):
        N = find_lang_or_warn(name[9:], name)
        O = find_lang_or_warn(val or '', name)
        N.pretend = O
        return True
    if name.startswith('_prelude-') or name.startswith('_sequel-'):
        return True
    return False

def init_builtin():
    import builtin_optlib
    builtin_optlib.install()

# ---------------------------------------------------------------------------
# running

def expand(template, text, m, base=0):
    out = []
    i = 0
    n = len(template)
    while i < n:
        c = template[i]
        if c == '\\' and i + 1 < n:
            d = template[i + 1]
            if '0' <= d <= '9':
                g = int(d)
                if g < len(m) and m[g][0] >= 0:
                    if g == 0:
                        pass
                    else:
                        out.append(text[m[g][0]:m[g][1]])
                i += 2
                continue
            out.append(d)
            i += 2
            continue
        out.append(c)
        i += 1
    return ''.join(out)

def do_search(p, text, start=0, end=None, anchored_sub=False):
    if p.regex is not None:
        if anchored_sub:
            sub = text[start:end] if end is not None else text[start:]
            m = p.regex.search(sub)
            if m is None:
                return None
            return [(a + start, b + start) if a >= 0 else (-1, -1) for a, b in m]
        return p.regex.search(text, start, end)
    else:
        b = text.encode('latin-1')
        mm = p.pyre.search(b, start, end if end is not None else len(b))
        if mm is None:
            return None
        res = []
        for g in range(10):
            if g <= p.pyre.groups:
                res.append(mm.span(g))
            else:
                res.append((-1, -1))
        return res

class RegexState:
    def __init__(self, ctx, L):
        self.ctx = ctx
        self.L = L
        self.scope_stack = []
        self.anon = {}

def make_regex_tag(st, p, text, m, line, lineoff=None, pos=None):
    ctx = st.ctx
    L = st.L
    action = p.scope
    if p.fatal is not None:
        errprint(p.fatal)
        raise FatalError(None)
    if p.warning is not None:
        warning(p.warning)
    if action in ('pop', 'clear') :
        if action == 'pop':
            if st.scope_stack:
                idx = st.scope_stack.pop()
                t = ctx.cork[idx]
                if t is not None and not t.end:
                    t.end = line
        else:
            while st.scope_stack:
                idx = st.scope_stack.pop()
                t = ctx.cork[idx]
                if t is not None and not t.end:
                    t.end = line
        if p.kind is None or (p.name == '' and p.anonymous is None):
            return None
    if p.kind is None:
        return None
    if p.anonymous is not None:
        n = st.anon.get(p.anonymous, 0) + 1
        st.anon[p.anonymous] = n
        name = anon_name(p.anonymous, L, n)
    else:
        name = expand(p.name, text, m)
        name = name.strip(' \t\n\r\f\v')
    if name == '' and not p.placeholder:
        if not (action == 'pop' or action == 'clear'):
            warning('%s:%d: null expansion of name pattern "%s"' % (ctx.path, line, p.name))
        return None
    kind = p.kind
    tlang = L
    if p.lang:
        FL = find_language(p.lang)
        if FL is not None:
            tlang = FL
    idx = ctx.make_tag(name, kind, line=line, lang=L)
    t = ctx.cork[idx]
    if p.placeholder:
        t.placeholder = True
    if action in ('ref', 'push', 'set', 'replace') or action is None:
        if action == 'set':
            while st.scope_stack:
                st.scope_stack.pop()
        if action == 'replace':
            if st.scope_stack:
                old = st.scope_stack.pop()
                ot = ctx.cork[old]
                if ot is not None and not ot.end:
                    ot.end = line
        if action in ('ref', 'push', 'replace') and st.scope_stack:
            t.scope = st.scope_stack[-1]
        if action in ('push', 'set', 'replace'):
            st.scope_stack.append(idx)
    for fn, fv in p.fields:
        val = expand(fv, text, m)
        if not t.set_field(fn, val, L):
            # maybe a common field
            if fn == 'signature':
                warning('no such field "%s" in %s' % (fn, L.name))
            else:
                warning('no such field "%s" in %s' % (fn, L.name))
    for r in p.roles:
        t.add_role(r)
    if p.extra:
        t.add_extra(p.extra)
    if p.anonymous is not None:
        t.add_extra('anonymous')
    if L.base is not None and L.user_defined and False:
        t.add_extra('subparser')
    return idx

def anon_name(prefix, L, n):
    import hashlib
    return '%s%s' % (prefix, anon_hash(L, n))

_anon_counter = [0]
def anon_hash(L, n):
    # mimic ctags: prefix + hash of input file name + counter
    return '%08x%02x' % (0, n)

def run_line_regexes(ctx, L, d, st=None):
    if st is None:
        st = RegexState(ctx, L)
    pats = [p for p in d.line if not p.postrun]
    if not pats:
        return st
    text = ctx.text
    for lineno, line in ctx.lines():
        for p in pats:
            m = do_search(p, line)
            if m is None:
                continue
            make_regex_tag(st, p, line, m, lineno)
            if p.exclusive:
                break
    return st

def run_mline_regexes(ctx, L, d):
    text = ctx.text
    st = RegexState(ctx, L)
    for p in d.mline:
        pos = 0
        n = len(text)
        while pos <= n:
            m = do_search(p, text, pos)
            if m is None:
                break
            g = p.mgroup if p.mgroup is not None and p.mgroup < len(m) and m[p.mgroup][0] >= 0 else 0
            line = ctx.line_of(m[g][0])
            make_regex_tag(st, p, text, m, line)
            newpos = advance_pos(p, m)
            if newpos <= pos and m[0][1] == m[0][0]:
                newpos = pos + 1
            pos = max(newpos, pos + (1 if m[0][1] == pos else 0)) if newpos <= pos else newpos
    return st

def advance_pos(p, m):
    if p.advance:
        a = p.advance
        mm = re.match(r'(\d+)(start|end)?$', a)
        if mm:
            g = int(mm.group(1))
            which = mm.group(2) or 'end'
            if g < len(m) and m[g][0] >= 0:
                return m[g][0] if which == 'start' else m[g][1]
    return m[0][1]

def run_mtable(ctx, L, d):
    if not d.table_order:
        return
    text = ctx.text
    n = len(text)
    st = RegexState(ctx, L)
    stack = []
    cur = d.table_order[0]
    pos = 0
    guard = 0
    while pos < n:
        guard += 1
        if guard > 10 * n + 1000:
            break
        pats = expand_table(d, cur)
        matched = False
        for p in pats:
            m = do_search(p, text, pos, anchored_sub=True)
            if m is None:
                continue
            if m[0][0] != pos and False:
                continue
            matched = True
            g = p.mgroup if p.mgroup is not None and p.mgroup < len(m) and m[p.mgroup][0] >= 0 else 0
            line = ctx.line_of(m[g][0]) if m[g][0] < n else ctx.line_of(max(0, n - 1))
            if p.kind is not None or p.scope:
                make_regex_tag(st, p, text, m, line)
            newpos = advance_pos(p, m)
            act = p.taction
            if act == 'tenter':
                stack.append((cur, p.tcont))
                cur = p.ttable
            elif act == 'tleave':
                if stack:
                    cur, cont = stack.pop()
                    if cont:
                        cur = cont
                else:
                    pass
            elif act == 'tjump':
                cur = p.ttable
            elif act == 'treset':
                stack = []
                cur = p.ttable
            elif act == 'tquit':
                return
            if newpos == pos and act is None:
                newpos = pos + 1
            pos = newpos
            break
        if not matched:
            pos += 1
            if stack and False:
                cur, _ = stack.pop()
    return

def expand_table(d, name, seen=None):
    out = []
    for p in d.tables.get(name, []):
        if isinstance(p, tuple):
            if seen is None:
                seen = set()
            if p[1] in seen:
                continue
            seen.add(p[1])
            out.extend(expand_table(d, p[1], seen))
        else:
            out.append(p)
    return out

def run_optlib(ctx, L):
    d = L.optlib
    if d is None:
        return
    saved = ctx.cur_lang
    ctx.cur_lang = L
    try:
        run_line_regexes(ctx, L, d)
        if d.mline:
            run_mline_regexes(ctx, L, d)
        if d.table_order:
            run_mtable(ctx, L, d)
        post = [p for p in d.line if p.postrun]
        if post:
            st = RegexState(ctx, L)
            for lineno, line in ctx.lines():
                for p in post:
                    m = do_search(p, line)
                    if m is None:
                        continue
                    make_regex_tag(st, p, line, m, lineno)
                    if p.exclusive:
                        break
    finally:
        ctx.cur_lang = saved
