"""Regex based (optlib) parser engine: --langdef, --regex-<LANG>, --mline-regex-<LANG>, mtable."""
import re
from core import *
import core
import posixre

class Pat:
    def __init__(self):
        self.regex = None
        self.pyre = None
        self.name = ''
        self.kind = None
        self.exclusive = False
        self.placeholder = False
        self.scope = None
