        L.optlib = OptlibDef()
    return L.optlib

# ---------------------------------------------------------------------------
# option parsing

def scan_sep(s, i, sep, multiline):
    """Scan from s[i] (after a separator) to next separator. Returns (text, newindex or None)."""
    out = []
    quoted = False
    n = len(s)
    while i < n:
        c = s[i]
        if quoted:
            if c == sep:
                out.append(sep)
            elif c == 't':
                out.append('\t')
            elif multiline and c == 'n':
                out.append('\n')
            else:
                out.append('\\'); out.append(c)
            quoted = False
        elif c == '\\':
            quoted = True
        elif c == sep:
            return ''.join(out), i
        else:
            out.append(c)
        i += 1
    if quoted:
        out.append('\\')
    return ''.join(out), None

def parse_flags(s):
    """Parse a flags string like 'ix{scope=push}{_field=a:\\1}' -> list of (name, value)."""
    out = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c == '{':
            # find matching } (allow quoted strings)
            j = i + 1
            depth = 0
            inq = False
            while j < n:
                if s[j] == '"' :
                    inq = not inq
                elif s[j] == '\\' and inq:
                    j += 1
                elif s[j] == '}' and not inq:
                    break
                j += 1
            body = s[i + 1:j]
            if '=' in body:
                k, v = body.split('=', 1)
            else:
                k, v = body, None
            out.append((k, v))
            i = j + 1
        else:
            out.append((c, None))
            i += 1
    return out

def define_kind(L, letter, name, desc, warn=True):
    for k in L.kinds:
        if k.letter == letter:
            if name is not None and k.name != name and warn:
                warning("Don't reuse the kind letter `%s' in a language %s (old: \"%s\", new: \"%s\")" % (letter, L.name, k.name, name))
            return k
    if name is None:
        name = 'regex'
    if desc is None:
        desc = name
    for k in L.kinds:
        if k.name == name and warn and name != 'regex':
            warning("Don't reuse the kind name `%s' in a language %s (old: \"%s\", new: \"%s\")" % (name, L.name, k.letter, letter))
            return k
    k = Kind(letter, name, True, False, 'NONE', 0, desc)
    L.kinds.append(k)
    L.rebuild()
    return k

def parse_kind_spec(L, spec):
    if spec is None or spec == '':
        return define_kind(L, 'r', 'regex', 'regex', warn=False)
    parts = spec.split(',', 2)
    letter = parts[0]
    name = parts[1] if len(parts) > 1 else None
    desc = parts[2] if len(parts) > 2 else None
    if letter.startswith('{') and letter.endswith('}'):
        k = L.kind(letter[1:-1])
        if k is None:
            error('no such kind %s' % letter)
        return k
    if len(letter) != 1:
        return define_kind(L, letter[0], name, desc)
    return define_kind(L, letter, name, desc)

def compile_pat(L, rx, flags, multiline):
    extended = True
    icase = False
    pcre = False
    for k, v in flags:
        if k == 'b' or k == 'basic': extended = False
        elif k == 'e' or k == 'extend': extended = True
        elif k == 'i' or k == 'icase': icase = True
        elif k == 'p' or k == 'pcre2': pcre = True
    p = Pat()
    p.icase = icase
    if pcre:
        try:
            p.pyre = re.compile(rx.encode('latin-1'), (re.I if icase else 0) | re.M)
        except re.error as e:
            error('regex compile error: %s' % e)
    else:
        try:
            p.regex = posixre.Regex(rx, extended=extended, icase=icase, newline=True)
        except posixre.RegexError as e:
            errprint('%s: regcomp %s: %s' % (core.PROGRAM, rx, e))
            raise FatalError(None)
    return p

def apply_pat_flags(L, p, flags, ctxname):
    for k, v in flags:
        if k in ('b', 'e', 'i', 'p', 'basic', 'extend', 'icase', 'pcre2'):
            continue
        if k == 'x' or k == 'exclusive':
            p.exclusive = True
        elif k == 'placeholder':
            p.placeholder = True
        elif k == 'scope':
            p.scope = v
        elif k == '_field':
            if v and ':' in v:
                fn, fv = v.split(':', 1)
                p.fields.append((fn, fv))
        elif k == '_role':
            p.roles.append(v)
        elif k == '_extra':
            p.extra = v
        elif k == '_anonymous':
            p.anonymous = v or ''
        elif k == 'mgroup':
            try:
                p.mgroup = int(v)
            except (TypeError, ValueError):
                pass
        elif k == '_advanceTo':
            p.advance = v
        elif k in ('tenter', 'tjump', 'treset'):
            p.taction = k
            if v and ',' in v:
                p.ttable, p.tcont = v.split(',', 1)
            else:
                p.ttable = v
        elif k in ('tleave', 'tquit'):
            p.taction = k
        elif k == 'fatal':
            p.fatal = (v or '').strip('"')
        elif k == 'warning':
            p.warning = (v or '').strip('"')
        elif k == '_language':
            p.lang = v
        elif k == 'postrun':
            p.postrun = True
        elif k == '_guest':
            pass
        else:
            warning('Unknown flag specified in %s: %s' % (ctxname, k))

def parse_regex_option(L, val, kind_mode, optname, table=None):
    """kind_mode: 'line', 'mline', 'mtable'."""
    if not val:
        error('empty regex in --%s' % optname)
    sep = val[0]
    multiline = kind_mode != 'line'
    rx, i = scan_sep(val, 1, sep, multiline)
    if i is None:
        error('%s: Regex pattern is not terminated: %s' % (L.name, val)) if False else None
        warning('%s: Regular expression pattern is not terminated: %s' % (L.name, val))
        return None
    name, j = scan_sep(val, i + 1, sep, multiline)
    if j is None:
        # no kind spec; name till end
        kspec = ''
        flagstr = ''
    else:
        kspec, k = scan_sep(val, j + 1, sep, multiline)
        if k is None:
            flagstr = ''
        else:
            flagstr = val[k + 1:]
    flags = parse_flags(flagstr)
    p = compile_pat(L, rx, flags, multiline)
    p.name = name
    has_kind = (kspec != '' or name != '')
    if kspec == '' and name == '':
        p.kind = None
    else:
        p.kind = parse_kind_spec(L, kspec)
    apply_pat_flags(L, p, flags, optname)
    p.source = val
    return p

def find_lang_or_warn(lname, optname):
    L = find_language(lname)
    if L is None:
        error('Unknown language "%s" in "%s" option' % (lname, optname))
    return L

def parse_langdef(val):
    name = val
    flags = []
    if '{' in val:
        name = val[:val.index('{')]
        flags = parse_flags(val[val.index('{'):])
    if find_language(name) is not None:
        error('Language "%s" already defined' % name)
    if not name:
        error('No language specified for "langdef" option')
    L = Language(name)
    L.user_defined = True
    L.version = '0.0'
    L.rebuild()
    get_def(L)
    for k, v in flags:
        if k == 'base':
            B = find_language(v)
            if B is None:
                error('Unknown language "%s" in "langdef" option' % v)
            L.base = B
            B.subparsers.append((L, 'base <> sub {bidirectional}'))
            L.direction = 'base <> sub {bidirectional}'
        elif k in ('dedicated', 'shared', 'bidirectional'):
            d = {'dedicated': 'base <= sub {dedicated}', 'shared': 'base => sub {shared}',
                 'bidirectional': 'base <> sub {bidirectional}'}[k]
            L.direction = d
            if L.base is not None:
                L.base.subparsers = [(S, dd if S is not L else d) for (S, dd) in L.base.subparsers]
        elif k == 'version':
            L.version = v
        elif k == '_autoFQTag':
            L.qualified = True
        elif k == '_foreignLanguage':
            pass
    add_language(L)
    return L

def handle_option(name, val):
    if name == 'langdef':
        parse_langdef(val or '')
        return True
    for prefix, mode in (('regex-', 'line'), ('mline-regex-', 'mline')):
        if name.startswith(prefix):
            lname = name[len(prefix):]
            L = find_lang_or_warn(lname, name)
            p = parse_regex_option(L, val or '', mode, name)
            if p is None:
                return True
            d = get_def(L)
            if mode == 'line':
                d.line.append(p)
            else:
                if p.mgroup is None:
                    warning('%s: no {mgroup=N} flag given in --mline-regex-<LANG>=%s... (addTagRegexOption)' % (L.name, val))
                    p.mgroup = 0
                d.mline.append(p)
            return True
    if name.startswith('kinddef-'):
        L = find_lang_or_warn(name[8:], name)
        v = val or ''
        flags = []
        if '{' in v:
            flags = parse_flags(v[v.index('{'):])
            v = v[:v.index('{')]
        parts = v.split(',', 2)
        if len(parts) < 2:
            error('no kind name specified in "--%s" option' % name)
        letter = parts[0]
        kname = parts[1]
        desc = parts[2] if len(parts) > 2 else kname
        k = define_kind(L, letter, kname, desc)
        for fk, fv in flags:
            if fk == '_refonly':
                k.refonly = True
            elif fk == 'version':
                try: k.ver = int(fv)
                except ValueError: pass
        return True
    if name.startswith('_tabledef-'):
        L = find_lang_or_warn(name[10:], name)
        d = get_def(L)
        if val not in d.tables:
            d.tables[val] = []
            d.table_order.append(val)
        return True
    if name.startswith('_mtable-regex-'):
        L = find_lang_or_warn(name[14:], name)
        d = get_def(L)
        v = val or ''
        if '/' not in v:
            error('no table name in --%s' % name)
        tname, rest = v.split('/', 1)
        if tname not in d.tables:
            error('no such regex table in %s: %s' % (L.name, tname))
        p = parse_regex_option(L, '/' + rest, 'mtable', name, tname)
        if p is not None:
            d.tables[tname].append(p)
        return True
    if name.startswith('_mtable-extend-'):
        L = find_lang_or_warn(name[15:], name)
        d = get_def(L)
        dst, src = (val or '').split('+', 1)
        if dst in d.tables and src in d.tables:
            d.tables[dst].extend(('__extend__', src) for _ in [0])
        return True
    if name.startswith('_fielddef-'):
        L = find_lang_or_warn(name[10:], name)
        v = val or ''
        flags = []
        if '{' in v:
            flags = parse_flags(v[v.index('{'):])
            v = v[:v.index('{')]
        fname, desc = (v.split(',', 1) + [''])[:2]
        f = Field('-', fname, True, 's--', False, '--', 0, desc, L)
        for fk, fv in flags:
            if fk == 'datatype':
                f.datatype = fv
                f.jstype = {'str': 's--', 'int': '-i-', 'bool': '--b', 'str+bool': 's-b'}.get(fv, 's--')
        L.fields.append(f)
        return True
    if name.startswith('_extradef-'):
        L = find_lang_or_warn(name[10:], name)
        v = val or ''
        if '{' in v:
            v = v[:v.index('{')]
        ename, desc = (v.split(',', 1) + [''])[:2]
        L.extras.append(Extra('-', ename, False, False, 0, desc, L))
        return True
    if name.startswith('_roledef-'):
        rest = name[9:]
        lname, kspec = rest.split('.', 1)
        L = find_lang_or_warn(lname, name)
        k = L.kind(kspec.strip('{}'))
        if k is None:
            error('no such kind: %s' % kspec)
        v = val or ''
        if '{' in v:
            v = v[:v.index('{')]
        rname, desc = (v.split(',', 1) + [''])[:2]
        r = Role(rname, True, 0, desc)
        r.kind = k
        k.roles.append(r)
        return True
    if name.startswith('_paramdef-'):
        L = find_lang_or_warn(name[10:], name)
        pname, desc = ((val or '').split(',', 1) + [''])[:2]
        L.params.append(Param(pname, desc))
        return True
    if name.startswith('_scopesep-'):
        L = find_lang_or_warn(name[10:], name)
        v = val or ''
        if ':' in v:
            kinds, sep = v.split(':', 1)
            if '/' in kinds:
                pk, ck = kinds.split('/', 1)
            else:
                pk, ck = '*', kinds
            L.scope_seps[(pk, ck)] = sep
        return True
    if name.startswith('_pretend-'):
        N = find_lang_or_warn(name[9:], name)
        O = find_lang_or_warn(val or '', name)
        N.pretend = O
        return True
    if name.startswith('_prelude-') or name.startswith('_sequel-'):
        return True
    return False

