        return '%s:%r' % (self.t, self.v)

OPS3 = ('**=', '//=', '>>=', '<<=', '...', '!=')
OPS2 = ('**', '//', '>>', '<<', '<=', '>=', '==', '!=', '->', '+=', '-=', '*=', '/=', '%=', '&=', '|=', '^=', '@=', ':=')

def is_id_start(c):
    return c == '_' or isalpha(c) or ord(c) >= 0x80

def is_id_char(c):
    return c == '_' or isalnum(c) or ord(c) >= 0x80

def tokenize(text):
    """Yield logical lines: (indent, tokens). Each token: Tok."""
    i = 0
    n = len(text)
    line = 1
    depth = 0
    lines = []
    cur = []
    indent = 0
    at_bol = True
    ws = False
    while i < n:
        c = text[i]
        if at_bol and depth == 0:
            # compute indentation
            col = 0
            j = i
            while j < n and text[j] in ' \t\f':
                if text[j] == '\t':
                    col = (col // 8 + 1) * 8
                elif text[j] == ' ':
                    col += 1
                j += 1
            if j >= n:
                break
            if text[j] == '\n' or text[j] == '#' or text[j] == '\r':
                # blank or comment line
                k = text.find('\n', j)
                if k < 0:
                    break
                i = k + 1
                line += 1
                continue
            if text[j] == '\\' and j + 1 < n and text[j + 1] == '\n':
                i = j + 2
                line += 1
                continue
            indent = col
            i = j
            at_bol = False
            ws = False
            continue
        if c == ' ' or c == '\t' or c == '\f' or c == '\r':
            i += 1
            ws = True
            continue
        if c == '\n':
            line += 1
            i += 1
            if depth > 0:
                ws = True
                continue
            if cur:
                lines.append((indent, cur))
                cur = []
            at_bol = True
            continue
        if c == '#':
            k = text.find('\n', i)
            if k < 0:
                i = n
            else:
                i = k
            ws = True
            continue
        if c == '\\' and i + 1 < n and text[i + 1] in '\r\n':
            i += 1
            if text[i] == '\r':
                i += 1
            if i < n and text[i] == '\n':
                i += 1
            line += 1
            ws = True
            continue
        start = i
        sline = line
        if is_id_start(c):
            j = i + 1
            while j < n and is_id_char(text[j]):
                j += 1
            word = text[i:j]
            # string prefix?
            if j < n and text[j] in '\'"' and len(word) <= 2 and ascii_lower(word) in ('r', 'u', 'b', 'f', 'br', 'rb', 'fr', 'rf', 't', 'tr', 'rt'):
                i = j
                j, line = scan_string(text, j, line)
                cur.append(Tok('str', text[start:j], sline, ws, start, j))
                i = j
                ws = False
                continue
            cur.append(Tok('name', word, sline, ws, start, j))
            i = j
            ws = False
            continue
        if isdigit(c) or (c == '.' and i + 1 < n and isdigit(text[i + 1])):
            j = i + 1
            while j < n and (isalnum(text[j]) or text[j] in '._' or (text[j] in '+-' and text[j - 1] in 'eE' and not text[start:j].startswith(('0x', '0X')))):
                j += 1
            cur.append(Tok('num', text[i:j], sline, ws, start, j))
            i = j
            ws = False
            continue
        if c in '\'"':
            j, line = scan_string(text, i, line)
            cur.append(Tok('str', text[i:j], sline, ws, start, j))
            i = j
            ws = False
            continue
        if c in '([{':
            depth += 1
            cur.append(Tok('op', c, sline, ws, start, i + 1))
            i += 1
            ws = False
            continue
        if c in ')]}':
            if depth > 0:
                depth -= 1
            cur.append(Tok('op', c, sline, ws, start, i + 1))
            i += 1
            ws = False
            continue
        op = None
        for o in OPS3:
            if text.startswith(o, i):
                op = o
                break
        if op is None:
            for o in OPS2:
                if text.startswith(o, i):
                    op = o
                    break
        if op is None:
            op = c
        cur.append(Tok('op', op, sline, ws, start, i + len(op)))
        i += len(op)
        ws = False
    if cur:
        lines.append((indent, cur))
    return lines, line

def scan_string(text, i, line):
    n = len(text)
    q = text[i]
    if text.startswith(q * 3, i):
        j = i + 3
        while j < n:
            c = text[j]
            if c == '\\':
                if j + 1 < n and text[j + 1] == '\n':
                    line += 1
                j += 2
                continue
            if c == '\n':
                line += 1
            if text.startswith(q * 3, j):
                return j + 3, line
            j += 1
        return n, line
    j = i + 1
    while j < n:
        c = text[j]
        if c == '\\':
            if j + 1 < n and text[j + 1] == '\n':
                line += 1
            j += 2
            continue
        if c == q:
            return j + 1, line
        if c == '\n':
            return j, line
        j += 1
    return n, line

def split_statements(tokens):
    """Split a logical line's tokens on top-level ';'."""
    out = []
    cur = []
    depth = 0
    for t in tokens:
        if t.t == 'op':
            if t.v in '([{':
                depth += 1
            elif t.v in ')]}':
                depth -= 1
            elif t.v == ';' and depth == 0:
                if cur:
                    out.append(cur)
                cur = []
                continue
        cur.append(t)
    if cur:
        out.append(cur)
    return out

def match_bracket(toks, i):
    """toks[i] is an opening bracket; return index of matching closing bracket."""
    depth = 0
    for j in range(i, len(toks)):
        t = toks[j]
        if t.t == 'op':
            if t.v in '([{':
                depth += 1
            elif t.v in ')]}':
                depth -= 1
                if depth == 0:
                    return j
    return len(toks) - 1

def repr_tokens(toks, drop_ws_after=()):
    out = []
    for k, t in enumerate(toks):
        if t.ws and out and k not in drop_ws_after:
            out.append(' ')
        out.append(t.v)
    return ''.join(out)

def compact_tokens(toks):
    return ''.join(t.v for t in toks)

def access_of(name, is_func, has_parent, parent_is_class):
    if has_parent and not parent_is_class:
        return 'private'
    if not name.startswith('_'):
        return 'public'
    n = len(name)
    if is_func and parent_is_class and n > 3 and name[1] == '_' and name.endswith('__'):
        return 'public'
    if parent_is_class and n > 1 and name[1] == '_':
        return 'private'
    return 'protected'

class Scope:
    __slots__ = ('indent', 'idx', 'kind', 'endline')
    def __init__(self, indent, idx, kind):
        self.indent = indent; self.idx = idx; self.kind = kind; self.endline = 0

def parse(ctx):
    L = ctx.lang
    lines, lastline = tokenize(ctx.text)
    stack = []
    z_enabled = L.kind('z').enabled
    decorators = []

    def parent():
        return stack[-1] if stack else None

    def close_until(indent):
        while stack and stack[-1].indent >= indent:
            s = stack.pop()
            t = ctx.cork[s.idx]
            t.end = s.endline

    def mark_end(line):
        for s in stack:
            if line > s.endline:
                s.endline = line

    def scope_info():
        p = parent()
        if p is None:
            return 0, False, False
        return p.idx, True, p.kind == 'class'

    def make(name, kind, line, is_func=False, **kw):
        sidx, has_parent, pclass = scope_info()
        acc = access_of(name, is_func, has_parent, pclass)
        idx = ctx.make_tag(name, kind, line=line, scope=sidx)
        t = ctx.cork[idx]
        t.access = acc
        if acc == 'private':
            t.file_scope = True
        for k, v in kw.items():
            setattr(t, k, v)
        return idx

    pending_block = None
    for indent, toks in lines:
        close_until(indent)
        stmts = split_statements(toks)
        last_line_of_toks = toks[-1].line
        if toks[-1].t == 'str':
            last_line_of_toks = ctx.line_of(toks[-1].end - 1)
        mark_end(last_line_of_toks)
        first = True
        for st in stmts:
            r = handle_statement(ctx, L, st, indent, stack, make, decorators, z_enabled, first)
            first = False
            if r == 'block_rest':
                # remaining statements after a block opener on same line belong to the new block
                continue
    close_until(-1)

def handle_statement(ctx, L, st, indent, stack, make, decorators, z_enabled, first):
    t0 = st[0]
    if t0.t == 'op' and t0.v == '@':
        decorators.append(compact_decorator(st[1:]))
        return None
    is_async = False
    toks = st
    if t0.t == 'name' and t0.v == 'async' and len(st) > 1 and st[1].t == 'name' and st[1].v in ('def', 'for', 'with'):
        toks = st[1:]
        t0 = toks[0]
        is_async = True
    if t0.t == 'name' and t0.v in ('def', 'class') and len(toks) > 1 and toks[1].t == 'name':
        name_tok = toks[1]
        name = name_tok.v
        line = name_tok.line
        p = stack[-1] if stack else None
        if t0.v == 'class':
            kind = 'c'
            inherits = ''
            j = 2
            if j < len(toks) and toks[j].t == 'op' and toks[j].v == '[':
                j = match_bracket(toks, j) + 1
            if j < len(toks) and toks[j].t == 'op' and toks[j].v == '(':
                e = match_bracket(toks, j)
                inherits = repr_tokens(toks[j + 1:e]).strip()
                j = e + 1
            idx = make(name, 'c', toks[0].line if False else line, inherits=inherits)
            t = ctx.cork[idx]
        else:
            kind = 'm' if (p is not None and p.kind == 'class') else 'f'
            j = 2
            sig = None
            params = []
            if j < len(toks) and toks[j].t == 'op' and toks[j].v == '[':
                j = match_bracket(toks, j) + 1
                tparams = True
            else:
                tparams = False
            if j < len(toks) and toks[j].t == 'op' and toks[j].v == '(':
                e = match_bracket(toks, j)
                inner = toks[j + 1:e]
                params, drop = collect_params(inner)
                if z_enabled:
                    sig = '(' + repr_tokens_inner(toks[j + 1:e], drop, toks[e]) + ')'
                else:
                    sig = '(' + repr_tokens_inner(toks[j + 1:e], (), toks[e]) + ')'
                j = e + 1
            typeref = None
            if j < len(toks) and toks[j].t == 'op' and toks[j].v == '->':
                k = j + 1
                depth = 0
                rt = []
                while k < len(toks):
                    tk = toks[k]
                    if tk.t == 'op' and tk.v in '([{':
                        depth += 1
                    elif tk.t == 'op' and tk.v in ')]}':
                        depth -= 1
                    elif tk.t == 'op' and tk.v == ':' and depth == 0:
                        break
                    rt.append(tk)
                    k += 1
                if rt:
                    typeref = ('typename', compact_tokens(rt))
            idx = make(name, kind, line, is_func=True)
            t = ctx.cork[idx]
            if sig is not None and not tparams:
                t.signature = sig
            if typeref:
                t.typeref = typeref
        if decorators:
            t.set_field('decorators', ','.join(decorators))
            del decorators[:]
        sc = Scope(indent, idx, 'class' if t0.v == 'class' else 'func')
        sc.endline = ctx.cork[idx].line
        # end line: last token line of this statement
        lastl = toks[-1].line
        sc.endline = lastl
        stack.append(sc)
        if t0.v == 'def':
            for (pname, pline, ptype) in params:
                if pname in ('*', '/'):
                    continue
                pidx = make(pname, 'z', pline)
                if ptype:
                    ctx.cork[pidx].typeref = ('typename', ptype)
        # handle statements on the same line after ':'
        return 'block_rest'
    del decorators[:]
    if t0.t == 'name':
        kw = t0.v
        if kw == 'import':
            handle_import(ctx, st[1:], make)
            return None
        if kw == 'from':
            handle_from(ctx, st[1:], make)
            return None
        if kw in ('if', 'elif', 'else', 'for', 'while', 'try', 'except', 'finally', 'with', 'return',
                  'pass', 'break', 'continue', 'raise', 'global', 'nonlocal', 'del', 'assert', 'yield',
                  'print', 'exec', 'lambda', 'await', 'not', 'match', 'case'):
            # compound statement: maybe has a simple statement after ':'
            if kw in ('if', 'elif', 'else', 'for', 'while', 'try', 'except', 'finally', 'with', 'match', 'case'):
                # find top-level ':' and process the rest
                depth = 0
                for k, tk in enumerate(st):
                    if tk.t == 'op':
                        if tk.v in '([{':
                            depth += 1
                        elif tk.v in ')]}':
                            depth -= 1
                        elif tk.v == ':' and depth == 0:
                            rest = st[k + 1:]
                            if rest:
                                handle_statement(ctx, L, rest, indent + 1, stack, make, decorators, z_enabled, False)
                            break
            if not (kw in ('match', 'case', 'print', 'exec') and len(st) > 1 and st[1].t == 'op' and st[1].v in ('=', ':')):
                return None
        if kw == 'type' and len(st) > 2 and st[1].t == 'name' and st[2].t == 'op' and st[2].v in ('=', '['):
            p = stack[-1] if stack else None
            kind = 'l' if (p is not None and p.kind == 'func') else 'v'
            make(st[1].v, kind, st[1].line, typeref=('typename', 'TypeAliasType'))
            return None
        handle_assignment(ctx, st, stack, make)
    return None

def compact_decorator(toks):
    return repr_tokens(toks).strip()

def repr_tokens_inner(toks, drop, closer):
    out = []
    for k, t in enumerate(toks):
        if t.ws and k not in drop:
            out.append(' ')
        out.append(t.v)
    if closer.ws and len(toks) not in drop:
        out.append(' ')
    return ''.join(out)

def collect_params(inner):
    """Return list of (name, line, typeref) and set of token indexes after which whitespace is dropped."""
    params = []
    drop = set()
    depth = 0
    expect = True
    k = 0
    n = len(inner)
    while k < n:
        t = inner[k]
        if t.t == 'op' and t.v in '([{':
            depth += 1
        elif t.t == 'op' and t.v in ')]}':
            depth -= 1
        elif depth == 0 and t.t == 'op' and t.v == ',':
            expect = True
            k += 1
            continue
        if depth == 0 and expect:
            if t.t == 'op' and t.v in ('*', '**', '/'):
                if t.v != '/' and k + 1 < n and inner[k + 1].t == 'name':
                    k += 1
                    t = inner[k]
                else:
                    expect = False
                    k += 1
                    continue
            if t.t == 'name':
                ptype = None
                if k + 1 < n and inner[k + 1].t == 'op' and inner[k + 1].v == ':':
                    m = k + 2
                    d2 = 0
                    tt = []
                    while m < n:
                        x = inner[m]
                        if x.t == 'op' and x.v in '([{':
                            d2 += 1
                        elif x.t == 'op' and x.v in ')]}':
                            d2 -= 1
                        elif d2 == 0 and x.t == 'op' and x.v in (',', '='):
                            break
                        tt.append(x)
                        m += 1
                    if tt:
                        ptype = compact_tokens(tt)
                params.append((t.v, t.line, ptype))
                drop.add(k + 1)
            expect = False
        k += 1
    return params, drop

def handle_import(ctx, toks, make):
    # import a.b.c [as x], d
    for part in split_commas(toks):
        if not part:
            continue
        names = []
        alias = None
        k = 0
        dotted = []
        while k < len(part):
            t = part[k]
            if t.t == 'name' and t.v == 'as':
                if k + 1 < len(part) and part[k + 1].t == 'name':
                    alias = part[k + 1]
                break
            dotted.append(t)
            k += 1
        if not dotted:
            continue
        mod = ''.join(t.v for t in dotted)
        line = dotted[0].line
        if alias is None:
            idx = ctx.make_tag(mod, 'i', line=line)
            ctx.cork[idx].add_role('imported')
        else:
            idx = ctx.make_tag(mod, 'i', line=line)
            ctx.cork[idx].add_role('indirectlyImported')
            aidx = make(alias.v, 'I', alias.line)
            ctx.cork[aidx].set_field('nameref', 'module:' + mod)

def split_commas(toks):
    out = []
    cur = []
    depth = 0
    for t in toks:
        if t.t == 'op' and t.v in '([{':
            depth += 1
            if depth == 1 and t.v == '(':
                continue
        if t.t == 'op' and t.v in ')]}':
            depth -= 1
            if depth == 0 and t.v == ')':
                continue
        if t.t == 'op' and t.v == ',' and depth <= 1:
            out.append(cur)
            cur = []
            continue
        cur.append(t)
    out.append(cur)
    return out

def handle_from(ctx, toks, make):
    k = 0
    mod = []
    while k < len(toks) and not (toks[k].t == 'name' and toks[k].v == 'import'):
        mod.append(toks[k])
        k += 1
    if not mod or k >= len(toks):
        return
    modname = ''.join(t.v for t in mod)
    midx = ctx.make_tag(modname, 'i', line=mod[0].line)
    ctx.cork[midx].add_role('namespace')
    rest = toks[k + 1:]
    if rest and rest[0].t == 'op' and rest[0].v == '*':
        return
    for part in split_commas(rest):
        part = [t for t in part]
        if not part or part[0].t != 'name':
            continue
        name = part[0]
        alias = None
        if len(part) >= 3 and part[1].t == 'name' and part[1].v == 'as' and part[2].t == 'name':
            alias = part[2]
        idx = ctx.make_tag(name.v, 'Y', line=name.line, scope_kind=ctx.lang.kind('i'), scope_name=modname)
        ctx.cork[idx].add_role('indirectlyImported' if alias else 'imported')
        if alias:
            aidx = make(alias.v, 'Y', alias.line)
            ctx.cork[aidx].set_field('nameref', 'unknown:' + name.v)

def handle_assignment(ctx, st, stack, make):
    # find top-level '=' or ':' annotation
    n = len(st)
    depth = 0
    eq = None
    colon = None
    for k, t in enumerate(st):
        if t.t == 'op':
            if t.v in '([{':
                depth += 1
            elif t.v in ')]}':
                depth -= 1
            elif depth == 0 and t.v == '=' and eq is None:
                eq = k
                break
            elif depth == 0 and t.v == ':' and colon is None and eq is None:
                colon = k
            elif depth == 0 and t.v in ('+=', '-=', '*=', '/=', '//=', '%=', '**=', '>>=', '<<=', '&=', '|=', '^=', '@=', ':='):
                return
            elif depth == 0 and t.v in ('.', ) and colon is None:
                return
        elif t.t == 'name' and t.v == 'lambda':
            break
    p = stack[-1] if stack else None
    infunc = p is not None and p.kind == 'func'
    kind = 'l' if infunc else 'v'
    if colon is not None and (eq is None or colon < eq):
        # annotated
        if colon == 1 and st[0].t == 'name':
            end = eq if eq is not None else n
            ann = st[colon + 1:end]
            typeref = ('typename', compact_tokens(ann)) if ann else None
            if eq is None:
                return
            make(st[0].v, kind, st[0].line, typeref=typeref)
        return
    if eq is None:
        return
    targets = st[:eq]
    value = st[eq + 1:]
    # lambda?
    if len(targets) == 1 and targets[0].t == 'name' and value and value[0].t == 'name' and value[0].v == 'lambda':
        k = 1
        args = []
        while k < len(value) and not (value[k].t == 'op' and value[k].v == ':'):
            args.append(value[k])
            k += 1
        fkind = 'm' if (p is not None and p.kind == 'class') else 'f'
        sig = '(' + repr_tokens(args).strip() + ')'
        make(targets[0].v, fkind, targets[0].line, is_func=True, signature=sig)
        return
    if all(t.t == 'name' or (t.t == 'op' and t.v == ',') for t in targets):
        names = [t for t in targets if t.t == 'name']
        if not names:
            return
        if len(targets) == 1:
            make(names[0].v, kind, names[0].line)
            return
        # tuple: names separated by commas
        ok = True
        for k, t in enumerate(targets):
            if (k % 2 == 0) != (t.t == 'name'):
                ok = False
        if not ok:
            return
        for t in names:
            make(t.v, kind, t.line)
