"""C/C++ lexer with integrated preprocessor directive handling."""
from core import *
import core

C_KEYWORDS = set('''auto break case char const continue default do double else enum extern float for goto if
inline int long register restrict return short signed sizeof static struct switch typedef union unsigned void
volatile while _Bool _Complex _Imaginary _Alignas _Alignof _Atomic _Generic _Noreturn _Static_assert
_Thread_local __attribute__ __declspec asm __asm__ __asm typeof __typeof__ __inline __inline__ __restrict
__restrict__ __volatile__ __const __extension__ bool _Pragma'''.split())

CXX_KEYWORDS = C_KEYWORDS | set('''alignas alignof and and_eq bitand bitor catch char8_t char16_t char32_t class
compl concept consteval constexpr constinit const_cast co_await co_return co_yield decltype delete dynamic_cast
explicit export false final friend mutable namespace new noexcept not not_eq nullptr operator or or_eq override
private protected public reinterpret_cast requires static_assert static_cast template this thread_local throw
true try typeid typename using virtual wchar_t xor xor_eq module import'''.split())

CUDA_KEYWORDS = C_KEYWORDS | set('__global__ __device__ __host__ __shared__ __constant__ __managed__ __noinline__ __forceinline__'.split())

class T:
    __slots__ = ('t', 'v', 'line', 'pos', 'sp', 'chain', 'end', 'endline')
    def __init__(self, t, v, line, pos, sp=False):
        self.t = t        # id kw num str chr op ( [ { } ; eof
        self.v = v
        self.line = line
        self.pos = pos
        self.sp = sp      # followed by space
        self.chain = None
        self.end = pos
        self.endline = line
    def __repr__(self):
        if self.chain is not None:
            return '%s%r' % (self.t, self.chain)
        return '%s:%s' % (self.t, self.v)
    def is_(self, t, v=None):
        return self.t == t and (v is None or self.v == v)

OPS = ['<<=', '>>=', '...', '->*', '<=>', '::', '->', '++', '--', '<<', '>>', '<=', '>=', '==', '!=', '&&', '||',
       '+=', '-=', '*=', '/=', '%=', '&=', '|=', '^=', '##', '.*']

class Lexer:
    def __init__(self, ctx, lang_kind):
        self.ctx = ctx
        self.text = ctx.text
        self.n = len(self.text)
        self.i = 0
        self.line = 1
        self.lang_kind = lang_kind   # 'C', 'C++', 'CUDA'
        if lang_kind == 'C':
            self.keywords = C_KEYWORDS
        elif lang_kind == 'CUDA':
            self.keywords = CUDA_KEYWORDS
        else:
            self.keywords = CXX_KEYWORDS
        self.bol = True
        self.cond = []      # stack of dicts: {'skip': bool, 'taken': bool, 'single': bool, 'was_skipping': bool}
        self.pending = []
        self.last_sig = None   # last significant token type emitted
        self.header = ctx.is_header
        self.L = ctx.lang
        self.macro_kind = self.L.kind('d')
        self.if0 = OPT.if0
        p = find_language('CPreProcessor')
        if p is not None:
            pp = p.param('if0')
            if pp is not None and pp.value is not None:
                self.if0 = pp.value.lower() in ('true', 'yes', '1', 'on')

    # ------------------------------------------------------------------
    def skipping(self):
        for c in self.cond:
            if c['skip']:
                return True
        return False

    def next(self):
        while True:
            t = self._next()
            if t is None:
                continue
            if t.t != 'eof':
                self.last_sig = t.t if t.t in (';', '{', '}') else 'x'
            return t

    def _skip_ws_comments(self):
        """Skip whitespace and comments; return True if any skipped. Tracks newlines."""
        text = self.text
        n = self.n
        skipped = False
        while self.i < n:
            c = text[self.i]
            if c == '\n':
                self.line += 1
                self.i += 1
                self.bol = True
                skipped = True
            elif c in ' \t\r\f\v':
                self.i += 1
                skipped = True
            elif c == '\\' and self.i + 1 < n and text[self.i + 1] == '\n':
                self.i += 2
                self.line += 1
                skipped = True
            elif c == '\\' and text.startswith('\\\r\n', self.i):
                self.i += 3
                self.line += 1
                skipped = True
            elif c == '/' and self.i + 1 < n and text[self.i + 1] == '*':
                j = text.find('*/', self.i + 2)
                if j < 0:
                    j = n - 2
                self.line += text.count('\n', self.i, j + 2)
                self.i = j + 2
                skipped = True
            elif c == '/' and self.i + 1 < n and text[self.i + 1] == '/':
                j = self.i + 2
                while True:
                    k = text.find('\n', j)
                    if k < 0:
                        k = n
                        break
                    # line continuation in // comment
                    b = k - 1
                    if b >= 0 and text[b] == '\r':
                        b -= 1
                    if b >= j and text[b] == '\\':
                        self.line += 1
                        j = k + 1
                        continue
                    break
                self.i = k
                skipped = True
            else:
                break
        return skipped

    def _next(self):
        if self.pending:
            return self.pending.pop(0)
        text = self.text
        n = self.n
        while True:
            self._skip_ws_comments()
            if self.i >= n:
                if self.cond:
                    pass
                return T('eof', '', self.line, n)
            c = text[self.i]
            if c == '#' and self.bol:
                self.directive()
                continue
            if self.skipping():
                self._skip_token_raw()
                continue
            self.bol = False
            return self._token()

    def _skip_token_raw(self):
        text = self.text
        c = text[self.i]
        self.bol = False
        if c == '"' or c == "'":
            self._scan_quoted(c)
        else:
            self.i += 1

    def _scan_quoted(self, q):
        text = self.text
        n = self.n
        j = self.i + 1
        while j < n:
            c = text[j]
            if c == '\\':
                if j + 1 < n and text[j + 1] == '\n':
                    self.line += 1
                j += 2
                continue
            if c == q:
                j += 1
                break
            if c == '\n':
                break
            j += 1
        self.i = min(j, n)

    def _token(self):
        text = self.text
        n = self.n
        i = self.i
        c = text[i]
        line = self.line
        if c == '_' or isalpha(c) or c == '$' or ord(c) >= 0x80:
            j = i + 1
            while j < n and (text[j] == '_' or isalnum(text[j]) or text[j] == '$' or ord(text[j]) >= 0x80):
                j += 1
            word = text[i:j]
            # string prefixes
            if j < n and text[j] in '"\'' and word in ('L', 'u', 'U', 'u8', 'R', 'LR', 'uR', 'UR', 'u8R'):
                if word.endswith('R') and text[j] == '"' and self.lang_kind != 'C':
                    return self._raw_string(i, j, line)
                self.i = j
                self._scan_quoted(text[j])
                tok = T('str' if text[j] == '"' else 'chr', text[i:self.i], line, i)
                return self._fin(tok)
            self.i = j
            tok = T('kw' if word in self.keywords else 'id', word, line, i)
            return self._fin(tok)
        if isdigit(c) or (c == '.' and i + 1 < n and isdigit(text[i + 1])):
            j = i + 1
            while j < n:
                d = text[j]
                if isalnum(d) or d == '.' or d == '_' or (d == "'" and self.lang_kind != 'C' and j + 1 < n and isalnum(text[j + 1])):
                    j += 1
                elif d in '+-' and text[j - 1] in 'eEpP' and not (text[i:i + 2] in ('0x', '0X') and text[j - 1] in 'eE'):
                    j += 1
                else:
                    break
            self.i = j
            return self._fin(T('num', text[i:j], line, i))
        if c == '"' or c == "'":
            self._scan_quoted(c)
            return self._fin(T('str' if c == '"' else 'chr', text[i:self.i], line, i))
        if c in '()[]{};':
            self.i = i + 1
            return self._fin(T(c if c in '{};' else c, c, line, i))
        for op in OPS:
            if text.startswith(op, i):
                if op == '::' or True:
                    self.i = i + len(op)
                    return self._fin(T('op', op, line, i))
        self.i = i + 1
        return self._fin(T('op', c, line, i))

    def _raw_string(self, i, j, line):
        text = self.text
        k = text.find('(', j + 1)
        if k < 0:
            self.i = j + 1
            return self._fin(T('str', text[i:self.i], line, i))
        delim = text[j + 1:k]
        endm = ')' + delim + '"'
        e = text.find(endm, k + 1)
        if e < 0:
            e = self.n
        else:
            e += len(endm)
        self.line += text.count('\n', k, e)
        self.i = e
        return self._fin(T('str', text[i:e], line, i))

    def _fin(self, tok):
        tok.end = self.i
        tok.endline = self.line
        # followed by space?
        if self.i < self.n:
            c = self.text[self.i]
            tok.sp = c in ' \t\r\n\f\v' or (c == '/' and self.i + 1 < self.n and self.text[self.i + 1] in '/*') or (c == '\\')
        return tok

    # ------------------------------------------------------------------
    # preprocessor

    def read_directive_line(self):
        """Read from current position (after '#') to end of logical line. Returns text with
        continuations removed and comments stripped, plus the start line."""
        text = self.text
        n = self.n
        out = []
        i = self.i
        while i < n:
            c = text[i]
            if c == '\\' and i + 1 < n and text[i + 1] == '\n':
                i += 2
                self.line += 1
                out.append(' ')
                continue
            if c == '\\' and text.startswith('\\\r\n', i):
                i += 3
                self.line += 1
                out.append(' ')
                continue
            if c == '\n':
                break
            if c == '/' and i + 1 < n and text[i + 1] == '*':
                j = text.find('*/', i + 2)
                if j < 0:
                    j = n - 2
                self.line += text.count('\n', i, j)
                i = j + 2
                out.append(' ')
                continue
            if c == '/' and i + 1 < n and text[i + 1] == '/':
                j = text.find('\n', i)
                if j < 0:
                    j = n
                # continuation inside // comment
                while j > 0 and j < n and text[j - 1] == '\\':
                    k = text.find('\n', j + 1)
                    self.line += 1
                    j = k if k >= 0 else n
                i = j
                continue
            if c == '"' or c == "'":
                j = i + 1
                while j < n and text[j] != c and text[j] != '\n':
                    if text[j] == '\\':
                        j += 1
                    j += 1
                out.append(text[i:j + 1])
                i = j + 1
                continue
            out.append(c)
            i += 1
        self.i = i
        return ''.join(out)

    def directive(self):
        start_line = self.line
        start_pos = self.i
        self.i += 1  # skip '#'
        body = self.read_directive_line()
        s = body.lstrip(' \t')
        j = 0
        while j < len(s) and (isalnum(s[j]) or s[j] == '_'):
            j += 1
        d = s[:j]
        rest = s[j:]
        self.bol = True
        skipping = self.skipping()
        if d in ('if', 'ifdef', 'ifndef'):
            if skipping:
                self.cond.append({'skip': True, 'taken': True, 'single': True, 'outer_skip': True})
                return
            skip = False
            if d == 'if':
                expr = rest.strip()
                if expr == '0' and not self.if0:
                    skip = True
                self.cond_refs(rest, start_line)
            else:
                self.cond_refs(rest, start_line, single=True)
            self.cond.append({'skip': skip, 'taken': not skip, 'single': False, 'outer_skip': False})
            return
        if d in ('elif', 'else'):
            if not self.cond:
                return
            c = self.cond[-1]
            if c['outer_skip']:
                return
            if not c['single'] and self.last_sig not in (None, ';', '}') and c['taken']:
                c['single'] = True
            if c['single']:
                c['skip'] = True
                return
            if d == 'elif':
                expr = rest.strip()
                if not c['taken']:
                    # previous was #if 0
                    skip = (expr == '0' and not self.if0)
                    c['skip'] = skip
                    c['taken'] = not skip
                else:
                    c['skip'] = (expr == '0' and not self.if0)
                self.cond_refs(rest, start_line)
            else:
                c['skip'] = False
                c['taken'] = True
            return
        if d == 'endif':
            if self.cond:
                self.cond.pop()
            return
        if skipping:
            return
        if d == 'define':
            self.do_define(rest, start_line, start_pos)
        elif d == 'undef':
            m = rest.strip()
            k = 0
            while k < len(m) and (isalnum(m[k]) or m[k] == '_'):
                k += 1
            name = m[:k]
            if name:
                idx = self.ctx.make_tag(name, self.macro_kind, line=start_line, lang=self.L)
                t = self.ctx.cork[idx]
                t.add_role('undef')
                t.file_scope = not self.header
        elif d == 'include' or (d == 'import' and False):
            m = rest.strip()
            if m.startswith('<'):
                e = m.find('>')
                if e > 1:
                    self.make_include(m[1:e], 'system', start_line)
            elif m.startswith('"'):
                e = m.find('"', 1)
                if e > 1:
                    self.make_include(m[1:e], 'local', start_line)
        elif d == 'pragma':
            pass

    def cond_refs(self, rest, line, single=False):
        r = self.macro_kind.role('condition') if self.macro_kind else None
        names = []
        i = 0
        s = rest
        n = len(s)
        while i < n:
            c = s[i]
            if c == '_' or isalpha(c):
                j = i + 1
                while j < n and (s[j] == '_' or isalnum(s[j])):
                    j += 1
                w = s[i:j]
                if w != 'defined':
                    names.append(w)
                i = j
                if single:
                    break
            elif isdigit(c):
                j = i + 1
                while j < n and (isalnum(s[j]) or s[j] == '.'):
