import core
from parsers.cpp_lex import Lexer, T

HEADER_EXTS = ['h', 'H', 'hh', 'hpp', 'hxx', 'h++', 'inc', 'def']

def is_header(path):
    exts = HEADER_EXTS
    if OPT.header_exts is not None:
        spec = OPT.header_exts
        if spec == 'default':
            exts = HEADER_EXTS
        else:
            add = spec.startswith('+')
            if add:
                spec = spec[1:]
            lst = [e for e in spec.split('.') if e]
            exts = (HEADER_EXTS + lst) if add else lst
    b = path.rsplit('/', 1)[-1]
    if '.' not in b:
        return False
    return b.rsplit('.', 1)[1] in exts

def djb2(s):
    h = 5381
    for c in s.encode('latin-1'):
        h = (h * 33 + c) & 0xffffffff
    return h

TYPE_SPEC_KW = set('''static extern inline __inline __inline__ register auto typedef virtual explicit friend constexpr
consteval constinit mutable thread_local _Thread_local __thread _Noreturn __forceinline __global__ __device__ __host__
__shared__ __constant__ __managed__ __noinline__ __forceinline__ export'''.split())

QUALIFIER_AFTER = set(['const', 'volatile', 'override', 'final', 'noexcept', 'throw', '&', '&&', 'mutable',
                       '__attribute__', 'try', 'requires', 'restrict', '__restrict', '__restrict__'])

CONTROL_KW = set(['if', 'else', 'for', 'while', 'do', 'switch', 'return', 'goto', 'break', 'continue', 'case',
                  'default', 'try', 'catch', 'throw', 'delete', 'new', 'sizeof', 'co_return', 'co_yield', 'co_await',
                  'static_assert', '_Static_assert'])

class Scope:
    __slots__ = ('kind', 'idx', 'access', 'name', 'is_func', 'cls_kind', 'nth')
    def __init__(self, kind, idx, access=None, name=None):
        self.kind = kind      # 'file', 'namespace', 'class', 'struct', 'union', 'enum', 'function', 'block'
        self.idx = idx
        self.access = access
        self.name = name
        self.nth = 0

def tok_text(t):
    return t.v

class Parser:
    def __init__(self, ctx, langkind):
        self.ctx = ctx
        self.L = ctx.lang
        self.langkind = langkind
        self.cxx = langkind != 'C'
        ctx.is_header = is_header(ctx.path)
        self.header = ctx.is_header
        self.lex = Lexer(ctx, langkind)
        self.la = []
        self.anon_hash = '%08x' % djb2(OPT.anonhash if OPT.anonhash else ctx.path)
        self.anon_count = 0
        self.K = {}
        for k in self.L.kinds:
            self.K[k.letter] = k

    # token access ---------------------------------------------------------
    def get(self):
        if self.la:
            return self.la.pop()
        return self.lex.next()

    def unget(self, t):
        self.la.append(t)

    def read_chain(self, open_tok):
        close = {'(': ')', '[': ']', '{': '}'}[open_tok.t]
        chain = []
        while True:
            t = self.get()
            if t.t == 'eof':
                self.unget(t)
                break
            if t.t in ('(', '[', '{'):
                chain.append(self.read_chain(t))
                continue
            if t.t == close or (t.t == 'op' and t.v == close):
                open_tok.end = t.end
                open_tok.endline = t.line
                open_tok.sp = t.sp
                break
            if t.t in (')', ']', '}'):
                # mismatched; stop
                if t.t == '}' and close != '}':
                    self.unget(t)
                    break
                continue
            chain.append(t)
        open_tok.chain = chain
        return open_tok

    def anon(self, kletter):
        self.anon_count += 1
        k = self.K[kletter]
        return '__anon%s%02x%02x' % (self.anon_hash, self.anon_count, k.index)

    # tag creation ---------------------------------------------------------
    def make(self, name, kletter, line, scope, **kw):
        k = self.K.get(kletter)
        if k is None:
            return 0
        sidx = scope.idx if scope is not None else 0
        idx = self.ctx.make_tag(name, k, line=line, scope=sidx, lang=self.L)
        t = self.ctx.cork[idx]
        for a, v in kw.items():
            setattr(t, a, v)
        return idx

    # statements -------------------------------------------------------------
    def read_stmt(self, scope):
        toks = []
        depth_angle = 0
        while True:
            t = self.get()
            tt = t.t
            if tt == '(' or tt == '[':
                toks.append(self.read_chain(t))
                continue
            if tt == ';' or tt == '}' or tt == 'eof':
                return toks, t
            if tt == '{':
                if self.is_initializer_brace(toks, scope):
                    toks.append(self.read_chain(t))
                    continue
                return toks, t
            if tt == 'op' and t.v == ':' and toks:
                if len(toks) == 1 and toks[0].t == 'kw' and toks[0].v in ('public', 'private', 'protected'):
                    toks.append(t)
                    return toks, T(':', ':', t.line, t.pos)
                if len(toks) == 1 and toks[0].t == 'id' and scope.kind in ('function', 'block'):
                    toks.append(t)
                    return toks, T(':', ':', t.line, t.pos)
                if toks[0].t == 'kw' and toks[0].v in ('case', 'default') and scope.kind in ('function', 'block'):
                    return toks, T(':', ':', t.line, t.pos)
                if len(toks) == 2 and toks[0].t == 'kw' and toks[0].v in ('public', 'private', 'protected') and toks[1].t == 'id' and toks[1].v in ('slots', 'Q_SLOTS'):
                    toks.append(t)
                    return toks, T(':', ':', t.line, t.pos)
            toks.append(t)

    def is_initializer_brace(self, toks, scope):
        if not toks:
            return False
        depth = 0
        for t in toks:
            if t.t == 'op' and t.v == '=':
                # = { ... } initializer, but not "operator="
                return True
        last = toks[-1]
        if last.t == 'kw' and last.v == 'return':
            return True
        if self.cxx and last.t == 'id' and len(toks) >= 2 and scope.kind != 'enum':
            # brace initialization: T x{...};  (not struct/class/enum/namespace heads)
            for t in toks:
                if t.t == 'kw' and t.v in ('struct', 'class', 'union', 'enum', 'namespace', 'typedef', 'extern', 'template'):
                    return False
                if t.t == 'op' and t.v == ':':
                    return False
                if t.t == '(':
                    return False
            if toks[-2].t in ('id', 'kw', 'op') and not (toks[-2].t == 'op' and toks[-2].v in ('::', '~')):
                if toks[-2].t == 'op' and toks[-2].v not in ('*', '&', '&&', '>'):
                    return False
                return True
        return False

    def skip_braces(self):
        depth = 1
        while True:
            t = self.get()
            if t.t == 'eof':
                return t
            if t.t == '{':
                depth += 1
            elif t.t == '}':
                depth -= 1
                if depth == 0:
                    return t

    def parse(self):
        top = Scope('file', 0)
        self.parse_block(top, False)

    def parse_block(self, scope, expect_close):
        while True:
            toks, term = self.read_stmt(scope)
            if term.t == 'eof':
                if toks:
                    self.handle_stmt(toks, term, scope)
                return term
            if term.t == '}':
                if toks:
                    self.handle_stmt(toks, T(';', ';', term.line, term.pos), scope)
                if expect_close:
                    return term
                continue
            self.handle_stmt(toks, term, scope)

    # ------------------------------------------------------------------
    def handle_stmt(self, toks, term, scope):
        # strip leading noise
        toks = self.strip_attrs(toks)
        if term.t == ':':
            self.handle_colon(toks, scope)
            return
        if not toks:
            if term.t == '{':
                self.parse_block(Scope('block', scope.idx, scope.access, scope.name) if scope.kind in ('function', 'block') else scope, True)
                if scope.kind in ('function', 'block'):
                    pass
            return
        t0 = toks[0]
        if t0.t == 'kw':
            v = t0.v
            if v == 'namespace' and self.cxx:
                self.handle_namespace(toks, term, scope)
                return
            if v == 'template' and self.cxx:
                toks, tparams = self.strip_template(toks)
                if not toks:
                    if term.t == '{':
                        self.skip_braces()
                    return
                self.handle_decl(toks, term, scope, tparams)
                return
            if v == 'extern' and len(toks) >= 2 and toks[1].t == 'str' and term.t == '{':
                self.parse_block(scope, True)
                return
            if v == 'using' and self.cxx:
                self.handle_using(toks, term, scope)
                return
            if v in CONTROL_KW and scope.kind in ('function', 'block'):
                self.handle_control(toks, term, scope)
                return
            if v in ('static_assert', '_Static_assert'):
                if term.t == '{':
                    self.skip_braces()
                return
        self.handle_decl(toks, term, scope, None)

    def strip_attrs(self, toks):
        out = []
        i = 0
        n = len(toks)
        while i < n:
            t = toks[i]
            if t.t == 'kw' and t.v in ('__attribute__', '__declspec', 'alignas', '_Alignas', '__extension__', '__asm__', 'asm', '__asm') :
                if t.v == '__extension__':
                    i += 1
                    continue
                if i + 1 < n and toks[i + 1].t == '(':
                    i += 2
                    continue
                i += 1
                continue
            if t.t == '[' and t.chain and len(t.chain) == 1 and t.chain[0].t == '[':
                # [[attribute]]
                i += 1
                continue
            out.append(t)
            i += 1
        return out

    def handle_colon(self, toks, scope):
        if not toks:
            return
        t0 = toks[0]
        if t0.t == 'kw' and t0.v in ('public', 'private', 'protected'):
            scope.access = t0.v
            return
        if t0.t == 'id' and len(toks) == 2:
            self.make(t0.v, 'L', t0.line, scope, file_scope=True)
            return

    def handle_control(self, toks, term, scope):
        v = toks[0].v
        if v == 'for' and len(toks) >= 2 and toks[1].t == '(':
            inner = toks[1].chain
            # declarations in for-init
            parts = split_top(inner, ';')
            if parts and parts[0]:
                init = parts[0]
                if len(parts) == 1:
                    # range based for:  for (T x : expr)
                    colon = None
                    for k, t in enumerate(init):
                        if t.t == 'op' and t.v == ':':
                            colon = k
                            break
                    if colon is not None:
                        init = init[:colon]
                self.handle_decl_list(init, scope, 'l', toks[1].endline)
        elif v in ('if', 'while', 'switch') and len(toks) >= 2 and toks[1].t == '(':
            inner = toks[1].chain
            parts = split_top(inner, ';')
            if len(parts) > 1 and parts[0]:
                self.handle_decl_list(parts[0], scope, 'l', toks[1].endline)
        if term.t == '{':
            self.parse_block(Scope('block', scope.idx, scope.access, scope.name), True)

    def handle_namespace(self, toks, term, scope):
        # namespace A::B { / namespace { / namespace A = B;
        if len(toks) >= 3 and toks[2].t == 'op' and toks[2].v == '=':
            name = toks[1]
            target = join_plain(toks[3:])
            idx = self.make(name.v, 'A', name.line, scope, file_scope=not self.header)
            self.ctx.cork[idx].set_field('name', target)
            return
        if term.t != '{':
            return
        names = []
        line = toks[0].line
        for t in toks[1:]:
            if t.t == 'id':
                names.append(t)
        if not names:
            name = self.anon('n')
            idx = self.make(name, 'n', toks[0].line, scope, file_scope=not self.header)
            self.ctx.cork[idx].add_extra('anonymous')
            sc = Scope('namespace', idx, None, name)
            end = self.parse_block(sc, True)
            self.ctx.cork[idx].end = end.line
            return
        cur = scope
        idxs = []
        for nt in names:
            idx = self.make(nt.v, 'n', nt.line, cur, file_scope=not self.header)
            idxs.append(idx)
            cur = Scope('namespace', idx, None, nt.v)
        end = self.parse_block(cur, True)
        for idx in idxs:
            self.ctx.cork[idx].end = end.line

    def handle_using(self, toks, term, scope):
        if term.t == '{':
            self.skip_braces()
        if len(toks) >= 3 and toks[1].t == 'kw' and toks[1].v == 'namespace':
            name = join_plain(toks[2:])
            self.make(name, 'U', toks[0].line, scope, file_scope=not self.header)
            return
        # using X = type;
        if len(toks) >= 3 and toks[1].t == 'id' and toks[2].t == 'op' and toks[2].v == '=':
            tp = toks[3:]
            tr = self.typeref_of(tp)
            self.make(toks[1].v, 't', toks[1].line, scope, typeref=tr, file_scope=not self.header,
                      access=self.member_access(scope))
            return
        # using std::string;
        rest = [t for t in toks[1:] if not (t.t == 'kw' and t.v == 'typename')]
        if rest:
            last = None
            for t in rest:
                if t.t == 'id':
                    last = t
            if last is not None:
                self.make(last.v, 'N', toks[0].line, scope, file_scope=not self.header)

    def member_access(self, scope):
        if scope.kind in ('class', 'struct', 'union'):
            return scope.access
        return None

    # ------------------------------------------------------------------
    def strip_template(self, toks):
        """toks[0] is 'template'. Returns (rest, params)."""
        i = 1
        if i < len(toks) and toks[i].t == 'op' and toks[i].v == '<':
            depth = 0
            j = i
            while j < len(toks):
                t = toks[j]
                if t.t == 'op' and t.v == '<':
                    depth += 1
                elif t.t == 'op' and t.v == '>':
                    depth -= 1
                    if depth == 0:
                        break
                elif t.t == 'op' and t.v == '>>':
                    depth -= 2
                    if depth <= 0:
                        break
                j += 1
            params = toks[i + 1:j]
            rest = toks[j + 1:]
            if rest and rest[0].t == 'kw' and rest[0].v == 'template':
                rest, p2 = self.strip_template(rest)
            return rest, params
        return toks[1:], None

    # ------------------------------------------------------------------
    def find_aggregate(self, toks):
        """Return index of struct/class/union/enum keyword that starts an aggregate head."""
        for i, t in enumerate(toks):
            if t.t == 'kw' and t.v in ('struct', 'union', 'class', 'enum'):
                return i
            if t.t == '(' or (t.t == 'op' and t.v == '='):
                return -1
        return -1

    def handle_decl(self, toks, term, scope, tparams):
        is_typedef = any(t.t == 'kw' and t.v == 'typedef' for t in toks)
        agg = self.find_aggregate(toks)
        if agg >= 0:
            kw = toks[agg].v
            if term.t == '{' and self.agg_head_ok(toks, agg):
                self.handle_aggregate(toks, agg, scope, is_typedef, tparams)
                return
            if term.t == ';' and agg == 0 and kw in ('struct', 'union', 'class', 'enum') and self.is_forward(toks, agg):
                return
        if term.t == '{':
            if self.try_function(toks, scope, True, tparams):
                return
            # unknown block
            if scope.kind in ('function', 'block'):
                self.parse_block(Scope('block', scope.idx, scope.access, scope.name), True)
            elif scope.kind in ('class', 'struct', 'union'):
                self.skip_braces()
            else:
                self.skip_braces()
            return
        # ';'
        if is_typedef:
            self.handle_typedef(toks, scope)
            return
        if self.try_function(toks, scope, False, tparams):
            return
        self.handle_vars(toks, scope, term)

    def is_forward(self, toks, agg):
        rest = toks[agg + 1:]
        if len(rest) == 1 and rest[0].t == 'id':
            return True
        if not rest:
            return True
        return False

    def agg_head_ok(self, toks, agg):
        rest = toks[agg + 1:]
        # allow: [class] [attr] Name [::Name]* [final] [: bases] or nothing (anonymous)
        for t in rest:
            if t.t == 'op' and t.v == '=':
                return False
            if t.t == '(':
                # could be __attribute__ already stripped; macros like ALIGN(8)
                continue
        return True

    # ------------------------------------------------------------------
    def handle_aggregate(self, toks, agg, scope, is_typedef, tparams):
        kw = toks[agg].v
        rest = toks[agg + 1:]
        if kw == 'enum' and rest and rest[0].t == 'kw' and rest[0].v in ('class', 'struct'):
            rest = rest[1:]
        # name tokens up to ':' or end
        name_toks = []
        base = []
        i = 0
        while i < len(rest):
            t = rest[i]
            if t.t == 'op' and t.v == ':':
                base = rest[i + 1:]
                break
            name_toks.append(t)
            i += 1
        # name is last identifier in name_toks (skip final/attributes macros)
        name = None
        qual = []
        nt_list = [t for t in name_toks if not (t.t == 'id' and t.v in ('final',)) and t.t != '(']
        # handle template specialization Box<char>
        clean = []
        depth = 0
        for t in nt_list:
            if t.t == 'op' and t.v == '<':
                depth += 1
                continue
            if t.t == 'op' and t.v == '>':
                depth -= 1
                continue
            if t.t == 'op' and t.v == '>>':
                depth -= 2
                continue
            if depth > 0:
                continue
            clean.append(t)
        ids = [t for t in clean if t.t == 'id']
        line = toks[agg].line
        letter = {'struct': 's', 'union': 'u', 'class': 'c', 'enum': 'g'}[kw]
        anonymous = False
        if ids:
            name_tok = ids[-1]
            name = name_tok.v
            line = name_tok.line
            # qualified name A::B
            k = clean.index(name_tok)
            q = []
            j = k - 1
            while j >= 1 and clean[j].t == 'op' and clean[j].v == '::' and clean[j - 1].t == 'id':
                q.insert(0, clean[j - 1].v)
                j -= 2
            qual = q
        else:
            name = self.anon(letter)
            anonymous = True
        tscope = scope
        kw_kind = kw
        idx = self.make(name, letter, line, scope if not qual else None,
                        file_scope=not self.header)
        t = self.ctx.cork[idx]
        if anonymous:
            t.add_extra('anonymous')
        if qual:
            t.scope_kind = self.K.get('c') or self.K.get('s')
            t.scope_name = '::'.join(qual) if scope.idx == 0 else full_name(self.ctx.cork[scope.idx]) + '::' + '::'.join(qual)
        acc = self.member_access(scope)
        if acc:
            t.access = acc
        if kw == 'enum':
            if base:
                t.typeref = ('typename', self.join_type(base))
        else:
            if self.cxx:
                inh = self.parse_bases(base)
                if inh:
                    t.inherits = inh
        if tparams and self.cxx:
            self.make_tparams(tparams, idx)
        # body
        if kw == 'enum':
            end = self.parse_enum_body(idx)
        else:
            default_access = 'private' if kw == 'class' else 'public'
            sc = Scope({'struct': 'struct', 'union': 'union', 'class': 'class'}[kw], idx, default_access, name)
            end = self.parse_block(sc, True)
        t.end = end.line
        # declarators after '}'
        toks2, term2 = self.read_stmt(scope)
        if term2.t == '{':
            # weird; ignore
            self.skip_braces()
            return
        toks2 = self.strip_attrs(toks2)
        if not toks2:
            if term2.t == '}':
                self.unget(term2)
            return
        tk = self.K[letter]
        kindname = tk.name
        type_name = full_name(t)
        prefix = []
        for x in toks[:agg]:
            if x.t == 'kw' and x.v in ('const', 'volatile'):
                prefix.append(x.v)
        decls = split_top(toks2, ',')
        for d in decls:
            if not d:
                continue
            info = self.parse_declarator(d)
            if info is None:
                continue
            nm, nline, deco, rest_idx = info
            if prefix:
                tr = ('typename', ' '.join(prefix) + ' ' + kw + ' ' + type_name + deco)
            else:
                tr = (kindname, type_name + deco)
            if is_typedef:
                self.make(nm, 't', nline, scope, typeref=tr, file_scope=not self.header,
                          access=self.member_access(scope))
            else:
                self.make_var(nm, nline, scope, toks[:agg], tr, term2, False)
        if term2.t == '}':
            self.unget(term2)

    def parse_bases(self, base):
        if not base:
            return None
        parts = split_top_angle(base, ',')
        out = []
        for p in parts:
            p = [t for t in p if not (t.t == 'kw' and t.v in ('public', 'private', 'protected', 'virtual'))]
            if p:
                out.append(join_plain(p))
        return ','.join(out)

    def make_tparams(self, tparams, idx):
        if 'Z' not in self.K:
            return
        for part in split_top_angle(tparams, ','):
            if not part:
                continue
            # typename T / class T / int N / template<...> class T
            if part[0].t == 'kw' and part[0].v == 'template':
                continue
            eq = None
            for k, t in enumerate(part):
                if t.t == 'op' and t.v == '=':
                    eq = k
                    break
            if eq is not None:
                part = part[:eq]
            names = [t for t in part if t.t == 'id']
            if not names:
                continue
            nm = names[-1]
            kind_part = [t for t in part if t is not nm]
            if kind_part and kind_part[0].t == 'kw' and kind_part[0].v in ('typename', 'class'):
                tr = ('meta', kind_part[0].v)
            else:
                tr = ('typename', self.join_type(kind_part)) if kind_part else None
            self.ctx.make_tag(nm.v, self.K['Z'], line=nm.line, scope=idx, lang=self.L)
            zt = self.ctx.cork[-1]
            zt.typeref = tr
            zt.access = 'private' if False else None

    def parse_enum_body(self, idx):
        items = []
        cur = []
        endtok = None
        while True:
            t = self.get()
            if t.t == 'eof':
                endtok = t
                break
            if t.t == '}':
                endtok = t
                break
            if t.t in ('(', '[', '{'):
                cur.append(self.read_chain(t))
                continue
            if t.t == 'op' and t.v == ',':
                items.append(cur)
                cur = []
                continue
            cur.append(t)
        if cur:
            items.append(cur)
        parent = self.ctx.cork[idx]
        nth = 0
        for it in items:
            it = self.strip_attrs(it)
            if not it or it[0].t != 'id':
                continue
            e = self.make(it[0].v, 'e', it[0].line, Scope('enum', idx), file_scope=not self.header)
            et = self.ctx.cork[e]
            if parent.access is not None or (self.cxx and False):
                pass
            if self.cxx:
                et.access = parent.access if parent.access else None
            et.nth = nth
            nth += 1
        return endtok

    # ------------------------------------------------------------------
    def handle_typedef(self, toks, scope):
        toks = [t for t in toks if not (t.t == 'kw' and t.v == 'typedef')]
        decls = split_top(toks, ',')
        if not decls:
            return
        first = decls[0]
        # find base type and first declarator
        info = self.split_type_and_declarator(first)
        if info is None:
            return
        base, d = info
        for k, dd in enumerate([d] + decls[1:]):
            r = self.parse_declarator(dd)
            if r is None:
                continue
            nm, nline, deco, _ = r
            tr = self.typeref_from(base, deco)
            self.make(nm, 't', nline, scope, typeref=tr, file_scope=not self.header,
                      access=self.member_access(scope))

    # ------------------------------------------------------------------
    def split_type_and_declarator(self, toks):
        """Split a declaration into (base type tokens, declarator tokens)."""
        # function pointer: ... ( * name ) ( ... )
        n = len(toks)
        for i, t in enumerate(toks):
            if t.t == '(' and t.chain and any(x.t == 'op' and x.v in ('*', '&', '^') for x in t.chain[:1]) and i > 0:
                return toks[:i], toks[i:]
        # find the last identifier at depth 0 that is followed only by [ ] , : bits, = init
        last = None
        for i, t in enumerate(toks):
            if t.t == 'op' and t.v == '=':
                break
            if t.t == 'op' and t.v == ':' :
                break
            if t.t == 'id':
                last = i
            elif t.t == '(':
                break
        if last is None:
            return None
        # walk back over pointer stars
        j = last
        while j > 0 and toks[j - 1].t == 'op' and toks[j - 1].v in ('*', '&', '&&') or (j > 0 and toks[j - 1].t == 'kw' and toks[j - 1].v in ('const', 'volatile', 'restrict', '__restrict', '__restrict__') and j - 1 > 0 and toks[j - 2].t == 'op' and toks[j - 2].v == '*'):
            j -= 1
        base = toks[:j]
        if not base:
            return None
        return base, toks[j:]

    def parse_declarator(self, d):
        """Parse declarator tokens. Returns (name, line, decoration-string, index-after) or None."""
        d = self.strip_attrs(d)
        if not d:
            return None
        # function pointer (*name)(args)
        stars = []
        i = 0
        n = len(d)
        while i < n and ((d[i].t == 'op' and d[i].v in ('*', '&', '&&', '^')) or (d[i].t == 'kw' and d[i].v in ('const', 'volatile', 'restrict', '__restrict', '__restrict__'))):
            stars.append(d[i])
            i += 1
        if i < n and d[i].t == '(' and d[i].chain:
            inner = d[i].chain
            # (*name)  (*name[3]) (**name)
            k = 0
            istars = []
            while k < len(inner) and inner[k].t == 'op' and inner[k].v in ('*', '&', '^'):
                istars.append(inner[k])
                k += 1
            if k < len(inner) and inner[k].t == 'id':
                name = inner[k]
                after_inner = inner[k + 1:]
                rest = d[i + 1:]
                # build decoration: stars outside + ( stars + after_inner ) + rest chains
                deco_toks = stars + [T('(', '(', 0, 0)] 
                deco_inner = istars + after_inner
                ftoks = list(stars)
                pc = T('(', '(', 0, 0)
                pc.chain = istars + after_inner
                ftoks.append(pc)
                for x in rest:
                    if x.t == 'op' and x.v in ('=', ':'):
                        break
                    ftoks.append(x)
                return name.v, name.line, ('fp', ftoks), i + 1
            return None
        if i < n and d[i].t == 'id':
            name = d[i]
            j = i + 1
            # qualified name a::b
            while j + 1 < n and d[j].t == 'op' and d[j].v == '::' and d[j + 1].t == 'id':
                name = d[j + 1]
                j += 2
            post = []
            while j < n:
                x = d[j]
                if x.t == '[':
                    post.append(x)
                    j += 1
                    continue
                if x.t == 'op' and x.v == ':' and j + 1 < n:
                    # bitfield
                    post.append(('bits', d[j + 1]))
                    j += 2
                    continue
                break
            return name.v, name.line, (stars, post), j
        if i < n and d[i].t == 'kw' and d[i].v == 'operator':
            return None
        return None

    def deco_string(self, base_toks, deco):
        """Combine base type tokens with declarator decoration to a type string."""
        if isinstance(deco, tuple) and len(deco) == 2 and deco[0] == 'fp':
            return self.join_type(list(base_toks) + deco[1])
        stars, post = deco
        toks = list(base_toks) + stars
        s = self.join_type(toks)
        for p in post:
            if isinstance(p, tuple):
                s += ':' + p[1].v
            else:
                s += square_repr(p)
        return s

    def typeref_from(self, base, deco):
        base = [t for t in base if not (t.t == 'kw' and t.v in TYPE_SPEC_KW)]
        base = self.strip_attrs(base)
        if not base:
            return None
        # struct X ... => struct:X...
        if base[0].t == 'kw' and base[0].v in ('struct', 'union', 'enum', 'class') and len(base) >= 2 and base[1].t == 'id':
            k = {'struct': 'struct', 'union': 'union', 'enum': 'enum', 'class': 'class'}[base[0].v]
            s = self.deco_string(base[1:], deco)
            return (k, s)
        return ('typename', self.deco_string(base, deco))

    def typeref_of(self, toks):
        toks = [t for t in toks if not (t.t == 'kw' and t.v in TYPE_SPEC_KW)]
        if not toks:
            return None
        if toks[0].t == 'kw' and toks[0].v in ('struct', 'union', 'enum', 'class') and len(toks) >= 2 and toks[1].t == 'id':
            return (toks[0].v, self.join_type(toks[1:]))
        return ('typename', self.join_type(toks))

    def join_type(self, toks):
        return norm_join(toks)

    # ------------------------------------------------------------------
    def decl_kind(self, scope, is_extern):
        if scope.kind in ('class', 'struct', 'union'):
            return 'm'
        if scope.kind in ('function', 'block'):
            return 'x' if is_extern else 'l'
        return 'x' if is_extern else 'v'

    def make_var(self, name, line, scope, spec_toks, typeref, term, qualified, endline=None):
        is_extern = any(t.t == 'kw' and t.v == 'extern' for t in spec_toks)
        is_static = any(t.t == 'kw' and t.v == 'static' for t in spec_toks)
        kind = self.decl_kind(scope, is_extern)
        if qualified:
            kind = 'm'
        fs = False
        if kind in ('m',):
            fs = not self.header
            if qualified:
                fs = False
        elif kind == 'l':
            fs = True
        elif kind == 'v' or kind == 'x':
            fs = is_static and not self.header
        idx = self.make(name, kind, line, scope if not isinstance(qualified, tuple) else None, typeref=typeref, file_scope=fs)
        t = self.ctx.cork[idx]
        if isinstance(qualified, tuple):
            t.scope_kind = self.K['c'] if 'c' in self.K else self.K['s']
            t.scope_name = qualified[1]
        if kind != 'x' or True:
            t.end = endline if endline is not None else term.line
        acc = self.member_access(scope)
        if acc and kind == 'm':
            t.access = acc
        if kind == 'm' and scope.kind in ('class', 'struct', 'union'):
            t.nth = scope.nth
            scope.nth += 1
        props = []
        for x in spec_toks:
            if x.t == 'kw' and x.v in ('static', 'extern', 'inline', 'mutable', 'register', 'thread_local', 'constexpr', 'volatile') and x.v not in props:
                pass
        return idx

    def handle_vars(self, toks, scope, term):
        # filter out things that are clearly not declarations
        if not toks:
            return
        t0 = toks[0]
        if t0.t in ('num', 'str', 'chr'):
            return
        if t0.t == 'op' and t0.v not in ('::', '*'):
            return
        self.handle_decl_list(toks, scope, None, term.line, term)

    def handle_decl_list(self, toks, scope, force_kind, endline, term=None):
        decls = split_top(toks, ',')
        if not decls or not decls[0]:
            return
        info = self.split_type_and_declarator(decls[0])
        if info is None:
            return
        base, d = info
        # reject expressions: base must look like a type
        if not self.looks_like_type(base):
            return
        spec = [t for t in base if t.t == 'kw' and t.v in TYPE_SPEC_KW]
        for dd in [d] + decls[1:]:
            r = self.parse_declarator(dd)
            if r is None:
                continue
            nm, nline, deco, after = r
            # after declarator: must be end, '=' init, or '(' ctor args / '{' init (C++)
            if after < len(dd):
                x = dd[after]
                if not ((x.t == 'op' and x.v == '=') or x.t == '(' or x.t == '{'):
                    continue
                if x.t == '(' and not self.cxx:
                    continue
            tr = self.typeref_from(base, deco)
            q = False
            # qualified variable definition int N::var = 3;
            if dd and len(dd) >= 3:
                names = []
                k = 0
                while k < len(dd) and dd[k].t == 'op' and dd[k].v in ('*', '&'):
                    k += 1
                while k + 1 < len(dd) and dd[k].t == 'id' and dd[k + 1].t == 'op' and dd[k + 1].v == '::':
                    names.append(dd[k].v)
                    k += 2
                if names:
                    sn = '::'.join(names)
                    q = ('q', sn)
            self.make_var(nm, nline, scope, spec, tr, term if term is not None else T(';', ';', endline, 0), q, endline)

    def looks_like_type(self, base):
        b = [t for t in base if not (t.t == 'kw' and t.v in TYPE_SPEC_KW)]
        if not b:
            return False
        for t in b:
            if t.t in ('num', 'str', 'chr'):
                return False
            if t.t == 'op' and t.v not in ('::', '*', '&', '&&', '<', '>', ',', '>>'):
                return False
            if t.t == 'kw' and t.v in CONTROL_KW:
                return False
            if t.t == 'kw' and t.v in ('return', 'goto', 'case', 'sizeof', 'new', 'delete', 'throw'):
                return False
        if b[0].t == 'op' and b[0].v in ('*', '&'):
            return False
        return True

    # ------------------------------------------------------------------
    def find_function(self, toks):
        """Locate function name and parameter chain. Returns (name_tokens_start, name_index, paren_index) or None."""
        n = len(toks)
        for i in range(n):
            t = toks[i]
            if t.t != '(':
                continue
            if i == 0:
                continue
            prev = toks[i - 1]
            # operator overloading
            name_end = i - 1
            if prev.t == 'id' or (prev.t == 'kw' and prev.v in ('operator',)):
                pass
            elif prev.t == 'op' or prev.t == 'kw' or prev.t == '[' or prev.t == '(':
                # operator() etc
                op_i = None
                for k in range(i - 1, max(-1, i - 5), -1):
                    if toks[k].t == 'kw' and toks[k].v == 'operator':
                        op_i = k
                        break
                if op_i is None:
                    if prev.t == '(' and prev.chain is not None:
                        # int (*getfn(void))(int) - handled separately
                        pass
                    continue
            return i
        return None

    def try_function(self, toks, scope, is_def, tparams):
        n = len(toks)
        # function returning function pointer: int (*getfn(void))(int)
        for i, t in enumerate(toks):
            if t.t == '(' and t.chain and len(t.chain) >= 3 and t.chain[0].t == 'op' and t.chain[0].v == '*' \
                    and t.chain[1].t == 'id' and t.chain[2].t == '(' and i + 1 < n and toks[i + 1].t == '(' and i > 0:
                name = t.chain[1]
                params = t.chain[2]
                base = toks[:i]
                rt = [x for x in base if not (x.t == 'kw' and x.v in TYPE_SPEC_KW)]
                pc = T('(', '(', 0, 0)
                pc.chain = [t.chain[0]]
                rtype = norm_join(rt + [pc] + toks[i + 1:i + 2])
                kind = 'f' if is_def else 'p'
                return self.emit_function(name.v, name.line, scope, kind, base, params, toks[i + 2:], ('typename', rtype), None, tparams, is_def)
        pi = self.find_function(toks)
        if pi is None:
            return False
        params = toks[pi]
        # name
        ni = pi - 1
        name_toks = []
        prev = toks[ni]
        if prev.t == 'id':
            j = ni
            name_toks = [prev]
            if j - 1 >= 0 and toks[j - 1].t == 'op' and toks[j - 1].v == '~':
                name_toks = [toks[j - 1], prev]
                j -= 1
            start = j
        else:
            # operator
            k = ni
            while k >= 0 and not (toks[k].t == 'kw' and toks[k].v == 'operator'):
                k -= 1
            start = k
            name_toks = toks[k:pi]
        # qualifiers A::B::
        qual = []
        k = start - 1
        while k >= 1 and toks[k].t == 'op' and toks[k].v == '::':
            q = toks[k - 1]
            if q.t == 'id':
                qual.insert(0, q.v)
                k -= 2
            elif q.t == 'op' and q.v == '>':
                # template args A<T>::f
                depth = 0
                m = k - 1
                while m >= 0:
                    if toks[m].t == 'op' and toks[m].v == '>':
                        depth += 1
                    elif toks[m].t == 'op' and toks[m].v == '<':
                        depth -= 1
                        if depth == 0:
                            break
                    m -= 1
                if m >= 1 and toks[m - 1].t == 'id':
                    qual.insert(0, toks[m - 1].v)
                    k = m - 2
                else:
                    break
            else:
                break
        if k >= 0 and k < start and toks[k].t == 'op' and toks[k].v == '::' and k == 0:
            k -= 1
        base = toks[:k + 1] if k >= 0 else []
        after = toks[pi + 1:]
        # validate after
        ok = True
        j = 0
        while j < len(after):
            x = after[j]
            if x.t == 'kw' and x.v in ('const', 'volatile', 'override', 'final', 'noexcept', 'throw', 'mutable',
                                        '__attribute__', 'try', 'requires', 'restrict'):
                j += 1
                if j < len(after) and after[j].t == '(':
                    j += 1
                continue
            if x.t == 'id' and x.v in ('override', 'final'):
                j += 1
                continue
            if x.t == 'op' and x.v in ('&', '&&'):
                j += 1
                continue
            if x.t == 'op' and x.v == '->':
                j = len(after)
                break
            if x.t == 'op' and x.v == '=':
                # = 0, = default, = delete
                if j + 1 < len(after) and (after[j + 1].v in ('0', 'default', 'delete')):
                    j += 2
                    continue
                ok = False
                break
            if x.t == 'op' and x.v == ':' and is_def:
                j = len(after)
                break
            if x.t == '[':
                j += 1
                continue
            if x.t == 'id' and not is_def:
                # macro like __THROW or attribute macro
                j += 1
                if j < len(after) and after[j].t == '(':
                    j += 1
                continue
            if x.t == 'id' and is_def:
                # K&R declarations or macros
                j = len(after)
                break
            if x.t == 'kw' and is_def:
                j = len(after)
                break
            ok = False
            break
        if not ok:
            return False
        rt_toks = [x for x in base if not (x.t == 'kw' and x.v in TYPE_SPEC_KW)]
        rt_toks = self.strip_attrs(rt_toks)
        # Validate base: in C, need a return type; in C++ ctors allowed
        is_ctor = False
        if not rt_toks:
            if not self.cxx:
                if is_def and not base:
                    # K&R/implicit int "main() {"
                    pass
                elif not base:
                    return False
            else:
                is_ctor = True
        else:
            if not self.looks_like_type(rt_toks):
                return False
            if not is_def and not self.cxx and False:
                return False
        # params must look like a parameter list for prototypes
        if not is_def and not self.params_look_like_decl(params, scope, rt_toks):
            return False
        if name_toks and name_toks[0].t == 'id' and name_toks[0].v in ('if', 'while', 'for', 'switch', 'return', 'sizeof'):
            return False
        if name_toks[0].t == 'kw' and name_toks[0].v == 'operator':
            name = 'operator ' + norm_operator(name_toks[1:])
            name = name.rstrip()
        else:
            name = ''.join(t.v for t in name_toks)
        line = name_toks[0].line
        rtype = None
        if rt_toks:
            rtype = self.typeref_of(rt_toks)
        # trailing return type
        for j, x in enumerate(after):
            if x.t == 'op' and x.v == '->':
                rr = []
                for y in after[j + 1:]:
                    if y.t == 'kw' and y.v in ('override', 'final'):
                        break
                    if y.t == 'op' and y.v in ('=', ':'):
                        break
                    rr.append(y)
                if rr:
                    rtype = self.typeref_of(rr)
                break
        if rtype is not None and rtype[0] == 'typename' and rtype[1] == 'auto' and False:
            pass
        kind = 'f' if is_def else 'p'
        return self.emit_function(name, line, scope, kind, base, params, after, rtype, qual, tparams, is_def)

    def params_look_like_decl(self, params, scope, rt_toks):
        ch = params.chain or []
        if not ch:
            return True
        if len(ch) == 1 and ch[0].t == 'kw' and ch[0].v == 'void':
            return True
        for part in split_top(ch, ','):
            if not part:
                continue
            p = [t for t in part if not (t.t == 'kw' and t.v in ('const', 'volatile', 'register'))]
            if not p:
                continue
            if p[0].t in ('num', 'str', 'chr'):
                return False
            if p[0].t == 'op' and p[0].v not in ('...', '::', '&', '*'):
                return False
            if p[0].t == 'op' and p[0].v in ('&', '*') and scope.kind in ('function', 'block'):
                return False
        if scope.kind in ('function', 'block'):
            # inside functions, calls look like prototypes; require a type-ish first param with 2 tokens
            for part in split_top(ch, ','):
                ids = [t for t in part if t.t in ('id', 'kw')]
                if len(part) == 1 and part[0].t == 'id':
                    return False
        return True

    def emit_function(self, name, line, scope, kind, base, params, after, rtype, qual, tparams, is_def):
        ctx = self.ctx
        is_static = any(t.t == 'kw' and t.v == 'static' for t in base)
        sc = scope
        if scope.kind in ('function', 'block') and not is_def:
            # prototype inside function body
            pass
        fs = False
        if kind == 'p':
            fs = not self.header
        elif is_static and not self.header and scope.kind not in ('class', 'struct', 'union'):
            fs = True
        if scope.kind in ('class', 'struct', 'union') and not self.header:
            fs = True
        if qual:
            fs = is_static and not self.header and False
        idx = self.make(name, kind, line, None if qual else scope, file_scope=fs)
        t = ctx.cork[idx]
        if qual:
            qn = '::'.join(qual)
            if scope.idx:
                qn = full_name(ctx.cork[scope.idx]) + '::' + qn
            t.scope_kind = self.K['c'] if 'c' in self.K else self.K['s']
            t.scope_name = qn
        if rtype is not None:
            t.typeref = rtype
        t.signature = self.signature(params, after)
        acc = self.member_access(scope)
        if acc and not qual:
            t.access = acc
        if tparams and self.cxx:
            self.make_tparams(tparams, idx)
        # parameters
        if self.K['z'].enabled or True:
            self.make_params(params, idx, is_def)
        if is_def:
            fscope = Scope('function', idx, None, name)
            end = self.parse_block(fscope, True)
            t.end = end.line
        else:
            t.end = params.endline if not after else max(params.endline, after[-1].endline)
        return True

    def signature(self, params, after):
        s = norm_join([params])
        quals = []
        for x in after:
            if x.t == 'kw' and x.v in ('const', 'volatile', 'noexcept', 'override', 'final') or (x.t == 'id' and x.v in ('override', 'final')):
                quals.append(x.v)
            elif x.t == 'op' and x.v in ('&', '&&'):
                quals.append(x.v)
            elif x.t == 'op' and x.v in ('=', ':', '->'):
                break
            else:
                break
        if quals and self.cxx:
            s += ' ' + ' '.join(q for q in quals if q in ('const', 'volatile', '&', '&&'))
            s = s.rstrip()
        return s

    def make_params(self, params, fidx, is_def):
        ch = params.chain or []
        if not ch:
            return
        if len(ch) == 1 and ch[0].t == 'kw' and ch[0].v == 'void':
            return
        zk = self.K['z']
        nth = 0
        for part in split_top(ch, ','):
            if not part:
                continue
            if len(part) == 1 and part[0].t == 'op' and part[0].v == '...':
                continue
            # default value
            eq = None
            for k, x in enumerate(part):
                if x.t == 'op' and x.v == '=':
                    eq = k
                    break
            if eq is not None:
                part = part[:eq]
            info = self.split_type_and_declarator(part)
            if info is not None:
                base, d = info
                r = self.parse_declarator(d)
                if r is not None and self.looks_like_type(base):
                    nm, nline, deco, _ = r
                    tr = self.typeref_from(base, deco)
                    if zk.enabled:
                        pidx = self.ctx.make_tag(nm, zk, line=nline, scope=fidx, lang=self.L)
                        pt = self.ctx.cork[pidx]
                        pt.typeref = tr
                        pt.file_scope = True
                    nth += 1
                    continue
            # unnamed parameter (K&R names alone handled as unnamed? no)
            if len(part) == 1 and part[0].t == 'id' and not self.cxx:
                # K&R identifier list
                continue
            if zk.enabled:
                nm = self.anon('z')
                tr = self.typeref_of(part)
                pidx = self.ctx.make_tag(nm, zk, line=part[0].line, scope=fidx, lang=self.L)
                pt = self.ctx.cork[pidx]
                pt.typeref = tr
                pt.file_scope = True
                pt.add_extra('anonymous')
            nth += 1

# ---------------------------------------------------------------------------
# helpers

def split_top(toks, sep):
    out = []
    cur = []
    for t in toks:
        if (t.t == 'op' and t.v == sep) or (t.t == sep):
            out.append(cur)
            cur = []
        else:
            cur.append(t)
    out.append(cur)
    return out

def split_top_angle(toks, sep):
    out = []
    cur = []
    depth = 0
    for t in toks:
        if t.t == 'op' and t.v == '<':
            depth += 1
        elif t.t == 'op' and t.v == '>':
            depth -= 1
        elif t.t == 'op' and t.v == '>>':
            depth -= 2
        if depth <= 0 and t.t == 'op' and t.v == sep:
            out.append(cur)
            cur = []
        else:
            cur.append(t)
    out.append(cur)
    return out

def join_plain(toks):
    return ''.join(t.v if t.chain is None else norm_join([t]) for t in toks)

def square_repr(t):
    ch = t.chain or []
    if len(ch) == 1 and ch[0].t == 'num':
        return '[' + ch[0].v + ']'
    return '[]'

def norm_operator(toks):
    s = ''
    for t in toks:
        if t.chain is not None:
            s += '()' if t.t == '(' else '[]'
        else:
            if s and (t.t in ('id', 'kw')) and (s[-1].isalnum() or s[-1] == '_'):
                s += ' '
            s += t.v
    return s

def norm_join(toks):
    out = []
    n = len(toks)
    for i, t in enumerate(toks):
        nx = toks[i + 1] if i + 1 < n else None
        if t.chain is not None:
            if t.t == '(':
                out.append('(' + norm_join(t.chain) + ')')
            elif t.t == '[':
                out.append(square_repr(t))
            else:
                out.append('{' + norm_join(t.chain) + '}')
            sp = nx is not None and (nx.t in ('id', 'kw'))
        elif t.t == 'kw':
            out.append(t.v)
            sp = nx is not None and t.v != 'operator' and (nx.t in ('(', 'id', 'kw') and nx.chain is not None or nx.t in ('id', 'kw') or (nx.t == 'op' and nx.v in ('*', '&', '&&'))) and not (nx.t == '[')
        elif t.t == 'id' or (t.t == 'op' and t.v == '>'):
            out.append(t.v)
            sp = nx is not None and ((nx.t == '(' and nx.chain is not None) or nx.t in ('id', 'kw') or (nx.t == 'op' and nx.v in ('*', '&', '&&')))
        elif t.t == 'op' and t.v == ',':
            out.append(',')
            sp = False
        elif t.t == 'op' and t.v in ('*', '&', '&&'):
            out.append(t.v)
            sp = nx is not None and (nx.t in ('id', 'kw') or (nx.chain is not None and nx.t in ('(', '[')))
        else:
            out.append(t.v)
            sp = False
        if sp:
            out.append(' ')
    return ''.join(out)

def parse_c(ctx):
    _run(ctx, 'C')

def parse_cpp(ctx):
    _run(ctx, 'C++')

def parse_cuda(ctx):
    _run(ctx, 'CUDA')

def _run(ctx, kind):
    L = ctx.lang
    L.default_sep = '::'
    L.qualified = True
    p = Parser(ctx, kind)
    try:
        p.parse()
    except RecursionError:
        pass
