            self.skip_braces()
            return
        toks2 = self.strip_attrs(toks2)
        if not toks2:
            if term2.t == '}':
                self.unget(term2)
            return
        tk = self.K[letter]
        kindname = tk.name
        type_name = full_name(t)
        prefix = []
        for x in toks[:agg]:
            if x.t == 'kw' and x.v in ('const', 'volatile'):
                prefix.append(x.v)
        decls = split_top(toks2, ',')
        for d in decls:
            if not d:
                continue
            info = self.parse_declarator(d)
            if info is None:
                continue
            nm, nline, deco, rest_idx = info
            if prefix:
                tr = ('typename', ' '.join(prefix) + ' ' + kw + ' ' + type_name + deco)
            else:
                tr = (kindname, type_name + deco)
            if is_typedef:
                self.make(nm, 't', nline, scope, typeref=tr, file_scope=not self.header,
                          access=self.member_access(scope))
            else:
                self.make_var(nm, nline, scope, toks[:agg], tr, term2, False)
        if term2.t == '}':
            self.unget(term2)

    def parse_bases(self, base):
        if not base:
            return None
        parts = split_top_angle(base, ',')
        out = []
        for p in parts:
            p = [t for t in p if not (t.t == 'kw' and t.v in ('public', 'private', 'protected', 'virtual'))]
            if p:
                out.append(join_plain(p))
        return ','.join(out)

    def make_tparams(self, tparams, idx):
        if 'Z' not in self.K:
            return
        for part in split_top_angle(tparams, ','):
            if not part:
                continue
            # typename T / class T / int N / template<...> class T
            if part[0].t == 'kw' and part[0].v == 'template':
                continue
            eq = None
            for k, t in enumerate(part):
                if t.t == 'op' and t.v == '=':
                    eq = k
                    break
            if eq is not None:
                part = part[:eq]
            names = [t for t in part if t.t == 'id']
            if not names:
                continue
            nm = names[-1]
            kind_part = [t for t in part if t is not nm]
            if kind_part and kind_part[0].t == 'kw' and kind_part[0].v in ('typename', 'class'):
                tr = ('meta', kind_part[0].v)
            else:
                tr = ('typename', self.join_type(kind_part)) if kind_part else None
            self.ctx.make_tag(nm.v, self.K['Z'], line=nm.line, scope=idx, lang=self.L)
            zt = self.ctx.cork[-1]
            zt.typeref = tr
            zt.access = 'private' if False else None

    def parse_enum_body(self, idx):
        items = []
        cur = []
        endtok = None
        while True:
            t = self.get()
            if t.t == 'eof':
                endtok = t
                break
            if t.t == '}':
                endtok = t
                break
            if t.t in ('(', '[', '{'):
                cur.append(self.read_chain(t))
                continue
            if t.t == 'op' and t.v == ',':
                items.append(cur)
                cur = []
                continue
            cur.append(t)
        if cur:
            items.append(cur)
        parent = self.ctx.cork[idx]
        nth = 0
        for it in items:
            it = self.strip_attrs(it)
            if not it or it[0].t != 'id':
                continue
            e = self.make(it[0].v, 'e', it[0].line, Scope('enum', idx), file_scope=not self.header)
            et = self.ctx.cork[e]
            if parent.access is not None or (self.cxx and False):
                pass
            if self.cxx:
                et.access = parent.access if parent.access else None
            et.nth = nth
            nth += 1
        return endtok

    # ------------------------------------------------------------------
    def handle_typedef(self, toks, scope):
        toks = [t for t in toks if not (t.t == 'kw' and t.v == 'typedef')]
        decls = split_top(toks, ',')
        if not decls:
            return
        first = decls[0]
        # find base type and first declarator
        info = self.split_type_and_declarator(first)
        if info is None:
            return
        base, d = info
        for k, dd in enumerate([d] + decls[1:]):
            r = self.parse_declarator(dd)
            if r is None:
                continue
            nm, nline, deco, _ = r
            tr = self.typeref_from(base, deco)
            self.make(nm, 't', nline, scope, typeref=tr, file_scope=not self.header,
                      access=self.member_access(scope))

    # ------------------------------------------------------------------
    def split_type_and_declarator(self, toks):
        """Split a declaration into (base type tokens, declarator tokens)."""
        # function pointer: ... ( * name ) ( ... )
        n = len(toks)
        for i, t in enumerate(toks):
            if t.t == '(' and t.chain and any(x.t == 'op' and x.v in ('*', '&', '^') for x in t.chain[:1]) and i > 0:
                return toks[:i], toks[i:]
        # find the last identifier at depth 0 that is followed only by [ ] , : bits, = init
        last = None
        for i, t in enumerate(toks):
            if t.t == 'op' and t.v == '=':
                break
            if t.t == 'op' and t.v == ':' :
                break
            if t.t == 'id':
                last = i
            elif t.t == '(':
                break
        if last is None:
            return None
        # walk back over pointer stars
        j = last
        while j > 0 and toks[j - 1].t == 'op' and toks[j - 1].v in ('*', '&', '&&') or (j > 0 and toks[j - 1].t == 'kw' and toks[j - 1].v in ('const', 'volatile', 'restrict', '__restrict', '__restrict__') and j - 1 > 0 and toks[j - 2].t == 'op' and toks[j - 2].v == '*'):
            j -= 1
        base = toks[:j]
        if not base:
            return None
        return base, toks[j:]

    def parse_declarator(self, d):
        """Parse declarator tokens. Returns (name, line, decoration-string, index-after) or None."""
        d = self.strip_attrs(d)
        if not d:
            return None
        # function pointer (*name)(args)
        stars = []
        i = 0
        n = len(d)
        while i < n and ((d[i].t == 'op' and d[i].v in ('*', '&', '&&', '^')) or (d[i].t == 'kw' and d[i].v in ('const', 'volatile', 'restrict', '__restrict', '__restrict__'))):
            stars.append(d[i])
            i += 1
        if i < n and d[i].t == '(' and d[i].chain:
            inner = d[i].chain
            # (*name)  (*name[3]) (**name)
            k = 0
            istars = []
            while k < len(inner) and inner[k].t == 'op' and inner[k].v in ('*', '&', '^'):
                istars.append(inner[k])
                k += 1
            if k < len(inner) and inner[k].t == 'id':
                name = inner[k]
                after_inner = inner[k + 1:]
                rest = d[i + 1:]
                # build decoration: stars outside + ( stars + after_inner ) + rest chains
                deco_toks = stars + [T('(', '(', 0, 0)] 
                deco_inner = istars + after_inner
                ftoks = list(stars)
                pc = T('(', '(', 0, 0)
                pc.chain = istars + after_inner
                ftoks.append(pc)
                for x in rest:
                    if x.t == 'op' and x.v in ('=', ':'):
                        break
                    ftoks.append(x)
                return name.v, name.line, ('fp', ftoks), i + 1
            return None
        if i < n and d[i].t == 'id':
            name = d[i]
            j = i + 1
            # qualified name a::b
            while j + 1 < n and d[j].t == 'op' and d[j].v == '::' and d[j + 1].t == 'id':
                name = d[j + 1]
                j += 2
            post = []
            while j < n:
                x = d[j]
                if x.t == '[':
                    post.append(x)
                    j += 1
                    continue
                if x.t == 'op' and x.v == ':' and j + 1 < n:
                    # bitfield
                    post.append(('bits', d[j + 1]))
                    j += 2
                    continue
                break
            return name.v, name.line, (stars, post), j
        if i < n and d[i].t == 'kw' and d[i].v == 'operator':
            return None
        return None

    def deco_string(self, base_toks, deco):
        """Combine base type tokens with declarator decoration to a type string."""
        if isinstance(deco, tuple) and len(deco) == 2 and deco[0] == 'fp':
            return self.join_type(list(base_toks) + deco[1])
        stars, post = deco
        toks = list(base_toks) + stars
        s = self.join_type(toks)
        for p in post:
            if isinstance(p, tuple):
                s += ':' + p[1].v
            else:
                s += square_repr(p)
        return s

    def typeref_from(self, base, deco):
        base = [t for t in base if not (t.t == 'kw' and t.v in TYPE_SPEC_KW)]
        base = self.strip_attrs(base)
        if not base:
            return None
        # struct X ... => struct:X...
        if base[0].t == 'kw' and base[0].v in ('struct', 'union', 'enum', 'class') and len(base) >= 2 and base[1].t == 'id':
            k = {'struct': 'struct', 'union': 'union', 'enum': 'enum', 'class': 'class'}[base[0].v]
            s = self.deco_string(base[1:], deco)
            return (k, s)
        return ('typename', self.deco_string(base, deco))

    def typeref_of(self, toks):
        toks = [t for t in toks if not (t.t == 'kw' and t.v in TYPE_SPEC_KW)]
        if not toks:
            return None
        if toks[0].t == 'kw' and toks[0].v in ('struct', 'union', 'enum', 'class') and len(toks) >= 2 and toks[1].t == 'id':
            return (toks[0].v, self.join_type(toks[1:]))
        return ('typename', self.join_type(toks))

    def join_type(self, toks):
        return norm_join(toks)

    # ------------------------------------------------------------------
    def decl_kind(self, scope, is_extern):
        if scope.kind in ('class', 'struct', 'union'):
            return 'm'
        if scope.kind in ('function', 'block'):
            return 'x' if is_extern else 'l'
        return 'x' if is_extern else 'v'

    def make_var(self, name, line, scope, spec_toks, typeref, term, qualified, endline=None):
        is_extern = any(t.t == 'kw' and t.v == 'extern' for t in spec_toks)
        is_static = any(t.t == 'kw' and t.v == 'static' for t in spec_toks)
        kind = self.decl_kind(scope, is_extern)
        if qualified:
            kind = 'm'
        fs = False
        if kind in ('m',):
            fs = not self.header
            if qualified:
                fs = False
        elif kind == 'l':
            fs = True
        elif kind == 'v' or kind == 'x':
            fs = is_static and not self.header
        idx = self.make(name, kind, line, scope if not isinstance(qualified, tuple) else None, typeref=typeref, file_scope=fs)
        t = self.ctx.cork[idx]
        if isinstance(qualified, tuple):
            t.scope_kind = self.K['c'] if 'c' in self.K else self.K['s']
            t.scope_name = qualified[1]
        if kind != 'x' or True:
            t.end = endline if endline is not None else term.line
        acc = self.member_access(scope)
        if acc and kind == 'm':
            t.access = acc
        if kind == 'm' and scope.kind in ('class', 'struct', 'union'):
            t.nth = scope.nth
            scope.nth += 1
        props = []
        for x in spec_toks:
            if x.t == 'kw' and x.v in ('static', 'extern', 'inline', 'mutable', 'register', 'thread_local', 'constexpr', 'volatile') and x.v not in props:
                pass
        return idx

    def handle_vars(self, toks, scope, term):
        # filter out things that are clearly not declarations
        if not toks:
            return
        t0 = toks[0]
        if t0.t in ('num', 'str', 'chr'):
            return
        if t0.t == 'op' and t0.v not in ('::', '*'):
            return
        self.handle_decl_list(toks, scope, None, term.line, term)

    def handle_decl_list(self, toks, scope, force_kind, endline, term=None):
        decls = split_top(toks, ',')
        if not decls or not decls[0]:
            return
        info = self.split_type_and_declarator(decls[0])
        if info is None:
            return
        base, d = info
        # reject expressions: base must look like a type
        if not self.looks_like_type(base):
            return
        spec = [t for t in base if t.t == 'kw' and t.v in TYPE_SPEC_KW]
        for dd in [d] + decls[1:]:
            r = self.parse_declarator(dd)
            if r is None:
                continue
            nm, nline, deco, after = r
            # after declarator: must be end, '=' init, or '(' ctor args / '{' init (C++)
            if after < len(dd):
                x = dd[after]
                if not ((x.t == 'op' and x.v == '=') or x.t == '(' or x.t == '{'):
                    continue
                if x.t == '(' and not self.cxx:
                    continue
            tr = self.typeref_from(base, deco)
            q = False
            # qualified variable definition int N::var = 3;
            if dd and len(dd) >= 3:
                names = []
                k = 0
                while k < len(dd) and dd[k].t == 'op' and dd[k].v in ('*', '&'):
                    k += 1
                while k + 1 < len(dd) and dd[k].t == 'id' and dd[k + 1].t == 'op' and dd[k + 1].v == '::':
                    names.append(dd[k].v)
                    k += 2
                if names:
                    sn = '::'.join(names)
                    q = ('q', sn)
            self.make_var(nm, nline, scope, spec, tr, term if term is not None else T(';', ';', endline, 0), q, endline)

    def looks_like_type(self, base):
        b = [t for t in base if not (t.t == 'kw' and t.v in TYPE_SPEC_KW)]
        if not b:
            return False
        for t in b:
            if t.t in ('num', 'str', 'chr'):
                return False
            if t.t == 'op' and t.v not in ('::', '*', '&', '&&', '<', '>', ',', '>>'):
                return False
            if t.t == 'kw' and t.v in CONTROL_KW:
                return False
            if t.t == 'kw' and t.v in ('return', 'goto', 'case', 'sizeof', 'new', 'delete', 'throw'):
                return False
        if b[0].t == 'op' and b[0].v in ('*', '&'):
            return False
        return True

    # ------------------------------------------------------------------
    def find_function(self, toks):
        """Locate function name and parameter chain. Returns (name_tokens_start, name_index, paren_index) or None."""
        n = len(toks)
        for i in range(n):
            t = toks[i]
            if t.t != '(':
                continue
            if i == 0:
                continue
            prev = toks[i - 1]
            # operator overloading
            name_end = i - 1
            if prev.t == 'id' or (prev.t == 'kw' and prev.v in ('operator',)):
                pass
            elif prev.t == 'op' or prev.t == 'kw' or prev.t == '[' or prev.t == '(':
                # operator() etc
                op_i = None
                for k in range(i - 1, max(-1, i - 5), -1):
                    if toks[k].t == 'kw' and toks[k].v == 'operator':
                        op_i = k
                        break
                if op_i is None:
                    if prev.t == '(' and prev.chain is not None:
                        # int (*getfn(void))(int) - handled separately
                        pass
                    continue
            return i
        return None

    def try_function(self, toks, scope, is_def, tparams):
        n = len(toks)
        # function returning function pointer: int (*getfn(void))(int)
        for i, t in enumerate(toks):
            if t.t == '(' and t.chain and len(t.chain) >= 3 and t.chain[0].t == 'op' and t.chain[0].v == '*' \
                    and t.chain[1].t == 'id' and t.chain[2].t == '(' and i + 1 < n and toks[i + 1].t == '(' and i > 0:
                name = t.chain[1]
                params = t.chain[2]
                base = toks[:i]
                rt = [x for x in base if not (x.t == 'kw' and x.v in TYPE_SPEC_KW)]
                pc = T('(', '(', 0, 0)
                pc.chain = [t.chain[0]]
                rtype = norm_join(rt + [pc] + toks[i + 1:i + 2])
                kind = 'f' if is_def else 'p'
                return self.emit_function(name.v, name.line, scope, kind, base, params, toks[i + 2:], ('typename', rtype), None, tparams, is_def)
        pi = self.find_function(toks)
        if pi is None:
            return False
        params = toks[pi]
        # name
        ni = pi - 1
        name_toks = []
        prev = toks[ni]
        if prev.t == 'id':
            j = ni
            name_toks = [prev]
            if j - 1 >= 0 and toks[j - 1].t == 'op' and toks[j - 1].v == '~':
                name_toks = [toks[j - 1], prev]
                j -= 1
            start = j
        else:
            # operator
            k = ni
            while k >= 0 and not (toks[k].t == 'kw' and toks[k].v == 'operator'):
                k -= 1
            start = k
            name_toks = toks[k:pi]
        # qualifiers A::B::
        qual = []
        k = start - 1
        while k >= 1 and toks[k].t == 'op' and toks[k].v == '::':
            q = toks[k - 1]
            if q.t == 'id':
                qual.insert(0, q.v)
                k -= 2
            elif q.t == 'op' and q.v == '>':
                # template args A<T>::f
                depth = 0
                m = k - 1
                while m >= 0:
                    if toks[m].t == 'op' and toks[m].v == '>':
                        depth += 1
                    elif toks[m].t == 'op' and toks[m].v == '<':
                        depth -= 1
                        if depth == 0:
                            break
                    m -= 1
                if m >= 1 and toks[m - 1].t == 'id':
                    qual.insert(0, toks[m - 1].v)
                    k = m - 2
                else:
                    break
            else:
                break
        if k >= 0 and k < start and toks[k].t == 'op' and toks[k].v == '::' and k == 0:
            k -= 1
        base = toks[:k + 1] if k >= 0 else []
        after = toks[pi + 1:]
        # validate after
        ok = True
        j = 0
        while j < len(after):
            x = after[j]
            if x.t == 'kw' and x.v in ('const', 'volatile', 'override', 'final', 'noexcept', 'throw', 'mutable',
                                        '__attribute__', 'try', 'requires', 'restrict'):
                j += 1
                if j < len(after) and after[j].t == '(':
                    j += 1
                continue
            if x.t == 'id' and x.v in ('override', 'final'):
                j += 1
                continue
            if x.t == 'op' and x.v in ('&', '&&'):
                j += 1
                continue
            if x.t == 'op' and x.v == '->':
                j = len(after)
                break
            if x.t == 'op' and x.v == '=':
                # = 0, = default, = delete
                if j + 1 < len(after) and (after[j + 1].v in ('0', 'default', 'delete')):
                    j += 2
                    continue
                ok = False
                break
            if x.t == 'op' and x.v == ':' and is_def:
                j = len(after)
                break
            if x.t == '[':
                j += 1
                continue
            if x.t == 'id' and not is_def:
                # macro like __THROW or attribute macro
                j += 1
                if j < len(after) and after[j].t == '(':
                    j += 1
                continue
            if x.t == 'id' and is_def:
                # K&R declarations or macros
                j = len(after)
                break
            if x.t == 'kw' and is_def:
                j = len(after)
                break
            ok = False
            break
        if not ok:
            return False
        rt_toks = [x for x in base if not (x.t == 'kw' and x.v in TYPE_SPEC_KW)]
        rt_toks = self.strip_attrs(rt_toks)
        # Validate base: in C, need a return type; in C++ ctors allowed
        is_ctor = False
        if not rt_toks:
            if not self.cxx:
                if is_def and not base:
                    # K&R/implicit int "main() {"
                    pass
                elif not base:
                    return False
            else:
                is_ctor = True
        else:
            if not self.looks_like_type(rt_toks):
                return False
            if not is_def and not self.cxx and False:
                return False
        # params must look like a parameter list for prototypes
        if not is_def and not self.params_look_like_decl(params, scope, rt_toks):
            return False
        if name_toks and name_toks[0].t == 'id' and name_toks[0].v in ('if', 'while', 'for', 'switch', 'return', 'sizeof'):
            return False
        if name_toks[0].t == 'kw' and name_toks[0].v == 'operator':
            name = 'operator ' + norm_operator(name_toks[1:])
            name = name.rstrip()
        else:
            name = ''.join(t.v for t in name_toks)
        line = name_toks[0].line
        rtype = None
        if rt_toks:
            rtype = self.typeref_of(rt_toks)
        # trailing return type
        for j, x in enumerate(after):
            if x.t == 'op' and x.v == '->':
                rr = []
                for y in after[j + 1:]:
                    if y.t == 'kw' and y.v in ('override', 'final'):
                        break
                    if y.t == 'op' and y.v in ('=', ':'):
                        break
                    rr.append(y)
                if rr:
                    rtype = self.typeref_of(rr)
                break
        if rtype is not None and rtype[0] == 'typename' and rtype[1] == 'auto' and False:
            pass
        kind = 'f' if is_def else 'p'
        return self.emit_function(name, line, scope, kind, base, params, after, rtype, qual, tparams, is_def)

    def params_look_like_decl(self, params, scope, rt_toks):
        ch = params.chain or []
        if not ch:
            return True
        if len(ch) == 1 and ch[0].t == 'kw' and ch[0].v == 'void':
            return True
        for part in split_top(ch, ','):
            if not part:
                continue
            p = [t for t in part if not (t.t == 'kw' and t.v in ('const', 'volatile', 'register'))]
            if not p:
                continue
            if p[0].t in ('num', 'str', 'chr'):
                return False
            if p[0].t == 'op' and p[0].v not in ('...', '::', '&', '*'):
                return False
            if p[0].t == 'op' and p[0].v in ('&', '*') and scope.kind in ('function', 'block'):
                return False
        if scope.kind in ('function', 'block'):
            # inside functions, calls look like prototypes; require a type-ish first param with 2 tokens
            for part in split_top(ch, ','):
                ids = [t for t in part if t.t in ('id', 'kw')]
                if len(part) == 1 and part[0].t == 'id':
                    return False
        return True

    def emit_function(self, name, line, scope, kind, base, params, after, rtype, qual, tparams, is_def):
        ctx = self.ctx
        is_static = any(t.t == 'kw' and t.v == 'static' for t in base)
        sc = scope
        if scope.kind in ('function', 'block') and not is_def:
            # prototype inside function body
            pass
        fs = False
        if kind == 'p':
            fs = not self.header
        elif is_static and not self.header and scope.kind not in ('class', 'struct', 'union'):
            fs = True
        if scope.kind in ('class', 'struct', 'union') and not self.header:
            fs = True
        if qual:
            fs = is_static and not self.header and False
        idx = self.make(name, kind, line, None if qual else scope, file_scope=fs)
        t = ctx.cork[idx]
        if qual:
            qn = '::'.join(qual)
            if scope.idx:
                qn = full_name(ctx.cork[scope.idx]) + '::' + qn
            t.scope_kind = self.K['c'] if 'c' in self.K else self.K['s']
            t.scope_name = qn
        if rtype is not None:
            t.typeref = rtype
        t.signature = self.signature(params, after)
        acc = self.member_access(scope)
        if acc and not qual:
            t.access = acc
        if tparams and self.cxx:
            self.make_tparams(tparams, idx)
        # parameters
        if self.K['z'].enabled or True:
            self.make_params(params, idx, is_def)
        if is_def:
            fscope = Scope('function', idx, None, name)
            end = self.parse_block(fscope, True)
            t.end = end.line
        else:
            t.end = params.endline if not after else max(params.endline, after[-1].endline)
        return True

    def signature(self, params, after):
        s = norm_join([params])
        quals = []
        for x in after:
            if x.t == 'kw' and x.v in ('const', 'volatile', 'noexcept', 'override', 'final') or (x.t == 'id' and x.v in ('override', 'final')):
                quals.append(x.v)
            elif x.t == 'op' and x.v in ('&', '&&'):
                quals.append(x.v)
            elif x.t == 'op' and x.v in ('=', ':', '->'):
                break
            else:
                break
        if quals and self.cxx:
            s += ' ' + ' '.join(q for q in quals if q in ('const', 'volatile', '&', '&&'))
            s = s.rstrip()
        return s

    def make_params(self, params, fidx, is_def):
        ch = params.chain or []
        if not ch:
            return
        if len(ch) == 1 and ch[0].t == 'kw' and ch[0].v == 'void':
            return
        zk = self.K['z']
        nth = 0
        for part in split_top(ch, ','):
            if not part:
                continue
            if len(part) == 1 and part[0].t == 'op' and part[0].v == '...':
                continue
            # default value
            eq = None
            for k, x in enumerate(part):
                if x.t == 'op' and x.v == '=':
                    eq = k
                    break
            if eq is not None:
                part = part[:eq]
            info = self.split_type_and_declarator(part)
            if info is not None:
                base, d = info
                r = self.parse_declarator(d)
                if r is not None and self.looks_like_type(base):
                    nm, nline, deco, _ = r
                    tr = self.typeref_from(base, deco)
                    if zk.enabled:
                        pidx = self.ctx.make_tag(nm, zk, line=nline, scope=fidx, lang=self.L)
                        pt = self.ctx.cork[pidx]
                        pt.typeref = tr
                        pt.file_scope = True
                    nth += 1
                    continue
            # unnamed parameter (K&R names alone handled as unnamed? no)
            if len(part) == 1 and part[0].t == 'id' and not self.cxx:
                # K&R identifier list
                continue
            if zk.enabled:
                nm = self.anon('z')
                tr = self.typeref_of(part)
                pidx = self.ctx.make_tag(nm, zk, line=part[0].line, scope=fidx, lang=self.L)
                pt = self.ctx.cork[pidx]
                pt.typeref = tr
                pt.file_scope = True
                pt.add_extra('anonymous')
            nth += 1

# ---------------------------------------------------------------------------
# helpers

def split_top(toks, sep):
    out = []
    cur = []
    for t in toks:
        if (t.t == 'op' and t.v == sep) or (t.t == sep):
            out.append(cur)
            cur = []
        else:
            cur.append(t)
    out.append(cur)
    return out

def split_top_angle(toks, sep):
    out = []
    cur = []
    depth = 0
    for t in toks:
        if t.t == 'op' and t.v == '<':
            depth += 1
        elif t.t == 'op' and t.v == '>':
            depth -= 1
        elif t.t == 'op' and t.v == '>>':
            depth -= 2
        if depth <= 0 and t.t == 'op' and t.v == sep:
            out.append(cur)
            cur = []
        else:
            cur.append(t)
    out.append(cur)
    return out

def join_plain(toks):
    return ''.join(t.v if t.chain is None else norm_join([t]) for t in toks)

def square_repr(t):
    ch = t.chain or []
    if len(ch) == 1 and ch[0].t == 'num':
        return '[' + ch[0].v + ']'
    return '[]'

def norm_operator(toks):
    s = ''
    for t in toks:
        if t.chain is not None:
            s += '()' if t.t == '(' else '[]'
        else:
            if s and (t.t in ('id', 'kw')) and (s[-1].isalnum() or s[-1] == '_'):
                s += ' '
            s += t.v
    return s

def norm_join(toks):
    out = []
    n = len(toks)
    for i, t in enumerate(toks):
        nx = toks[i + 1] if i + 1 < n else None
        if t.chain is not None:
            if t.t == '(':
                out.append('(' + norm_join(t.chain) + ')')
            elif t.t == '[':
                out.append(square_repr(t))
            else:
                out.append('{' + norm_join(t.chain) + '}')
            sp = nx is not None and (nx.t in ('id', 'kw'))
        elif t.t == 'kw':
            out.append(t.v)
            sp = nx is not None and t.v != 'operator' and (nx.t in ('(', 'id', 'kw') and nx.chain is not None or nx.t in ('id', 'kw') or (nx.t == 'op' and nx.v in ('*', '&', '&&'))) and not (nx.t == '[')
        elif t.t == 'id' or (t.t == 'op' and t.v == '>'):
            out.append(t.v)
            sp = nx is not None and ((nx.t == '(' and nx.chain is not None) or nx.t in ('id', 'kw') or (nx.t == 'op' and nx.v in ('*', '&', '&&')))
        elif t.t == 'op' and t.v == ',':
            out.append(',')
            sp = False
        elif t.t == 'op' and t.v in ('*', '&', '&&'):
            out.append(t.v)
            sp = nx is not None and (nx.t in ('id', 'kw') or (nx.chain is not None and nx.t in ('(', '[')))
        else:
            out.append(t.v)
            sp = False
        if sp:
            out.append(' ')
    return ''.join(out)

def parse_c(ctx):
    _run(ctx, 'C')

def parse_cpp(ctx):
    _run(ctx, 'C++')

def parse_cuda(ctx):
    _run(ctx, 'CUDA')

def _run(ctx, kind):
    L = ctx.lang
    L.default_sep = '::'
    L.qualified = True
    p = Parser(ctx, kind)
    try:
        p.parse()
    except RecursionError:
        pass
