MODIFIERS = set('public protected private static final abstract native synchronized transient volatile strictfp default sealed non-sealed'.split())

class Tok:
    __slots__ = ('t', 'v', 'line', 'pos')
    def __init__(self, t, v, line, pos):
        self.t = t; self.v = v; self.line = line; self.pos = pos
    def __repr__(self):
        return '%s:%s' % (self.t, self.v)

def tokenize(text):
    toks = []
    i = 0
    n = len(text)
    line = 1
    while i < n:
        c = text[i]
        if c == '\n':
            line += 1; i += 1; continue
        if c in ' \t\r\f':
            i += 1; continue
        if c == '/' and i + 1 < n and text[i + 1] == '/':
            j = text.find('\n', i)
            i = n if j < 0 else j
            continue
        if c == '/' and i + 1 < n and text[i + 1] == '*':
            j = text.find('*/', i + 2)
            j = n if j < 0 else j + 2
            line += text.count('\n', i, j)
            i = j
            continue
        if c == '"':
            if text.startswith('"""', i):
                j = text.find('"""', i + 3)
                j = n if j < 0 else j + 3
                line += text.count('\n', i, j)
                toks.append(Tok('str', text[i:j], line, i))
                i = j
                continue
            j = i + 1
            while j < n and text[j] != '"' and text[j] != '\n':
                if text[j] == '\\':
                    j += 1
                j += 1
            toks.append(Tok('str', text[i:j + 1], line, i))
            i = j + 1
            continue
        if c == "'":
            j = i + 1
            while j < n and text[j] != "'" and text[j] != '\n':
                if text[j] == '\\':
                    j += 1
                j += 1
            toks.append(Tok('chr', text[i:j + 1], line, i))
            i = j + 1
            continue
        if c == '_' or c == '$' or isalpha(c) or ord(c) >= 0x80:
            j = i + 1
            while j < n and (text[j] == '_' or text[j] == '$' or isalnum(text[j]) or ord(text[j]) >= 0x80):
                j += 1
            w = text[i:j]
            if w == 'non' and text.startswith('-sealed', j):
                w = 'non-sealed'
                j += 7
            toks.append(Tok('kw' if w in KEYWORDS else 'id', w, line, i))
            i = j
            continue
        if isdigit(c):
            j = i + 1
            while j < n and (isalnum(text[j]) or text[j] in '._'):
                j += 1
            toks.append(Tok('num', text[i:j], line, i))
            i = j
            continue
        if text.startswith('...', i):
            toks.append(Tok('op', '...', line, i)); i += 3; continue
        if text.startswith('::', i) or text.startswith('->', i):
            toks.append(Tok('op', text[i:i + 2], line, i)); i += 2; continue
        toks.append(Tok('op', c, line, i))
        i += 1
    toks.append(Tok('eof', '', line, n))
    return toks

class Parser:
    def __init__(self, ctx):
        self.ctx = ctx
        self.L = ctx.lang
        self.toks = tokenize(ctx.text)
        self.i = 0

    def peek(self, k=0):
        j = self.i + k
        if j < len(self.toks):
            return self.toks[j]
        return self.toks[-1]

    def next(self):
        t = self.toks[self.i]
        if self.i < len(self.toks) - 1:
            self.i += 1
        return t

    def is_op(self, t, v):
        return t.t == 'op' and t.v == v

    def skip_balanced(self, open_c, close_c):
        """Current token is open_c; skip to after matching close. Return closing token."""
        depth = 0
        while True:
            t = self.next()
            if t.t == 'eof':
                return t
            if t.t == 'op' and t.v == open_c:
                depth += 1
            elif t.t == 'op' and t.v == close_c:
                depth -= 1
                if depth == 0:
                    return t

    def skip_generic(self):
        # current token '<'
        depth = 0
        while True:
            t = self.next()
            if t.t == 'eof':
                return
            if self.is_op(t, '<'):
                depth += 1
            elif self.is_op(t, '>'):
                depth -= 1
                if depth == 0:
                    return
            elif t.t == 'op' and t.v in (';', '{', '}'):
                return

    def skip_annotation(self):
        # current '@'
        self.next()
        if self.peek().t == 'kw' and self.peek().v == 'interface':
            return False
        # qualified name
        self.next()
        while self.is_op(self.peek(), '.') and self.peek(1).t in ('id', 'kw'):
            self.next(); self.next()
        if self.is_op(self.peek(), '('):
            self.skip_balanced('(', ')')
        return True

    def text_between(self, a, b):
        """Source text from token a start to token b end (inclusive)."""
        return self.ctx.text[a.pos:b.pos + len(b.v)]

    def parse(self):
        self.parse_body(None, 'file')

    def make(self, name, kind, line, scope, **kw):
        idx = self.ctx.make_tag(name, kind, line=line, scope=scope or 0)
        t = self.ctx.cork[idx]
        for k, v in kw.items():
            setattr(t, k, v)
        return idx

    def parse_body(self, scope, ctype):
        """Parse declarations until '}' (consumed) or EOF. Returns closing token."""
        first_enum = ctype == 'enum'
        if first_enum:
            r = self.parse_enum_constants(scope)
            if r is not None:
                return r
        while True:
            t = self.peek()
            if t.t == 'eof':
                return t
            if self.is_op(t, '}'):
                self.next()
                return t
            if self.is_op(t, ';'):
                self.next()
                continue
            self.parse_member(scope, ctype)

    def parse_enum_constants(self, scope):
        while True:
            t = self.peek()
            if t.t == 'eof':
                return t
            if self.is_op(t, '}'):
                self.next()
                return t
            if self.is_op(t, ';'):
                self.next()
                return None
            if self.is_op(t, '@'):
                self.skip_annotation()
                continue
            if self.is_op(t, ','):
                self.next()
                continue
            if t.t == 'id':
                self.next()
                idx = self.make(t.v, 'e', t.line, scope, access='public', file_scope=True)
                endt = t
                if self.is_op(self.peek(), '('):
                    endt = self.skip_balanced('(', ')')
                if self.is_op(self.peek(), '{'):
                    self.next()
                    endt = self.parse_body(None, 'anonclass', ) if False else self.parse_anon_body(scope)
                self.ctx.cork[idx].end = endt.line
                continue
            # unexpected: treat as member start
            return None

    def parse_anon_body(self, outer_scope):
        # body of an enum constant class: members are tagged without scope (quirk)
        while True:
            t = self.peek()
            if t.t == 'eof':
                return t
            if self.is_op(t, '}'):
                self.next()
                return t
            if self.is_op(t, ';'):
                self.next()
                continue
            self.parse_member(None, 'anon', qual_scope=outer_scope)

    def parse_member(self, scope, ctype, qual_scope=None):
        mods = []
        start = self.peek()
        while True:
            t = self.peek()
            if self.is_op(t, '@'):
                if self.peek(1).t == 'kw' and self.peek(1).v == 'interface':
                    break
                self.skip_annotation()
                continue
            if t.t == 'kw' and t.v in MODIFIERS:
                if t.v == 'default' and ctype == 'switch':
                    break
                mods.append(t.v)
                self.next()
                continue
            break
        t = self.peek()
        if t.t == 'kw' and t.v == 'package' and scope is None:
            self.next()
            first = self.peek()
            parts = []
            while True:
                x = self.next()
                if x.t == 'eof' or self.is_op(x, ';'):
                    break
                parts.append(x.v)
            self.make(''.join(parts), 'p', first.line, None, end=x.line)
            return
        if t.t == 'kw' and t.v == 'import':
            while True:
                x = self.next()
                if x.t == 'eof' or self.is_op(x, ';'):
                    break
            return
        if self.is_op(t, '@') and self.peek(1).t == 'kw' and self.peek(1).v == 'interface':
            self.next()
            self.next()
            self.parse_type_decl('a', mods, scope, ctype)
            return
        if t.t == 'kw' and t.v in ('class', 'interface', 'enum') or (t.t in ('id', 'kw') and t.v == 'record' and self.peek(1).t == 'id' and self.peek(2).t == 'op' and self.peek(2).v in ('(', '<')):
            self.next()
            if t.v == 'record':
                self.parse_record(mods, scope, ctype)
                return
            kind = {'class': 'c', 'interface': 'i', 'enum': 'g'}[t.v]
            self.parse_type_decl(kind, mods, scope, ctype)
            return
        if self.is_op(t, '{'):
            # initializer block
            self.skip_balanced('{', '}')
            return
        # method or field
        if self.is_op(t, '<'):
            self.skip_generic()
        # type
        type_start = self.peek()
        name_tok = None
        # constructor: Name '('
        if self.peek().t == 'id' and self.is_op(self.peek(1), '('):
            name_tok = self.next()
        else:
            if not self.skip_type():
                self.next()
                return
            if self.peek().t != 'id':
                # skip to ; or balanced
                self.recover()
                return
            name_tok = self.next()
        if self.is_op(self.peek(), '('):
            # method
            p_open = self.peek()
            p_close = self.skip_balanced('(', ')')
            sig = collapse(self.ctx.text[p_open.pos:p_close.pos + 1])
            # array dims, throws
            while True:
                x = self.peek()
                if self.is_op(x, '['):
                    self.skip_balanced('[', ']')
                    continue
                if x.t == 'kw' and x.v == 'throws':
                    self.next()
                    while True:
                        y = self.peek()
                        if y.t == 'eof' or (y.t == 'op' and y.v in ('{', ';')):
                            break
                        if y.t == 'kw' and y.v == 'default':
                            break
                        self.next()
                    continue
                if x.t == 'kw' and x.v == 'default':
                    # annotation default value
                    self.next()
                    while True:
                        y = self.peek()
                        if y.t == 'eof' or self.is_op(y, ';'):
                            break
                        if self.is_op(y, '{'):
                            self.skip_balanced('{', '}')
                            continue
                        self.next()
                    continue
                break
            acc = self.access(mods, ctype)
            idx = self.make(name_tok.v, 'm', name_tok.line, scope, signature=sig)
            tg = self.ctx.cork[idx]
            if acc:
                tg.access = acc
            if 'abstract' in mods:
                tg.implementation = 'abstract'
            if qual_scope is not None:
                tg.qual_name = full_name(self.ctx.cork[qual_scope]) + '.' + name_tok.v
            x = self.peek()
            if self.is_op(x, '{'):
                endt = self.parse_method_body(idx)
                tg.end = endt.line
            elif self.is_op(x, ';'):
                self.next()
                tg.end = x.line
            return
        # field(s)
        acc = self.access(mods, ctype)
        names = [name_tok]
        idxs = []
        while True:
            idx = self.make(names[-1].v, 'f', names[-1].line, scope)
            tg = self.ctx.cork[idx]
            if acc:
                tg.access = acc
            if 'private' in mods:
                tg.file_scope = True
            idxs.append(idx)
            # skip array dims / initializer
            endt = None
            while True:
                x = self.peek()
                if x.t == 'eof':
                    endt = x
                    break
                if self.is_op(x, '['):
                    self.skip_balanced('[', ']')
                    continue
                if self.is_op(x, '='):
                    self.next()
                    endt = self.skip_initializer()
                    continue
                break
            x = self.peek()
            if self.is_op(x, ','):
                self.next()
                if self.peek().t == 'id':
                    names.append(self.next())
                    continue
            if self.is_op(x, ';'):
                self.next()
                for i2 in idxs:
                    self.ctx.cork[i2].end = x.line
            break

    def skip_initializer(self):
        while True:
            x = self.peek()
            if x.t == 'eof':
                return x
            if x.t == 'op' and x.v in (',', ';'):
                return x
            if self.is_op(x, '('):
                self.skip_balanced('(', ')')
                continue
            if self.is_op(x, '{'):
                self.skip_balanced('{', '}')
                continue
            if self.is_op(x, '['):
                self.skip_balanced('[', ']')
                continue
            if self.is_op(x, '}'):
                return x
            self.next()

    def recover(self):
        while True:
            x = self.peek()
            if x.t == 'eof':
                return
            if self.is_op(x, ';'):
                self.next()
                return
            if self.is_op(x, '{'):
                self.skip_balanced('{', '}')
                return
            if self.is_op(x, '}'):
                return
            if self.is_op(x, '('):
                self.skip_balanced('(', ')')
                continue
            self.next()

    def skip_type(self):
        t = self.peek()
        if t.t not in ('id', 'kw'):
            return False
        if t.t == 'kw' and t.v not in ('boolean', 'byte', 'char', 'short', 'int', 'long', 'float', 'double', 'void', 'var'):
            return False
        self.next()
        while True:
            x = self.peek()
            if self.is_op(x, '<'):
                self.skip_generic()
                continue
            if self.is_op(x, '.') and self.peek(1).t in ('id', 'kw'):
                self.next(); self.next()
                continue
            if self.is_op(x, '['):
                if self.is_op(self.peek(1), ']'):
                    self.next(); self.next()
                    continue
                break
            if self.is_op(x, '@'):
                self.skip_annotation()
                continue
            if self.is_op(x, '...'):
                self.next()
                continue
            break
        return True

    def access(self, mods, ctype):
        for a in ('public', 'protected', 'private'):
            if a in mods:
                return a
        if ctype in ('interface', 'annotation'):
            return 'public'
        if ctype == 'anon':
            return None
        return 'default'

    def parse_method_body(self, midx):
        # current '{'
        return self.skip_balanced('{', '}')

    def parse_type_decl(self, kind, mods, scope, ctype):
        name_tok = self.peek()
        if name_tok.t != 'id':
            self.recover()
            return
        self.next()
        if self.is_op(self.peek(), '<'):
            self.skip_generic()
        inherits = []
        while True:
            x = self.peek()
            if x.t == 'kw' and x.v in ('extends', 'implements', 'permits'):
                self.next()
                is_permits = x.v == 'permits'
                while True:
                    y = self.peek()
                    if y.t in ('id',) or (y.t == 'kw' and y.v not in ('extends', 'implements', 'permits')):
                        nm = y.v
                        self.next()
                        while self.is_op(self.peek(), '.') and self.peek(1).t == 'id':
                            self.next()
                            nm += '.' + self.next().v
                        if self.is_op(self.peek(), '<'):
                            self.skip_generic()
                        if not is_permits:
                            inherits.append(nm)
                        if self.is_op(self.peek(), ','):
                            self.next()
                            continue
                    break
                continue
            break
        acc = self.access(mods, ctype) if scope is not None else None
        idx = self.make(name_tok.v, kind, name_tok.line, scope)
        tg = self.ctx.cork[idx]
        if inherits:
            tg.inherits = ','.join(inherits)
        if acc:
            tg.access = acc
        if self.is_op(self.peek(), '{'):
            self.next()
            sub = {'c': 'class', 'i': 'interface', 'g': 'enum', 'a': 'annotation'}[kind]
            endt = self.parse_body(idx, sub)
            tg.end = endt.line
        else:
            self.recover()

    def parse_record(self, mods, scope, ctype):
        name_tok = self.next()
        if self.is_op(self.peek(), '<'):
            self.skip_generic()
        p_open = self.peek()
        sig = None
        if self.is_op(p_open, '('):
            p_close = self.skip_balanced('(', ')')
            sig = collapse(self.ctx.text[p_open.pos:p_close.pos + 1])
        while not (self.is_op(self.peek(), '{') or self.peek().t == 'eof' or self.is_op(self.peek(), ';')):
            self.next()
        idx = self.make(name_tok.v, 'm', name_tok.line, None, signature=sig)
        tg = self.ctx.cork[idx]
        if self.is_op(self.peek(), '{'):
            self.next()
            endt = self.parse_record_body()
            tg.end = endt.line

    def parse_record_body(self):
        while True:
            t = self.peek()
            if t.t == 'eof':
                return t
            if self.is_op(t, '}'):
                self.next()
                return t
            if self.is_op(t, ';'):
                self.next()
                continue
            # compact constructor: Name {
            if t.t == 'id' and self.is_op(self.peek(1), '{'):
                self.next()
                self.skip_balanced('{', '}')
                continue
            self.parse_member(None, 'anon')

def collapse(s):
    out = []
    sp = False
    for c in s:
        if c in ' \t\r\n':
            sp = True
            continue
        if sp and out:
            out.append(' ')
        sp = False
        out.append(c)
    return ''.join(out)

def parse(ctx):
    L = ctx.lang
    L.qualified = True
    p = Parser(ctx)
    p.parse()
