            if self.isop(self.peek(), '*'):
                self.next()
                gen = True
            nt = self.peek()
            if self.isop(nt, '{') and 'static' in mods:
                self.next()
                self.statements(cidx, True, '}')
                continue
            if nt.t == 'id' or nt.t == 'num':
                name = nt.v
                self.next()
            elif nt.t == 'str':
                name = nt.v[1:-1]
                self.next()
            elif self.isop(nt, '['):
                a = nt
                b = self.skip_group('[', ']')
                name = self.ctx.text[a.pos:b.end]
            else:
                self.next()
                continue
            acc = 'private' if name.startswith('#') else None
            if self.isop(self.peek(), '('):
                sig = self.params_sig()
                kind = 'm'
                if 'get' in mods:
                    kind = 'G'
                elif 'set' in mods:
                    kind = 'S'
                elif gen:
                    kind = 'g'
                idx = self.make(name, kind, nt.line, cidx, signature=sig)
                if acc:
                    self.ctx.cork[idx].access = acc
                if self.isop(self.peek(), '{'):
                    self.function_body(idx)
                continue
            # field
            idx = self.make(name, 'M', nt.line, cidx)
            if acc:
                self.ctx.cork[idx].access = acc
            if self.isop(self.peek(), '='):
                self.next()
                self.expression(cidx, True, stop_semicolon=True)
            if self.isop(self.peek(), ';'):
                self.next()

    def var_decl(self, kw, scope, in_func):
        while True:
            t = self.peek()
            if t.t == 'id':
                name = self.next()
                if self.isop(self.peek(), '='):
                    self.next()
                    self.assigned_value(name.v, name.line, kw, scope, in_func)
                else:
                    if not in_func:
                        self.make(name.v, 'C' if kw == 'const' else 'v', name.line, scope)
            elif self.isop(t, '{') or self.isop(t, '['):
                close = '}' if t.v == '{' else ']'
                self.next()
                depth = 1
                while True:
                    x = self.next()
                    if x.t == 'eof':
                        break
                    if x.t == 'op' and x.v in ('{', '['):
                        depth += 1
                    elif x.t == 'op' and x.v in ('}', ']'):
                        depth -= 1
                        if depth == 0:
                            break
                    elif x.t == 'id' and depth == 1 and not in_func:
                        nx = self.peek()
                        if not (self.isop(nx, ':')):
                            self.make(x.v, 'C' if kw == 'const' else 'v', x.line, scope)
                if self.isop(self.peek(), '='):
                    self.next()
                    self.expression(scope, in_func, stop_comma=True)
            else:
                break
            if self.isop(self.peek(), ','):
                self.next()
                continue
            break
        if self.isop(self.peek(), ';'):
            self.next()

    def is_function_value(self):
        """Check if the tokens at current position start a function expression or arrow."""
        t = self.peek()
        k = 0
        if t.t == 'id' and t.v == 'async':
            k = 1
        t = self.peek(k)
        if t.t == 'id' and t.v == 'function':
            return 'function'
        if t.t == 'id' and self.isop(self.peek(k + 1), '=>'):
            return 'arrow1'
        if self.isop(t, '('):
            # find matching ) and check =>
            depth = 0
            j = self.i + k
            while j < len(self.toks):
                x = self.toks[j]
                if self.isop(x, '('):
                    depth += 1
                elif self.isop(x, ')'):
                    depth -= 1
                    if depth == 0:
                        break
                elif x.t == 'eof':
                    return None
                j += 1
            if j + 1 < len(self.toks) and self.isop(self.toks[j + 1], '=>'):
                return 'arrow'
        return None

    def assigned_value(self, name, line, kw, scope, in_func, member_kind=None, prop=False):
        fv = self.is_function_value()
        if fv:
            if self.peek().t == 'id' and self.peek().v == 'async':
                self.next()
            if fv == 'function':
                ft = self.next()
                gen = False
                if self.isop(self.peek(), '*'):
                    self.next(); gen = True
                if self.peek().t == 'id':
                    self.next()
                self.anon_count += 1
                sig = self.params_sig() if self.isop(self.peek(), '(') else '()'
                kind = member_kind or ('g' if gen else 'f')
                idx = self.make(name, kind, line, scope, signature=sig)
                if self.isop(self.peek(), '{'):
                    self.function_body(idx)
                return idx
            if fv == 'arrow1':
                p = self.next()
                sig = '(' + p.v + ')'
            else:
                sig = self.params_sig()
            self.next()  # =>
            kind = member_kind or 'f'
            idx = self.make(name, kind, line, scope, signature=sig)
            if self.isop(self.peek(), '{'):
                self.function_body(idx)
            else:
                self.expression(idx, True, stop_comma=True)
            return idx
        t = self.peek()
        if t.t == 'id' and t.v == 'class':
            return self.class_decl(scope, in_func, (name, line))
        if self.isop(t, '{') and not in_func:
            # object literal: properties first, then the variable
            self.next()
            tmp = self.ctx.make_tag(name, 'v', line=line, scope=scope)
            vt = self.ctx.cork[tmp]
            # temporarily remove to keep order: we re-append after properties
            self.ctx.cork.pop()
            holder = Holder(vt)
            self.object_literal(holder, 'variable')
            vt.index = len(self.ctx.cork)
            self.ctx.cork.append(vt)
            holder.fix(vt.index)
            self.expression(scope, in_func, stop_comma=True)
            return vt.index
        if not in_func:
            k = 'C' if kw == 'const' else 'v'
            idx = self.make(name, k, line, scope)
            self.expression(scope, in_func, stop_comma=True)
            return idx
        self.expression(scope, in_func, stop_comma=True)
        return None

    def object_literal(self, holder, scope_kind_name):
        """After '{'. Parses properties with scope = holder (index fixed later)."""
        while True:
            t = self.peek()
            if t.t == 'eof':
                return
            if self.isop(t, '}'):
                self.next()
                return
            if self.isop(t, ','):
                self.next()
                continue
            if self.isop(t, '...'):
                self.next()
                self.expression(0, True, stop_comma=True)
                continue
            mods = []
            while self.peek().t == 'id' and self.peek().v in ('get', 'set', 'async') and (self.peek(1).t in ('id', 'str', 'num') or self.isop(self.peek(1), '[')):
                mods.append(self.next().v)
            gen = False
            if self.isop(self.peek(), '*'):
                self.next(); gen = True
            nt = self.peek()
            if nt.t in ('id', 'num'):
                name = nt.v
                self.next()
            elif nt.t == 'str':
                name = nt.v[1:-1]
                self.next()
            elif self.isop(nt, '['):
                a = nt
                b = self.skip_group('[', ']')
                name = self.ctx.text[a.pos:b.end]
            else:
                self.expression(0, True, stop_comma=True)
                continue
            if self.isop(self.peek(), '('):
                sig = self.params_sig()
                kind = 'G' if 'get' in mods else ('S' if 'set' in mods else ('g' if gen else 'm'))
                idx = holder.make(self, name, kind, nt.line, signature=sig)
                if self.isop(self.peek(), '{'):
                    self.function_body(idx)
                continue
            if self.isop(self.peek(), ':'):
                self.next()
                fv = self.is_function_value()
                if fv:
                    if self.peek().t == 'id' and self.peek().v == 'async':
                        self.next()
                    if fv == 'function':
                        self.next()
                        gk = False
                        if self.isop(self.peek(), '*'):
                            self.next(); gk = True
                        if self.peek().t == 'id':
                            self.next()
                        self.anon_count += 1
                        sig = self.params_sig() if self.isop(self.peek(), '(') else '()'
                        idx = holder.make(self, name, 'g' if gk else 'm', nt.line, signature=sig)
                        if self.isop(self.peek(), '{'):
                            self.function_body(idx)
                    else:
                        if fv == 'arrow1':
                            p = self.next()
                            sig = '(' + p.v + ')'
                        else:
                            sig = self.params_sig()
                        self.next()
                        idx = holder.make(self, name, 'm', nt.line, signature=sig)
                        if self.isop(self.peek(), '{'):
                            self.function_body(idx)
                        else:
                            self.expression(idx, True, stop_comma=True)
                    continue
                if self.isop(self.peek(), '{'):
                    self.next()
                    sub = SubHolder(holder, name, nt.line, self)
                    self.object_literal(sub, 'property')
                    sub.finish()
                    continue
                holder.make(self, name, 'p', nt.line)
                self.expression(0, True, stop_comma=True)
                continue
            # shorthand
            holder.make(self, name, 'p', nt.line)

    def try_assignment(self, scope, in_func):
        # dotted name followed by '='
        j = self.i
        parts = []
        toks = self.toks
        if toks[j].t != 'id':
            return False
        parts.append(toks[j])
        j += 1
        while j + 1 < len(toks) and self.isop(toks[j], '.') and toks[j + 1].t == 'id':
            parts.append(toks[j + 1])
            j += 2
        if not (j < len(toks) and self.isop(toks[j], '=')):
            return False
        names = [p.v for p in parts]
        self.i = j + 1
        last = parts[-1]
        if names[0] == 'this' and len(names) == 2:
            if scope and self.is_function_value():
                owner = self.ctx.cork[scope]
                owner.extra_data = 'ctor'
                self.assigned_value_scoped(names[1], last.line, scope, 'c', 'm', in_func)
                return True
            self.expression(scope, in_func)
            return True
        if len(names) >= 3 and names[-2] == 'prototype':
            cls = '.'.join(names[:-2])
            self.assigned_value_scoped(names[-1], last.line, None, ('c', cls), 'm', in_func)
            return True
        if len(names) == 2 and names[1] == 'prototype':
            if self.isop(self.peek(), '{'):
                self.next()
                h = Holder(None, ('c', names[0]))
                self.object_literal(h, 'class')
                return True
            self.expression(scope, in_func)
            return True
        if len(names) >= 2:
            if names == ['module', 'exports'] and self.isop(self.peek(), '{'):
                self.next()
                idx = self.make('module.exports', 'p', parts[0].line, scope)
                h = Holder(None, ('p', 'module.exports'))
                self.object_literal(h, 'property')
                return True
            obj = '.'.join(names[:-1])
            fv = self.is_function_value()
            if fv:
                self.assigned_value_scoped(names[-1], last.line, None, ('v', obj), 'f', in_func)
                return True
            self.expression(scope, in_func)
            return True
        # simple assignment NAME = ...
        fv = self.is_function_value()
        if fv and not in_func:
            self.assigned_value(names[0], parts[0].line, 'var', scope, in_func)
            return True
        self.expression(scope, in_func)
        return True

    def assigned_value_scoped(self, name, line, scope, explicit, kind, in_func):
        idx = self.assigned_value(name, line, 'var', scope or 0, True, member_kind=kind)
        if idx is not None and explicit is not None and not isinstance(explicit, str):
            t = self.ctx.cork[idx]
            t.scope = 0
            k = self.L.kind({'c': 'c', 'v': 'v', 'p': 'p'}[explicit[0]])
            t.scope_kind = k
            t.scope_name = explicit[1]
        elif idx is not None and explicit == 'c':
            pass
        return idx

    def expression_group(self, scope, in_func):
        # current '('
        self.next()
        depth = 1
        while True:
            t = self.peek()
            if t.t == 'eof':
                return
            if self.isop(t, '('):
                depth += 1
            elif self.isop(t, ')'):
                depth -= 1
                if depth == 0:
                    self.next()
                    return
            if t.t == 'id' and t.v == 'function':
                self.function_decl(scope, in_func)
                continue
            if self.isop(t, '{'):
                self.next()
                self.statements(scope, in_func, '}')
                continue
            self.next()

    def expression(self, scope, in_func, stop_comma=False, stop_semicolon=False):
        """Skip an expression, tagging nested function expressions."""
        depth = 0
        start_line = self.peek().line
        while True:
            t = self.peek()
            if t.t == 'eof':
                return
            if t.t == 'op':
                v = t.v
                if v in ('(', '['):
                    depth += 1
                    self.next()
                    continue
                if v in (')', ']'):
                    if depth == 0:
                        return
                    depth -= 1
                    self.next()
                    continue
                if v == '{':
                    self.next()
                    self.statements(scope, in_func, '}')
                    continue
                if v == '}':
                    return
                if v == ';' and depth == 0:
                    if not stop_comma and not stop_semicolon:
                        self.next()
                    return
                if v == ',' and depth == 0 and stop_comma:
                    return
                self.next()
                continue
            if t.t == 'id':
                if t.v == 'function':
                    self.function_decl(scope, in_func)
                    continue
                if t.v == 'class':
                    self.class_decl(scope, in_func, None)
                    continue
                if depth == 0 and not stop_comma and t.line != start_line:
                    pv = self.toks[self.i - 1]
                    if pv.t in ('id', 'num', 'str') or (pv.t == 'op' and pv.v in (')', ']', '}')):
                        if t.v in ('var', 'let', 'const', 'function', 'class', 'if', 'for', 'while', 'return', 'export', 'import', 'switch', 'try', 'throw', 'do'):
                            return
                        if self.isop(self.peek(1), '=') or (self.isop(self.peek(1), '.') ):
                            return
            self.next()

class Holder:
    """Scope holder for object literal members whose owner tag is created later or is explicit."""
    def __init__(self, vt, explicit=None):
        self.vt = vt
        self.members = []
        self.explicit = explicit
    def make(self, p, name, kind, line, **kw):
        idx = p.make(name, kind, line, 0, **kw)
        t = p.ctx.cork[idx]
        if self.explicit is not None:
            t.scope_kind = p.L.kind(self.explicit[0])
            t.scope_name = self.explicit[1]
        else:
            self.members.append(idx)
        return idx
    def fix(self, idx):
        for m in self.members:
            t = self.vt.ctx.cork[m]
            if not t.scope:
                t.scope = idx
    def scope_name(self, p):
        if self.explicit is not None:
            return self.explicit
        return ('v', None)

class SubHolder:
    def __init__(self, parent, name, line, p):
        self.parent = parent
        self.name = name
        self.line = line
        self.p = p
        self.members = []
    def make(self, p, name, kind, line, **kw):
        idx = p.make(name, kind, line, 0, **kw)
        self.members.append(idx)
        return idx
    def finish(self):
        p = self.p
        idx = self.parent.make(p, self.name, 'p', self.line)
        for m in self.members:
            t = p.ctx.cork[m]
            if not t.scope and t.scope_name is None:
                t.scope = idx

def parse(ctx):
    L = ctx.lang
    L.qualified = True
    p = Parser(ctx)
    try:
        p.parse()
    except RecursionError:
        pass
