PUNCT3 = ('===', '!==', '**=', '...', '<<=', '>>=', '>>>', '&&=', '||=', '??=')
PUNCT2 = ('=>', '==', '!=', '<=', '>=', '&&', '||', '??', '?.', '++', '--', '+=', '-=', '*=', '/=', '%=', '&=',
          '|=', '^=', '**', '<<', '>>')

class Tok:
    __slots__ = ('t', 'v', 'line', 'pos', 'end')
    def __init__(self, t, v, line, pos, end):
        self.t = t; self.v = v; self.line = line; self.pos = pos; self.end = end
    def __repr__(self):
        return '%s:%s' % (self.t, self.v)

REGEX_PREV_OPS = set('( , = : [ ! & | ? { } ; + - * % < > ~ ^ => == != === !== <= >= && || ?? += -= *= /= %= &= |= ^= return typeof case do else in of new delete void throw yield await'.split())

def tokenize(text):
    toks = []
    i = 0
    n = len(text)
    line = 1
    def prev_allows_regex():
        if not toks:
            return True
        p = toks[-1]
        if p.t == 'op':
            return p.v in REGEX_PREV_OPS
        if p.t == 'id' and p.v in ('return', 'typeof', 'case', 'do', 'else', 'in', 'of', 'new', 'delete', 'void', 'throw', 'yield', 'await'):
            return True
        return False
    while i < n:
        c = text[i]
        if c == '\n':
            line += 1; i += 1; continue
        if c in ' \t\r\f\v':
            i += 1; continue
        if c == '/' and i + 1 < n and text[i + 1] == '/':
            j = text.find('\n', i)
            i = n if j < 0 else j
            continue
        if c == '/' and i + 1 < n and text[i + 1] == '*':
            j = text.find('*/', i + 2)
            j = n if j < 0 else j + 2
            line += text.count('\n', i, j)
            i = j
            continue
        if c == '#' and i == 0 and text.startswith('#!'):
            j = text.find('\n')
            i = n if j < 0 else j
            continue
        start = i
        sline = line
        if c in '"\'':
            j = i + 1
            while j < n and text[j] != c:
                if text[j] == '\\':
                    if j + 1 < n and text[j + 1] == '\n':
                        line += 1
                    j += 1
                elif text[j] == '\n':
                    break
                j += 1
            j = min(j + 1, n)
            toks.append(Tok('str', text[i:j], sline, i, j))
            i = j
            continue
        if c == '`':
            j = i + 1
            depth = 0
            while j < n:
                d = text[j]
                if d == '\\':
                    j += 2
                    continue
                if d == '\n':
                    line += 1
                if depth == 0 and d == '`':
                    break
                if d == '$' and j + 1 < n and text[j + 1] == '{':
                    depth += 1
                    j += 2
                    continue
                if d == '}' and depth > 0:
                    depth -= 1
                j += 1
            j = min(j + 1, n)
            toks.append(Tok('str', text[i:j], sline, i, j))
            i = j
            continue
        if c == '/' and prev_allows_regex():
            j = i + 1
            incls = False
            while j < n:
                d = text[j]
                if d == '\\':
                    j += 2
                    continue
                if d == '\n':
                    break
                if d == '[':
                    incls = True
                elif d == ']':
                    incls = False
                elif d == '/' and not incls:
                    break
                j += 1
            j += 1
            while j < n and (isalnum(text[j])):
                j += 1
            toks.append(Tok('re', text[i:j], sline, i, j))
            i = j
            continue
        if c == '_' or c == '$' or isalpha(c) or ord(c) >= 0x80 or (c == '#' and i + 1 < n and (isalpha(text[i + 1]) or text[i + 1] in '_$')):
            j = i + 1
            while j < n and (text[j] == '_' or text[j] == '$' or isalnum(text[j]) or ord(text[j]) >= 0x80):
                j += 1
            toks.append(Tok('id', text[i:j], sline, i, j))
            i = j
            continue
        if isdigit(c) or (c == '.' and i + 1 < n and isdigit(text[i + 1])):
            j = i + 1
            while j < n and (isalnum(text[j]) or text[j] in '._'):
                j += 1
            toks.append(Tok('num', text[i:j], sline, i, j))
            i = j
            continue
        op = None
        for o in PUNCT3:
            if text.startswith(o, i):
                op = o; break
        if op is None:
            for o in PUNCT2:
                if text.startswith(o, i):
                    op = o; break
        if op is None:
            op = c
        toks.append(Tok('op', op, sline, i, i + len(op)))
        i += len(op)
    toks.append(Tok('eof', '', line, n, n))
    return toks

def collapse(s):
    out = []
    sp = False
    for c in s:
        if c in ' \t\r\n':
            sp = True
            continue
        if sp and out:
            out.append(' ')
        sp = False
        out.append(c)
    return ''.join(out)

class Parser:
    def __init__(self, ctx):
        self.ctx = ctx
        self.L = ctx.lang
        self.toks = tokenize(ctx.text)
        self.i = 0
        self.anon_hash = None
        self.anon_count = 0
        import parsers.cxx as cx
        self.anon_hash = '%08x' % cx.djb2(OPT.anonhash if OPT.anonhash else ctx.path)

    def anon(self, prefix, kletter):
        self.anon_count += 1
        k = self.L.kind(kletter)
        return '%s%s%02x%02x' % (prefix, self.anon_hash, self.anon_count, k.index)

    def peek(self, k=0):
        j = self.i + k
        return self.toks[j] if j < len(self.toks) else self.toks[-1]

    def next(self):
        t = self.toks[self.i]
        if self.i < len(self.toks) - 1:
            self.i += 1
        return t

    def isop(self, t, v):
        return t.t == 'op' and t.v == v

    def make(self, name, kind, line, scope=0, **kw):
        idx = self.ctx.make_tag(name, kind, line=line, scope=scope)
        t = self.ctx.cork[idx]
        for k, v in kw.items():
            setattr(t, k, v)
        return idx

    def skip_group(self, o, c):
        depth = 0
        while True:
            t = self.next()
            if t.t == 'eof':
                return t
            if self.isop(t, o):
                depth += 1
            elif self.isop(t, c):
                depth -= 1
                if depth == 0:
                    return t

    def params_sig(self):
        """Current token '('; skip params and return collapsed signature text."""
        a = self.peek()
        b = self.skip_group('(', ')')
        return collapse(self.ctx.text[a.pos:b.end])

    # ------------------------------------------------------------------
    def parse(self):
        self.statements(0, False, None)

    def statements(self, scope, in_func, end_op):
        while True:
            t = self.peek()
            if t.t == 'eof':
                return
            if end_op and self.isop(t, end_op):
                self.next()
                return
            self.statement(scope, in_func)

    def statement(self, scope, in_func):
        t = self.peek()
        if t.t == 'op':
            if t.v == ';':
                self.next(); return
            if t.v == '{':
                self.next()
                self.statements(scope, in_func, '}')
                return
            self.expression(scope, in_func)
            return
        if t.t == 'id':
            v = t.v
            if v == 'export':
                self.next()
                if self.peek().t == 'id' and self.peek().v == 'default':
                    self.next()
                if self.isop(self.peek(), '{') or self.isop(self.peek(), '*'):
                    self.expression(scope, in_func)
                return
            if v == 'import' and not self.isop(self.peek(1), '('):
                self.skip_to_semicolon()
                return
            if v == 'async' and self.peek(1).t == 'id' and self.peek(1).v == 'function':
                self.next()
                self.function_decl(scope, in_func)
                return
            if v == 'function':
                self.function_decl(scope, in_func)
                return
            if v == 'class':
                self.class_decl(scope, in_func, None)
                return
            if v in ('var', 'let', 'const'):
                self.next()
                self.var_decl(v, scope, in_func)
                return
            if v in ('if', 'while', 'for', 'switch', 'with', 'catch'):
                self.next()
                if self.isop(self.peek(), '('):
                    self.expression_group(scope, in_func)
                self.statement(scope, in_func) if not self.isop(self.peek(), ';') else self.next()
                return
            if v in ('else', 'do', 'try', 'finally'):
                self.next()
                return
            if v in ('return', 'throw', 'case', 'yield', 'await', 'new', 'typeof', 'delete', 'void'):
                self.next()
                self.expression(scope, in_func)
                return
            if v in ('break', 'continue', 'debugger'):
                self.next()
                return
            if v == 'default' and self.isop(self.peek(1), ':'):
                self.next(); self.next(); return
            # assignment statements: a.b.c = ...
            if self.try_assignment(scope, in_func):
                return
        self.expression(scope, in_func)

    def skip_to_semicolon(self):
        while True:
            t = self.peek()
            if t.t == 'eof':
                return
            if self.isop(t, ';'):
                self.next()
                return
            if self.isop(t, '{'):
                self.skip_group('{', '}')
                continue
            if t.line != self.toks[self.i - 1].line and self.i > 0 and not self.isop(self.toks[self.i - 1], ','):
                # ASI
                pv = self.toks[self.i - 1]
                if pv.t in ('str', 'id', 'num') or self.isop(pv, '}') or self.isop(pv, ')'):
                    return
            self.next()

    def function_decl(self, scope, in_func, name_override=None):
        ft = self.next()  # 'function'
        gen = False
        if self.isop(self.peek(), '*'):
            self.next()
            gen = True
        name = None
        if self.peek().t == 'id' and not self.isop(self.peek(), '('):
            name = self.next()
        sig = '()'
        if self.isop(self.peek(), '('):
            sig = self.params_sig()
        kind = 'g' if gen else 'f'
        if name is None:
            nm = self.anon('anonymousFunction', 'f')
            line = ft.line
        else:
            nm = name.v
            line = name.line
        idx = self.make(nm, kind, line, scope, signature=sig)
        if self.isop(self.peek(), '{'):
            self.function_body(idx)
        return idx

    def function_body(self, idx):
        self.next()  # {
        start_cork = len(self.ctx.cork)
        self.statements(idx, True, '}')
        # constructor detection: this.x = function
        t = self.ctx.cork[idx]
        if getattr(t, 'extra_data', None) == 'ctor' and t.kind.letter == 'f':
            t.kind = self.L.kind('c')

    def class_decl(self, scope, in_func, name_override):
        ct = self.next()  # class
        name = None
        if self.peek().t == 'id' and self.peek().v != 'extends':
            name = self.next()
        if self.peek().t == 'id' and self.peek().v == 'extends':
            self.next()
            self.skip_expression_until_brace()
        idx = None
        if name is not None:
            idx = self.make(name.v, 'c', name.line, scope)
        if name_override is not None:
            oidx = self.make(name_override[0], 'c', name_override[1], scope)
            if idx is None:
                idx = oidx
        if idx is None:
            idx = self.make(self.anon('AnonymousClass', 'c'), 'c', ct.line, scope)
        if self.isop(self.peek(), '{'):
            self.next()
            self.class_body(idx)
        return idx

    def skip_expression_until_brace(self):
        while True:
            t = self.peek()
            if t.t == 'eof' or self.isop(t, '{'):
                return
            if self.isop(t, '('):
                self.skip_group('(', ')')
                continue
            self.next()

    def class_body(self, cidx):
        while True:
            t = self.peek()
            if t.t == 'eof':
                return
            if self.isop(t, '}'):
                self.next()
                return
            if self.isop(t, ';'):
                self.next()
                continue
            mods = []
            while self.peek().t == 'id' and self.peek().v in ('static', 'async', 'get', 'set', 'accessor') and not (self.isop(self.peek(1), '(') or self.isop(self.peek(1), '=') or self.isop(self.peek(1), ';')):
                mods.append(self.next().v)
            gen = False
            if self.isop(self.peek(), '*'):
                self.next()
                gen = True
            nt = self.peek()
            if self.isop(nt, '{') and 'static' in mods:
                self.next()
                self.statements(cidx, True, '}')
                continue
            if nt.t == 'id' or nt.t == 'num':
                name = nt.v
                self.next()
            elif nt.t == 'str':
                name = nt.v[1:-1]
                self.next()
            elif self.isop(nt, '['):
                a = nt
                b = self.skip_group('[', ']')
                name = self.ctx.text[a.pos:b.end]
            else:
                self.next()
                continue
            acc = 'private' if name.startswith('#') else None
            if self.isop(self.peek(), '('):
                sig = self.params_sig()
                kind = 'm'
                if 'get' in mods:
                    kind = 'G'
                elif 'set' in mods:
                    kind = 'S'
                elif gen:
                    kind = 'g'
                idx = self.make(name, kind, nt.line, cidx, signature=sig)
                if acc:
                    self.ctx.cork[idx].access = acc
                if self.isop(self.peek(), '{'):
                    self.function_body(idx)
                continue
            # field
            idx = self.make(name, 'M', nt.line, cidx)
            if acc:
                self.ctx.cork[idx].access = acc
            if self.isop(self.peek(), '='):
                self.next()
                self.expression(cidx, True, stop_semicolon=True)
            if self.isop(self.peek(), ';'):
                self.next()

    def var_decl(self, kw, scope, in_func):
        while True:
            t = self.peek()
            if t.t == 'id':
                name = self.next()
                if self.isop(self.peek(), '='):
                    self.next()
                    self.assigned_value(name.v, name.line, kw, scope, in_func)
                else:
                    if not in_func:
                        self.make(name.v, 'C' if kw == 'const' else 'v', name.line, scope)
            elif self.isop(t, '{') or self.isop(t, '['):
                close = '}' if t.v == '{' else ']'
                self.next()
                depth = 1
                while True:
                    x = self.next()
                    if x.t == 'eof':
                        break
                    if x.t == 'op' and x.v in ('{', '['):
                        depth += 1
                    elif x.t == 'op' and x.v in ('}', ']'):
                        depth -= 1
                        if depth == 0:
                            break
                    elif x.t == 'id' and depth == 1 and not in_func:
                        nx = self.peek()
                        if not (self.isop(nx, ':')):
                            self.make(x.v, 'C' if kw == 'const' else 'v', x.line, scope)
                if self.isop(self.peek(), '='):
                    self.next()
                    self.expression(scope, in_func, stop_comma=True)
            else:
                break
            if self.isop(self.peek(), ','):
                self.next()
                continue
            break
        if self.isop(self.peek(), ';'):
            self.next()

    def is_function_value(self):
        """Check if the tokens at current position start a function expression or arrow."""
        t = self.peek()
        k = 0
        if t.t == 'id' and t.v == 'async':
            k = 1
        t = self.peek(k)
        if t.t == 'id' and t.v == 'function':
            return 'function'
        if t.t == 'id' and self.isop(self.peek(k + 1), '=>'):
            return 'arrow1'
        if self.isop(t, '('):
            # find matching ) and check =>
            depth = 0
            j = self.i + k
            while j < len(self.toks):
                x = self.toks[j]
                if self.isop(x, '('):
                    depth += 1
                elif self.isop(x, ')'):
                    depth -= 1
                    if depth == 0:
                        break
                elif x.t == 'eof':
                    return None
                j += 1
            if j + 1 < len(self.toks) and self.isop(self.toks[j + 1], '=>'):
                return 'arrow'
        return None

    def assigned_value(self, name, line, kw, scope, in_func, member_kind=None, prop=False):
        fv = self.is_function_value()
        if fv:
            if self.peek().t == 'id' and self.peek().v == 'async':
                self.next()
            if fv == 'function':
                ft = self.next()
                gen = False
                if self.isop(self.peek(), '*'):
                    self.next(); gen = True
                if self.peek().t == 'id':
                    self.next()
                self.anon_count += 1
                sig = self.params_sig() if self.isop(self.peek(), '(') else '()'
                kind = member_kind or ('g' if gen else 'f')
                idx = self.make(name, kind, line, scope, signature=sig)
                if self.isop(self.peek(), '{'):
                    self.function_body(idx)
                return idx
            if fv == 'arrow1':
                p = self.next()
                sig = '(' + p.v + ')'
            else:
                sig = self.params_sig()
            self.next()  # =>
            kind = member_kind or 'f'
            idx = self.make(name, kind, line, scope, signature=sig)
            if self.isop(self.peek(), '{'):
                self.function_body(idx)
            else:
                self.expression(idx, True, stop_comma=True)
            return idx
        t = self.peek()
        if t.t == 'id' and t.v == 'class':
            return self.class_decl(scope, in_func, (name, line))
        if self.isop(t, '{') and not in_func:
            # object literal: properties first, then the variable
            self.next()
            tmp = self.ctx.make_tag(name, 'v', line=line, scope=scope)
            vt = self.ctx.cork[tmp]
            # temporarily remove to keep order: we re-append after properties
            self.ctx.cork.pop()
            holder = Holder(vt)
            self.object_literal(holder, 'variable')
            vt.index = len(self.ctx.cork)
            self.ctx.cork.append(vt)
            holder.fix(vt.index)
            self.expression(scope, in_func, stop_comma=True)
            return vt.index
        if not in_func:
            k = 'C' if kw == 'const' else 'v'
            idx = self.make(name, k, line, scope)
            self.expression(scope, in_func, stop_comma=True)
            return idx
        self.expression(scope, in_func, stop_comma=True)
        return None

    def object_literal(self, holder, scope_kind_name):
        """After '{'. Parses properties with scope = holder (index fixed later)."""
        while True:
            t = self.peek()
            if t.t == 'eof':
                return
            if self.isop(t, '}'):
                self.next()
                return
            if self.isop(t, ','):
                self.next()
                continue
            if self.isop(t, '...'):
                self.next()
                self.expression(0, True, stop_comma=True)
                continue
            mods = []
            while self.peek().t == 'id' and self.peek().v in ('get', 'set', 'async') and (self.peek(1).t in ('id', 'str', 'num') or self.isop(self.peek(1), '[')):
                mods.append(self.next().v)
            gen = False
            if self.isop(self.peek(), '*'):
                self.next(); gen = True
            nt = self.peek()
            if nt.t in ('id', 'num'):
                name = nt.v
                self.next()
            elif nt.t == 'str':
                name = nt.v[1:-1]
                self.next()
            elif self.isop(nt, '['):
                a = nt
                b = self.skip_group('[', ']')
                name = self.ctx.text[a.pos:b.end]
            else:
                self.expression(0, True, stop_comma=True)
                continue
            if self.isop(self.peek(), '('):
                sig = self.params_sig()
                kind = 'G' if 'get' in mods else ('S' if 'set' in mods else ('g' if gen else 'm'))
                idx = holder.make(self, name, kind, nt.line, signature=sig)
                if self.isop(self.peek(), '{'):
                    self.function_body(idx)
                continue
            if self.isop(self.peek(), ':'):
                self.next()
                fv = self.is_function_value()
                if fv:
                    if self.peek().t == 'id' and self.peek().v == 'async':
                        self.next()
                    if fv == 'function':
                        self.next()
                        gk = False
                        if self.isop(self.peek(), '*'):
                            self.next(); gk = True
                        if self.peek().t == 'id':
                            self.next()
                        self.anon_count += 1
                        sig = self.params_sig() if self.isop(self.peek(), '(') else '()'
                        idx = holder.make(self, name, 'g' if gk else 'm', nt.line, signature=sig)
                        if self.isop(self.peek(), '{'):
                            self.function_body(idx)
                    else:
                        if fv == 'arrow1':
                            p = self.next()
                            sig = '(' + p.v + ')'
                        else:
                            sig = self.params_sig()
                        self.next()
                        idx = holder.make(self, name, 'm', nt.line, signature=sig)
                        if self.isop(self.peek(), '{'):
                            self.function_body(idx)
                        else:
                            self.expression(idx, True, stop_comma=True)
                    continue
                if self.isop(self.peek(), '{'):
                    self.next()
                    sub = SubHolder(holder, name, nt.line, self)
                    self.object_literal(sub, 'property')
                    sub.finish()
                    continue
                holder.make(self, name, 'p', nt.line)
                self.expression(0, True, stop_comma=True)
                continue
            # shorthand
            holder.make(self, name, 'p', nt.line)

    def try_assignment(self, scope, in_func):
        # dotted name followed by '='
        j = self.i
        parts = []
        toks = self.toks
        if toks[j].t != 'id':
            return False
        parts.append(toks[j])
        j += 1
        while j + 1 < len(toks) and self.isop(toks[j], '.') and toks[j + 1].t == 'id':
            parts.append(toks[j + 1])
            j += 2
        if not (j < len(toks) and self.isop(toks[j], '=')):
            return False
        names = [p.v for p in parts]
        self.i = j + 1
        last = parts[-1]
        if names[0] == 'this' and len(names) == 2:
            if scope and self.is_function_value():
                owner = self.ctx.cork[scope]
                owner.extra_data = 'ctor'
                self.assigned_value_scoped(names[1], last.line, scope, 'c', 'm', in_func)
                return True
            self.expression(scope, in_func)
            return True
        if len(names) >= 3 and names[-2] == 'prototype':
            cls = '.'.join(names[:-2])
            self.assigned_value_scoped(names[-1], last.line, None, ('c', cls), 'm', in_func)
            return True
        if len(names) == 2 and names[1] == 'prototype':
            if self.isop(self.peek(), '{'):
                self.next()
                h = Holder(None, ('c', names[0]))
                self.object_literal(h, 'class')
                return True
            self.expression(scope, in_func)
            return True
        if len(names) >= 2:
            if names == ['module', 'exports'] and self.isop(self.peek(), '{'):
                self.next()
                idx = self.make('module.exports', 'p', parts[0].line, scope)
                h = Holder(None, ('p', 'module.exports'))
                self.object_literal(h, 'property')
                return True
            obj = '.'.join(names[:-1])
            fv = self.is_function_value()
            if fv:
                self.assigned_value_scoped(names[-1], last.line, None, ('v', obj), 'f', in_func)
                return True
            self.expression(scope, in_func)
            return True
        # simple assignment NAME = ...
        fv = self.is_function_value()
        if fv and not in_func:
            self.assigned_value(names[0], parts[0].line, 'var', scope, in_func)
            return True
        self.expression(scope, in_func)
        return True

    def assigned_value_scoped(self, name, line, scope, explicit, kind, in_func):
        idx = self.assigned_value(name, line, 'var', scope or 0, True, member_kind=kind)
        if idx is not None and explicit is not None and not isinstance(explicit, str):
            t = self.ctx.cork[idx]
            t.scope = 0
            k = self.L.kind({'c': 'c', 'v': 'v', 'p': 'p'}[explicit[0]])
            t.scope_kind = k
            t.scope_name = explicit[1]
        elif idx is not None and explicit == 'c':
            pass
        return idx

    def expression_group(self, scope, in_func):
        # current '('
        self.next()
        depth = 1
        while True:
            t = self.peek()
            if t.t == 'eof':
                return
            if self.isop(t, '('):
                depth += 1
            elif self.isop(t, ')'):
                depth -= 1
                if depth == 0:
                    self.next()
                    return
            if t.t == 'id' and t.v == 'function':
                self.function_decl(scope, in_func)
                continue
            if self.isop(t, '{'):
                self.next()
                self.statements(scope, in_func, '}')
                continue
            self.next()

    def expression(self, scope, in_func, stop_comma=False, stop_semicolon=False):
        """Skip an expression, tagging nested function expressions."""
        depth = 0
        start_line = self.peek().line
        while True:
            t = self.peek()
            if t.t == 'eof':
                return
            if t.t == 'op':
                v = t.v
                if v in ('(', '['):
                    depth += 1
                    self.next()
                    continue
                if v in (')', ']'):
                    if depth == 0:
                        return
                    depth -= 1
                    self.next()
                    continue
                if v == '{':
                    self.next()
                    self.statements(scope, in_func, '}')
                    continue
                if v == '}':
                    return
                if v == ';' and depth == 0:
                    if not stop_comma and not stop_semicolon:
                        self.next()
                    return
                if v == ',' and depth == 0 and stop_comma:
                    return
                self.next()
                continue
            if t.t == 'id':
                if t.v == 'function':
                    self.function_decl(scope, in_func)
                    continue
                if t.v == 'class':
                    self.class_decl(scope, in_func, None)
                    continue
                if depth == 0 and not stop_comma and t.line != start_line:
                    pv = self.toks[self.i - 1]
                    if pv.t in ('id', 'num', 'str') or (pv.t == 'op' and pv.v in (')', ']', '}')):
                        if t.v in ('var', 'let', 'const', 'function', 'class', 'if', 'for', 'while', 'return', 'export', 'import', 'switch', 'try', 'throw', 'do'):
                            return
                        if self.isop(self.peek(1), '=') or (self.isop(self.peek(1), '.') ):
                            return
            self.next()

class Holder:
    """Scope holder for object literal members whose owner tag is created later or is explicit."""
    def __init__(self, vt, explicit=None):
        self.vt = vt
        self.members = []
        self.explicit = explicit
    def make(self, p, name, kind, line, **kw):
        idx = p.make(name, kind, line, 0, **kw)
        t = p.ctx.cork[idx]
        if self.explicit is not None:
            t.scope_kind = p.L.kind(self.explicit[0])
            t.scope_name = self.explicit[1]
        else:
            self.members.append(idx)
        return idx
    def fix(self, idx):
        for m in self.members:
            t = self.vt.ctx.cork[m]
            if not t.scope:
                t.scope = idx
    def scope_name(self, p):
        if self.explicit is not None:
            return self.explicit
        return ('v', None)

class SubHolder:
    def __init__(self, parent, name, line, p):
        self.parent = parent
        self.name = name
        self.line = line
        self.p = p
        self.members = []
    def make(self, p, name, kind, line, **kw):
        idx = p.make(name, kind, line, 0, **kw)
        self.members.append(idx)
        return idx
    def finish(self):
        p = self.p
        idx = self.parent.make(p, self.name, 'p', self.line)
        for m in self.members:
            t = p.ctx.cork[m]
            if not t.scope and t.scope_name is None:
                t.scope = idx

def parse(ctx):
    L = ctx.lang
    L.qualified = True
    p = Parser(ctx)
    try:
        p.parse()
    except RecursionError:
        pass
