'use strict';
const fs = require('fs');
const path = require('path');
const { promisify } = require('util');

const DEFAULTS = {
  verbose: false,
  depth: 3,
};

class Walker extends EventEmitter {
  constructor(root, opts = {}) {
    super();
    this.root = root;
    this.opts = Object.assign({}, DEFAULTS, opts);
  }

  async walk(dir = this.root, level = 0) {
    const entries = await promisify(fs.readdir)(dir);
    for (const e of entries) {
      const full = path.join(dir, e);
      if (level < this.opts.depth) {
        await this.walk(full, level + 1);
      }
      this.emit('file', full);
    }
  }

  static of(root) {
    return new Walker(root);
  }
}

function helper(a, b = 2, ...rest) {
  return [a, b, ...rest].map((x) => x * 2);
}

const utils = {
  sum(arr) { return arr.reduce((a, b) => a + b, 0); },
  avg: function (arr) { return this.sum(arr) / arr.length; },
};

module.exports = Walker;
module.exports.helper = helper;
exports.VERSION = '1.0.0';

$(document).ready(function () {
  $('#btn').on('click', function handler(e) {
    e.preventDefault();
  });
});
