"""Go parser."""
from core import *

KEYWORDS = set('break case chan const continue default defer else fallthrough for func go goto if import interface map package range return select struct switch type var'.split())

class Tok:
    __slots__ = ('t', 'v', 'line', 'pos', 'end', 'nl', 'tab')
    def __init__(self, t, v, line, pos, end, nl=False, tab=False):
        self.t = t; self.v = v; self.line = line; self.pos = pos; self.end = end; self.nl = nl; self.tab = tab
    def __repr__(self):
        return '%s:%s' % (self.t, self.v)

OPS = ['<<=', '>>=', '&^=', '...', '&&', '||', '<-', '++', '--', '==', '!=', '<=', '>=', ':=', '+=', '-=', '*=', '/=',
       '%=', '&=', '|=', '^=', '<<', '>>', '&^']

def tokenize(text):
    toks = []
    i = 0
    n = len(text)
    line = 1
    def need_semi():
        if not toks:
            return False
        p = toks[-1]
        if p.t in ('id', 'num', 'str'):
            return p.v not in KEYWORDS or p.v in ('break', 'continue', 'fallthrough', 'return')
        if p.t == 'op' and p.v in ('++', '--', ')', ']', '}'):
            return True
        return False
    sp = False
    while i < n:
        c = text[i]
        if c == '\n':
            if need_semi():
                toks.append(Tok('op', ';', line, i, i, nl=True))
            line += 1
            i += 1
            sp = False
            continue
        if c in ' \t\r':
            i += 1
            sp = True
            continue
        if c == '/' and i + 1 < n and text[i + 1] == '/':
            j = text.find('\n', i)
            i = n if j < 0 else j
            continue
        if c == '/' and i + 1 < n and text[i + 1] == '*':
            j = text.find('*/', i + 2)
            j = n if j < 0 else j + 2
            if '\n' in text[i:j] and need_semi():
                toks.append(Tok('op', ';', line, i, i, nl=True))
            line += text.count('\n', i, j)
            i = j
            continue
        start = i
        tab = sp
        sp = False
        if c == '"':
            j = i + 1
            while j < n and text[j] != '"' and text[j] != '\n':
                if text[j] == '\\':
                    j += 1
                j += 1
            toks.append(Tok('str', text[i:j + 1], line, i, j + 1, tab=tab))
            i = j + 1
            continue
        if c == '`':
            j = text.find('`', i + 1)
            j = n if j < 0 else j + 1
            toks.append(Tok('str', text[i:j], line, i, j, tab=tab))
            line += text.count('\n', i, j)
            i = j
            continue
        if c == "'":
            j = i + 1
            while j < n and text[j] != "'" and text[j] != '\n':
                if text[j] == '\\':
                    j += 1
                j += 1
            toks.append(Tok('str', text[i:j + 1], line, i, j + 1, tab=tab))
            i = j + 1
            continue
        if c == '_' or isalpha(c) or ord(c) >= 0x80:
            j = i + 1
            while j < n and (text[j] == '_' or isalnum(text[j]) or ord(text[j]) >= 0x80):
                j += 1
            toks.append(Tok('id', text[i:j], line, i, j, tab=tab))
            i = j
            continue
        if isdigit(c) or (c == '.' and i + 1 < n and isdigit(text[i + 1])):
            j = i + 1
            while j < n and (isalnum(text[j]) or text[j] in '._'):
                j += 1
            toks.append(Tok('num', text[i:j], line, i, j, tab=tab))
            i = j
            continue
        op = None
        for o in OPS:
            if text.startswith(o, i):
                op = o
                break
        if op is None:
            op = c
        toks.append(Tok('op', op, line, i, i + len(op), tab=tab))
        i += len(op)
    if need_semi():
        toks.append(Tok('op', ';', line, n, n, nl=True))
    toks.append(Tok('eof', '', line, n, n))
    return toks

def is_word(t):
    return t.t in ('id', 'num', 'str')

def join_type(toks):
    out = []
    prev = None
    for t in toks:
        if t.t == 'op' and t.v == ';' and t.nl:
            v = ';'
        else:
            v = t.v
        if prev is not None:
            sp = False
            if is_word(prev) and is_word(t):
                sp = True
            elif prev.t == 'op' and prev.v in (',', ';') and not (t.t == 'op' and t.v in (')', '}')):
                sp = True
            elif prev.t == 'op' and prev.v == ')' and is_word(t):
                sp = True
            elif prev.t == 'op' and prev.v == '<-' and is_word(t) and t.v != 'chan':
                sp = True
            elif prev.t == 'op' and prev.v == '{' and not (t.t == 'op' and t.v == '}'):
                sp = True
            elif t.t == 'op' and t.v == '}' and not (prev.t == 'op' and prev.v == '{') and t.tab:
                sp = True
            elif t.t == 'op' and t.v == '{' and is_word(prev) and prev.v == 'struct':
                sp = True
            elif prev.t == 'op' and prev.v == '}' and is_word(t):
                sp = True
            elif prev.t == 'op' and prev.v == ']' and False:
                sp = True
            if sp:
                out.append(' ')
        out.append(v)
        prev = t
    return ''.join(out)

class Parser:
    def __init__(self, ctx):
        self.ctx = ctx
        self.L = ctx.lang
        self.toks = tokenize(ctx.text)
        self.i = 0
        self.pkg = 0
        self.pkgname = None
        self.types = {}

    def peek(self, k=0):
        j = self.i + k
        return self.toks[j] if j < len(self.toks) else self.toks[-1]

    def next(self):
        t = self.toks[self.i]
        if self.i < len(self.toks) - 1:
            self.i += 1
        return t

    def isop(self, t, v):
        return t.t == 'op' and t.v == v

    def skip_group(self, o, c):
        depth = 0
        toks = []
        while True:
            t = self.next()
            toks.append(t)
            if t.t == 'eof':
                return toks
            if self.isop(t, o):
                depth += 1
            elif self.isop(t, c):
                depth -= 1
                if depth == 0:
                    return toks

    def make(self, name, kind, line, scope=None, **kw):
        idx = self.ctx.make_tag(name, kind, line=line, scope=self.pkg if scope is None else scope)
        t = self.ctx.cork[idx]
        for k, v in kw.items():
            setattr(t, k, v)
        return idx

    def skip_semis(self):
        while self.isop(self.peek(), ';'):
            self.next()

    def parse(self):
        while True:
            self.skip_semis()
            t = self.peek()
            if t.t == 'eof':
                return
            if t.t == 'id':
                if t.v == 'package':
                    self.next()
                    nt = self.next()
                    self.pkg = self.make(nt.v, 'p', nt.line, scope=0)
                    self.pkgname = nt.v
                    continue
                if t.v == 'import':
                    self.next()
                    self.imports()
                    continue
                if t.v in ('const', 'var'):
                    self.next()
                    self.group(self.var_spec, 'c' if t.v == 'const' else 'v')
                    continue
                if t.v == 'type':
                    self.next()
                    self.group(self.type_spec, None)
                    continue
                if t.v == 'func':
                    self.next()
                    self.func_decl()
                    continue
            self.skip_statement()

    def skip_statement(self):
        while True:
            t = self.peek()
            if t.t == 'eof':
                return
            if self.isop(t, ';'):
                self.next()
                return
            if self.isop(t, '{'):
                self.skip_group('{', '}')
                continue
            if self.isop(t, '('):
                self.skip_group('(', ')')
                continue
            self.next()

    def group(self, fn, arg):
        if self.isop(self.peek(), '('):
            self.next()
            while True:
                self.skip_semis()
                t = self.peek()
                if t.t == 'eof':
                    return
                if self.isop(t, ')'):
                    self.next()
                    return
                fn(arg)
        else:
            fn(arg)

    def imports(self):
        def spec(_):
            t = self.peek()
            alias = None
            if t.t == 'id' or self.isop(t, '.') or (t.t == 'id' and t.v == '_'):
                alias = self.next()
            pt = self.peek()
            if pt.t != 'str':
                self.skip_statement()
                return
            self.next()
            path = pt.v[1:-1]
            pk = self.L.kind('p')
            if alias is not None and alias.v not in ('_', '.'):
                aidx = self.make(alias.v, 'P', alias.line, scope=0)
                self.ctx.cork[aidx].set_field('package', path)
                ridx = self.make(path, pk, pt.line, scope=0)
                self.ctx.cork[ridx].add_role('imported')
                self.ctx.cork[ridx].set_field('packageName', alias.v)
            else:
                ridx = self.make(path, pk, pt.line, scope=0)
                self.ctx.cork[ridx].add_role('imported')
                if alias is not None:
                    self.ctx.cork[ridx].set_field('howImported', 'init' if alias.v == '_' else 'inline')
            if self.isop(self.peek(), ';'):
                self.next()
        self.group(spec, None)

    def collect_type(self, stops=(';', '=', ')', ',', '{')):
        """Collect type tokens until a stop token at depth 0."""
        toks = []
        depth = 0
        while True:
            t = self.peek()
            if t.t == 'eof':
                break
            if t.t == 'op':
                if depth == 0 and t.v in stops:
                    # struct/interface braces are part of type
                    if t.v == '{' and toks and toks[-1].t == 'id' and toks[-1].v in ('struct', 'interface'):
                        pass
                    else:
                        break
                if t.v in ('(', '[', '{'):
                    depth += 1
                elif t.v in (')', ']', '}'):
                    if depth == 0:
                        break
                    depth -= 1
            toks.append(self.next())
        return toks

    def var_spec(self, kind):
        names = []
        while True:
            t = self.peek()
            if t.t == 'id':
                names.append(self.next())
                if self.isop(self.peek(), ','):
                    self.next()
                    continue
            break
        typ = []
        if not self.isop(self.peek(), '=') and not self.isop(self.peek(), ';') and not self.isop(self.peek(), ')'):
            typ = self.collect_type(stops=(';', '=', ')'))
        tr = ('typename', join_type(typ)) if typ else None
        for nt in names:
            if nt.v == '_':
                continue
            self.make(nt.v, kind, nt.line, typeref=tr)
        if self.isop(self.peek(), '='):
            self.next()
            self.skip_expr()
        if self.isop(self.peek(), ';'):
            self.next()

    def skip_expr(self):
        depth = 0
        while True:
            t = self.peek()
            if t.t == 'eof':
                return
            if t.t == 'op':
                if t.v in ('(', '[', '{'):
                    depth += 1
                elif t.v in (')', ']', '}'):
                    if depth == 0:
                        return
                    depth -= 1
                elif t.v == ';' and depth == 0:
                    return
            self.next()

    def type_spec(self, _):
        nt = self.peek()
        if nt.t != 'id':
            self.skip_statement()
            return
        self.next()
        tparams = False
        if self.isop(self.peek(), '[') and not self.isop(self.peek(1), ']'):
            # generic type params
            tparams = True
        if self.isop(self.peek(), '='):
            self.next()
            typ = self.collect_type(stops=(';', ')'))
            idx = self.make(nt.v, 'a', nt.line, typeref=('typename', join_type(typ)))
            self.ctx.cork[idx].end = typ[-1].line if typ else nt.line
            self.types[nt.v] = idx
            return
        t = self.peek()
        if t.t == 'id' and t.v == 'struct' and not tparams:
            self.next()
            idx = self.make(nt.v, 's', nt.line)
            self.types[nt.v] = idx
            if self.isop(self.peek(), '{'):
                end = self.struct_body(idx)
                self.ctx.cork[idx].end = end.line
            return
        if t.t == 'id' and t.v == 'interface' and not tparams:
            self.next()
            idx = self.make(nt.v, 'i', nt.line)
            self.types[nt.v] = idx
            if self.isop(self.peek(), '{'):
                end = self.interface_body(idx)
                self.ctx.cork[idx].end = end.line
            return
        typ = self.collect_type(stops=(';', ')'))
        idx = self.make(nt.v, 't', nt.line, typeref=('typename', join_type(typ)))
        self.ctx.cork[idx].end = typ[-1].line if typ else nt.line
        self.types[nt.v] = idx

    def struct_body(self, sidx):
        self.next()  # {
        while True:
            self.skip_semis()
            t = self.peek()
            if t.t == 'eof':
                return t
            if self.isop(t, '}'):
                self.next()
                return t
            # embedded: [*]Type or pkg.Type
            line_toks = []
            if self.isop(t, '*') or (t.t == 'id' and (self.isop(self.peek(1), ';') or self.isop(self.peek(1), '.') or self.peek(1).t == 'str' or self.isop(self.peek(1), '}'))):
                typ = self.collect_type(stops=(';', '}'))
                typ2 = [x for x in typ if x.t != 'str']
                names = [x for x in typ2 if x.t == 'id']
                if names:
                    nm = names[-1]
                    self.make(nm.v, 'M', nm.line, scope=sidx, typeref=('typename', join_type(typ2)))
                if self.isop(self.peek(), ';'):
                    self.next()
                continue
            names = []
            while self.peek().t == 'id':
                names.append(self.next())
                if self.isop(self.peek(), ','):
                    self.next()
                    continue
                break
            typ = self.collect_type(stops=(';', '}'))
            typ = [x for x in typ if x.t != 'str']
            tr = ('typename', join_type(typ)) if typ else None
            for nm in names:
                self.make(nm.v, 'm', nm.line, scope=sidx, typeref=tr)
            if self.isop(self.peek(), ';'):
                self.next()

    def interface_body(self, iidx):
        self.next()  # {
        while True:
            self.skip_semis()
            t = self.peek()
            if t.t == 'eof':
                return t
            if self.isop(t, '}'):
                self.next()
                return t
            if t.t == 'id' and self.isop(self.peek(1), '('):
                nm = self.next()
                ptoks = self.skip_group('(', ')')
                sig = join_type(ptoks)
                rt = self.collect_type(stops=(';', '}'))
                tr = ('typename', join_type(rt)) if rt else None
                self.make(nm.v, 'n', nm.line, scope=iidx, typeref=tr, signature=sig)
                if self.isop(self.peek(), ';'):
                    self.next()
                continue
            self.collect_type(stops=(';', '}'))
            if self.isop(self.peek(), ';'):
                self.next()

    def func_decl(self):
        recv = None
        rname = None
        if self.isop(self.peek(), '('):
            rtoks = self.skip_group('(', ')')
            inner = rtoks[1:-1]
            ids = [x for x in inner if x.t == 'id']
            if ids:
                tname = ids[-1]
