                        rname = None
                recv = tname
        nt = self.peek()
        if nt.t != 'id':
            self.skip_statement()
            return
        self.next()
        tparams = None
        if self.isop(self.peek(), '['):
            tparams = self.skip_group('[', ']')
        sig = None
        if self.isop(self.peek(), '('):
            ptoks = self.skip_group('(', ')')
            sig = join_type(ptoks)
        rt = self.collect_type(stops=(';', '{'))
        if tparams is not None:
            tr = ('typename', join_type(([] if sig is None else []) + rt))
            tr = ('typename', sig + (' ' + join_type(rt) if rt else '')) if sig else None
            sig = join_type(tparams)
        else:
            tr = ('typename', join_type(rt)) if rt else None
        scope = None
        if recv is not None:
            tidx = self.types.get(recv.v)
            if tidx is None:
                uidx = self.make(recv.v, 'Y', recv.line)
                self.ctx.cork[uidx].add_role('receiverType')
                self.types[recv.v] = uidx
                tidx = uidx
            scope = tidx
            if rname is not None:
                ridx = self.ctx.make_tag(rname.v, 'R', line=rname.line, scope=0)
                self.pending_recv = ridx
        else:
            rname = None
        idx = self.make(nt.v, 'f', nt.line, scope=scope, signature=sig, typeref=tr)
        if recv is not None and rname is not None:
            rt_ = self.ctx.cork[self.pending_recv]
            rt_.scope = idx
            rt_.typeref = ('typename', recv.v)
            self.ctx.cork[idx].set_field('receiver', rname.v)
        if self.isop(self.peek(), '{'):
            body = self.skip_group('{', '}')
            self.ctx.cork[idx].end = body[-1].line
        elif self.isop(self.peek(), ';'):
            self.next()

def parse(ctx):
    L = ctx.lang
    L.qualified = True
    p = Parser(ctx)
    p.parse()
