"""Rust parser."""
from core import *

class Tok:
    __slots__ = ('t', 'v', 'line', 'pos', 'end')
    def __init__(self, t, v, line, pos, end):
        self.t = t; self.v = v; self.line = line; self.pos = pos; self.end = end
    def __repr__(self):
        return '%s:%s' % (self.t, self.v)

def tokenize(text):
    toks = []
    i = 0
    n = len(text)
    line = 1
    while i < n:
        c = text[i]
        if c == '\n':
            line += 1; i += 1; continue
        if c in ' \t\r\f':
            i += 1; continue
        if c == '/' and i + 1 < n and text[i + 1] == '/':
            j = text.find('\n', i)
            i = n if j < 0 else j
            continue
        if c == '/' and i + 1 < n and text[i + 1] == '*':
            depth = 0
            j = i
            while j < n:
                if text.startswith('/*', j):
                    depth += 1; j += 2; continue
                if text.startswith('*/', j):
                    depth -= 1; j += 2
                    if depth == 0:
                        break
                    continue
                j += 1
            line += text.count('\n', i, j)
            i = j
            continue
        start = i
        if c == 'r' and i + 1 < n and (text[i + 1] == '"' or (text[i + 1] == '#' and i + 2 < n and text[i + 2] in '#"')):
            j = i + 1
            h = 0
            while j < n and text[j] == '#':
                h += 1; j += 1
            if j < n and text[j] == '"':
                endm = '"' + '#' * h
                e = text.find(endm, j + 1)
                e = n if e < 0 else e + len(endm)
                line2 = line + text.count('\n', i, e)
                toks.append(Tok('str', text[i:e], line, i, e))
                line = line2
                i = e
                continue
        if c == 'b' and i + 1 < n and text[i + 1] in '"\'':
            i += 1
            c = text[i]
        if c == '"':
            j = i + 1
            while j < n and text[j] != '"':
                if text[j] == '\\':
                    j += 1
                j += 1
            j = min(j + 1, n)
            toks.append(Tok('str', text[start:j], line, start, j))
            line += text.count('\n', start, j)
            i = j
            continue
        if c == "'":
            # char literal or lifetime
            if i + 2 < n and text[i + 1] == '\\':
                j = text.find("'", i + 2)
                j = n if j < 0 else j + 1
                toks.append(Tok('chr', text[i:j], line, i, j))
                i = j
                continue
            if i + 2 < n and text[i + 2] == "'":
                toks.append(Tok('chr', text[i:i + 3], line, i, i + 3))
                i += 3
                continue
            j = i + 1
            while j < n and (isalnum(text[j]) or text[j] == '_'):
                j += 1
            toks.append(Tok('life', text[i:j], line, i, j))
            i = j
            continue
        if c == '_' or isalpha(c) or ord(c) >= 0x80:
            j = i + 1
            while j < n and (text[j] == '_' or isalnum(text[j]) or ord(text[j]) >= 0x80):
                j += 1
            toks.append(Tok('id', text[i:j], line, i, j))
            i = j
            continue
        if isdigit(c):
            j = i + 1
            while j < n and (isalnum(text[j]) or text[j] in '_.'):
                if text[j] == '.' and j + 1 < n and text[j + 1] == '.':
                    break
                j += 1
            toks.append(Tok('num', text[i:j], line, i, j))
            i = j
            continue
        if text.startswith('::', i) or text.startswith('->', i) or text.startswith('=>', i):
            toks.append(Tok('op', text[i:i + 2], line, i, i + 2)); i += 2; continue
        toks.append(Tok('op', c, line, i, i + 1))
        i += 1
    toks.append(Tok('eof', '', line, n, n))
    return toks

def sig_text(s):
    out = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c in ' \t\r\n':
            j = i
            nl = False
            while j < n and s[j] in ' \t\r\n':
                if s[j] == '\n':
                    nl = True
                j += 1
            if nl:
                out.append(' ')
            else:
                out.append(s[i:j])
            i = j
            continue
        out.append(c)
        i += 1
    return ''.join(out).strip()

class Parser:
    def __init__(self, ctx):
        self.ctx = ctx
        self.toks = tokenize(ctx.text)
        self.i = 0

    def peek(self, k=0):
        j = self.i + k
        return self.toks[j] if j < len(self.toks) else self.toks[-1]

    def next(self):
        t = self.toks[self.i]
        if self.i < len(self.toks) - 1:
            self.i += 1
        return t

    def isop(self, t, v):
        return t.t == 'op' and t.v == v

    def isid(self, t, v):
        return t.t == 'id' and t.v == v

    def skip_group(self, o, c):
        depth = 0
        last = None
        while True:
            t = self.next()
            if t.t == 'eof':
                return t
            if self.isop(t, o):
                depth += 1
            elif self.isop(t, c):
                depth -= 1
                if depth == 0:
                    return t

    def skip_generics(self):
        # current '<'
        depth = 0
        while True:
            t = self.next()
            if t.t == 'eof':
                return t
            if self.isop(t, '<'):
                depth += 1
            elif self.isop(t, '>'):
                depth -= 1
                if depth == 0:
                    return t
            elif self.isop(t, '(') :
                self.i -= 1
                self.skip_group('(', ')')
            elif t.t == 'op' and t.v in ('{', ';'):
                self.i -= 1
                return t

    def make(self, name, kind, line, scope, **kw):
        idx = self.ctx.make_tag(name, kind, line=line, scope=scope)
        t = self.ctx.cork[idx]
        for k, v in kw.items():
            setattr(t, k, v)
        return idx

    def skip_attr(self):
        # current '#'
        self.next()
        if self.isop(self.peek(), '!'):
            self.next()
        if self.isop(self.peek(), '['):
            self.skip_group('[', ']')

    def items(self, scope, ctx_kind, end_brace):
        while True:
            t = self.peek()
            if t.t == 'eof':
                return t
            if end_brace and self.isop(t, '}'):
                self.next()
                return t
            if self.isop(t, '#'):
                self.skip_attr()
                continue
            if self.isop(t, ';'):
                self.next()
                continue
            self.item(scope, ctx_kind)

    def skip_visibility(self):
        if self.isid(self.peek(), 'pub'):
            self.next()
            if self.isop(self.peek(), '('):
                self.skip_group('(', ')')

    def skip_to_semi_or_block(self):
        depth = 0
        while True:
            t = self.peek()
            if t.t == 'eof':
                return t
            if self.isop(t, ';'):
                self.next()
                return t
            if self.isop(t, '{'):
                return self.skip_group('{', '}')
            if self.isop(t, '('):
                self.skip_group('(', ')')
                continue
            if self.isop(t, '['):
                self.skip_group('[', ']')
                continue
            if self.isop(t, '}'):
                return t
            self.next()

    def item(self, scope, ctx_kind):
        self.skip_visibility()
        t = self.peek()
        if t.t != 'id':
            if self.isop(t, '{'):
                self.next()
                self.body(scope)
                return
            self.next()
            return
        v = t.v
        if v in ('async', 'const', 'unsafe', 'default') and (self.isid(self.peek(1), 'fn') or self.isid(self.peek(1), 'unsafe') or self.isid(self.peek(1), 'extern') or self.isid(self.peek(1), 'async')):
            self.next()
            self.item(scope, ctx_kind)
            return
        if v == 'extern':
            self.next()
            if self.peek().t == 'str':
                self.next()
            if self.isop(self.peek(), '{'):
                self.next()
                self.items(scope, ctx_kind, True)
                return
            if self.isid(self.peek(), 'crate'):
                self.skip_to_semi_or_block()
                return
            self.item(scope, ctx_kind)
            return
        if v == 'fn':
            self.next()
            nt = self.next()
            if nt.t != 'id':
                return
            start = self.peek()
