            depth = 0
            while True:
                x = self.peek()
                if x.t == 'eof':
                    break
                if x.t == 'op':
                    if x.v in ('(', '['):
                        depth += 1
                    elif x.v in (')', ']'):
                        depth -= 1
                    elif x.v in ('{', ';') and depth <= 0:
                        break
                    elif x.v == '<':
                        pass
                self.next()
            endtok = self.toks[self.i - 1]
            sig = sig_text(self.ctx.text[start.pos:endtok.end]) if endtok is not start or True else ''
            if self.i > 0 and self.toks[self.i - 1] is not nt:
                sig = sig_text(self.ctx.text[start.pos:self.toks[self.i - 1].end])
            else:
