from core import *

def is_ident_char(c):
    return isalnum(c) or c == '_' or ord(c) >= 0x80

class Nest:
    __slots__ = ('name', 'idx', 'kind')
    def __init__(self, name, idx, kind):
        self.name = name; self.idx = idx; self.kind = kind

OPERATORS = ['[]=', '[]', '**', '!~', '!=', '!', '~', '+@', '-@', '+', '-', '*', '/', '%', '<=>', '<<', '>>', '<=',
             '>=', '<', '>', '===', '==', '=~', '&', '^', '|', '`']

class Parser:
    def __init__(self, ctx):
        self.ctx = ctx
        self.L = ctx.lang
        self.nest = []
        self.line = 0

    def can_match(self, s, cp, word, assign=False):
        n = len(word)
        if not s.startswith(word, cp):
            return None
        e = cp + n
        if e < len(s):
            c = s[e]
            if is_ident_char(c) or c in '?!:':
                return None
            if not (c in ' \t\r\n' or c in '(;' or c == '#'):
                if c in '.' or c == '=':
                    return None
        return e

    def can_match_kw_assign(self, s, cp, word):
        e = self.can_match(s, cp, word)
        if e is not None:
            return e
        # x = if ...
        j = cp
        while j < len(s) and (is_ident_char(s[j]) or s[j] in '@$'):
            j += 1
        if j == cp:
            return None
        k = j
        while k < len(s) and s[k] in ' \t':
            k += 1
        if k < len(s) and s[k] == '=' and not (k + 1 < len(s) and s[k + 1] in '=~>'):
            k += 1
            while k < len(s) and s[k] in ' \t':
                k += 1
            return self.can_match(s, k, word)
        return None

    def scope_parent(self):
        for n in reversed(self.nest):
            if n.idx is not None:
                return n
        return None

    def enter_unnamed(self):
        self.nest.append(Nest(None, None, None))

    def emit(self, name, kind, push=True, line=None):
        line = line or self.line
        parent_idx = 0
        parent = None
        for n in reversed(self.nest):
            if n.name is not None:
                parent = n
                break
        parts = name.split('.') if kind not in ('f', 'S') else [name]
        if kind in ('c', 'm') and '.' in name:
            parts = name.split('.')
        tagname = parts[-1]
        idx = self.ctx.make_tag(tagname, kind, line=line)
        t = self.ctx.cork[idx]
        scope_names = [n.name for n in self.nest if n.name is not None]
        extra = parts[:-1]
        if scope_names or extra:
            full = scope_names + extra
            if extra:
                sk = self.L.kind('m')
            else:
                sk = parent.kind
            t.scope_kind = sk
            t.scope_name = '.'.join(full)
        if push:
            self.nest.append(Nest(tagname, idx, t.kind))
        return idx

    def parse_operator(self, s, cp):
        for op in OPERATORS:
            if s.startswith(op, cp):
                return op, cp + len(op)
        return None, cp

    def parse_identifier(self, s, cp, kind):
        """Returns (kind, name, newcp)."""
        n = len(s)
        while cp < n and s[cp] in ' \t':
            cp += 1
        if kind == 'c' and s.startswith('<<', cp):
            return None, '', cp
        if kind in ('f', 'S'):
            op, e = self.parse_operator(s, cp)
            if op is not None:
                return kind, op, e
        also = '.?!=' if kind == 'f' else ('?!=' if kind == 'S' else '')
        name = []
        had_sep = False
        while cp < n and (s[cp] == ':' or is_ident_char(s[cp]) or s[cp] in also):
            c = s[cp]
            if c == ':':
                had_sep = True
            else:
                if had_sep:
                    name.append('.')
                    had_sep = False
                name.append(c)
            cp += 1
            if kind == 'f' and c == '.':
                recv = ''.join(name[:-1])
                k2, nm2, cp2 = self.parse_identifier(s, cp, 'S')
                return 'S', (recv, nm2), cp2
            if kind in ('f', 'S') and c in '?!=':
                break
        return kind, ''.join(name), cp

    def read_and_emit(self, s, cp, kind):
        if cp < len(s) and s[cp] not in ' \t':
            return cp
        k, name, cp = self.parse_identifier(s, cp, kind)
        if k is None or name == '' or name == ('', ''):
            self.enter_unnamed()
            return cp
        if k == 'S':
            recv, nm = name if isinstance(name, tuple) else ('self', name)
            if recv == 'self' or (self.nest and self.nest[-1].name == recv) or recv == '':
                idx = self.emit(nm, 'S')
            else:
                # explicit receiver
                idx = self.ctx.make_tag(nm, 'S', line=self.line)
                t = self.ctx.cork[idx]
                scope_names = [n.name for n in self.nest if n.name is not None] + [recv]
                t.scope_kind = self.L.kind('m')
                t.scope_name = '.'.join(scope_names)
                self.nest.append(Nest(nm, idx, t.kind))
            sig = self.signature(s, cp)
            self.ctx.cork[idx].signature = sig
            return cp
        idx = self.emit(name, k)
        if k == 'f':
            if self.in_singleton():
                self.ctx.cork[idx].kind = self.L.kind('S')
            self.ctx.cork[idx].signature = self.signature(s, cp)
        return cp

    def in_singleton(self):
        for n in reversed(self.nest):
            if n.name is None and n.kind == 'singleton':
                return True
            if n.name is not None:
                return False
        return False

    def signature(self, s, cp):
        n = len(s)
        j = cp
        while j < n and s[j] in ' \t':
            j += 1
        if j < n and s[j] == '(':
            # collect possibly multi-line
            depth = 0
            out = []
            text = s
            k = j
            li = self.cur_line_index
            while True:
                while k < len(text):
                    c = text[k]
                    out.append(c)
                    if c == '(':
                        depth += 1
                    elif c == ')':
                        depth -= 1
                        if depth == 0:
                            return collapse(''.join(out))
                    k += 1
                li += 1
                if li >= len(self.lines):
                    return collapse(''.join(out))
                text = self.lines[li]
                out.append(' ')
                k = 0
        return '()'

    def parse(self):
        lines = [l for _, l in self.ctx.lines()]
        self.lines = lines
        in_comment = False
        for li, s in enumerate(lines):
            self.line = li + 1
            self.cur_line_index = li
            if s.startswith('=begin') and (len(s) == 6 or s[6] in ' \t\r'):
                in_comment = True
                continue
            if s.startswith('=end') and (len(s) == 4 or s[4] in ' \t\r'):
                in_comment = False
                continue
            if in_comment:
                continue
            cp = 0
            n = len(s)
            while cp < n and s[cp] in ' \t\r':
                cp += 1
            expect_sep = False
            e = None
            for kw in ('for', 'until', 'while'):
                e = self.can_match_kw_assign(s, cp, kw)
                if e is not None:
                    expect_sep = True
                    self.enter_unnamed()
                    cp = e
                    break
            if e is None:
                for kw in ('case', 'if', 'unless'):
                    e = self.can_match_kw_assign(s, cp, kw)
                    if e is not None:
                        self.enter_unnamed()
                        cp = e
                        break
            # access modifiers before def
            for kw in ('private', 'protected', 'public', 'module_function'):
                e2 = self.can_match(s, cp, kw)
                if e2 is not None:
                    k2 = e2
                    while k2 < n and s[k2] in ' \t':
                        k2 += 1
                    if self.can_match(s, k2, 'def') is not None:
                        cp = k2
                    break
            e = self.can_match_kw_assign(s, cp, 'module')
            handled = False
            if e is not None:
                cp = self.read_and_emit(s, e, 'm')
                handled = True
            if not handled:
                e = self.can_match_kw_assign(s, cp, 'class')
                if e is not None:
                    j = e
                    while j < n and s[j] in ' \t':
                        j += 1
                    if s.startswith('<<', j):
                        nest = Nest(None, None, 'singleton')
                        self.nest.append(nest)
                        cp = n
                    else:
                        cp = self.read_and_emit(s, e, 'c')
                    handled = True
            if not handled:
                e = self.can_match(s, cp, 'def')
                if e is not None:
                    cp = self.read_and_emit(s, e, 'f')
                    handled = True
            if not handled:
                handled, cp = self.misc(s, cp)
            while cp < n:
                c = s[cp]
                if c in ' \t\r':
                    cp += 1
                    continue
                if c == '#':
                    break
                e = self.can_match(s, cp, 'begin')
                if e is not None:
                    self.enter_unnamed()
                    cp = e
                    continue
                e = self.can_match(s, cp, 'do')
                if e is not None:
                    if not expect_sep:
                        self.enter_unnamed()
                    else:
                        expect_sep = False
                    cp = e
                    continue
                e = self.can_match(s, cp, 'end')
                if e is not None and self.nest:
                    nn = self.nest.pop()
                    if nn.idx is not None:
                        self.ctx.cork[nn.idx].end = self.line
                    cp = e
                    continue
                if c == '"':
                    j = cp + 1
                    while j < n and s[j] != '"':
                        j += 1
                    cp = j + 1
                    continue
                if c == ';':
                    cp += 1
                    expect_sep = False
                    continue
                cp += 1
                while cp < n and is_ident_char(s[cp]):
                    cp += 1

    def current_class_tag(self):
        for n in reversed(self.nest):
            if n.idx is not None:
                t = self.ctx.cork[n.idx]
                if t.kind.letter in ('c', 'm'):
                    return t
                return None
        return None

    def misc(self, s, cp):
        n = len(s)
        # x = Class.new do
        j = cp
        while j < n and is_ident_char(s[j]):
            j += 1
        word = s[cp:j]
        if word in ('attr_reader', 'attr_writer', 'attr_accessor', 'attr'):
            names = self.symbols(s, j)
            for nm in names:
                if word in ('attr_reader', 'attr_accessor', 'attr'):
                    self.emit(nm, 'A', push=False)
                if word in ('attr_writer', 'attr_accessor'):
                    self.emit(nm + '=', 'A', push=False)
            return True, n
        if word == 'alias_method':
            names = self.symbols(s, j)
            if names:
                self.emit(names[0], 'a', push=False)
            return True, n
        if word == 'alias' and j < n and s[j] in ' \t':
            k = j
            while k < n and s[k] in ' \t':
                k += 1
            m = k
            if m < n and s[m] == ':':
                m += 1
                k += 1
            while m < n and (is_ident_char(s[m]) or s[m] in '?!='):
                m += 1
            if m > k:
                self.emit(s[k:m], 'a', push=False)
            return True, n
        if word in ('include', 'extend', 'prepend') and j < n and s[j] in ' \t(':
            k = j
            while k < n and s[k] in ' \t(':
                k += 1
            m = k
            while m < n and (is_ident_char(s[m]) or s[m] == ':'):
                m += 1
            mod = s[k:m]
            ct = self.current_class_tag()
            if mod and ct is not None:
                old = ct.get_field('mixin')
                val = '%s:%s' % (word, mod)
                if old:
                    for i, (f, v) in enumerate(ct.pfields):
                        if f.name == 'mixin':
                            ct.pfields[i] = (f, v + ',' + val)
                else:
                    ct.set_field('mixin', val)
            return True, m
        if word in ('require', 'require_relative', 'load'):
            k = j
            while k < n and s[k] in ' \t(':
                k += 1
            if k < n and s[k] in '"\'':
                q = s[k]
                e = s.find(q, k + 1)
                if e > k:
                    nm = s[k + 1:e]
                    idx = self.ctx.make_tag(nm, 'L', line=self.line)
                    self.ctx.cork[idx].add_role({'require': 'required', 'require_relative': 'requiredRel', 'load': 'loaded'}[word])
            return True, n
        if word and (word[0].isupper()) and all(is_ident_char(c) for c in word):
            k = j
            while k < n and s[k] in ' \t':
                k += 1
            if k < n and s[k] == '=' and not s.startswith('=>', k) and not s.startswith('=~', k):
                self.emit(word, 'C', push=False)
                return True, k + 1
        if word and j < n:
            k = j
            while k < n and s[k] in ' \t':
                k += 1
            if k < n and s[k] == '=' and not s.startswith('==', k):
                k += 1
                while k < n and s[k] in ' \t':
                    k += 1
                for cls, kind in (('Class.new', 'c'), ('Module.new', 'm'), ('Struct.new', 'c')):
                    if s.startswith(cls, k):
                        rest = s[k + len(cls):]
                        if ' do' in rest or '{' in rest or rest.strip().startswith('do'):
                            self.emit(word, kind)
                            e = s.find(' do', k)
                            if e >= 0:
                                return True, e + 3
                            return True, n
        return False, cp

    def symbols(self, s, cp):
        out = []
        n = len(s)
        i = cp
        while i < n:
            c = s[i]
            if c == ':':
                j = i + 1
                while j < n and (is_ident_char(s[j]) or s[j] in '?!='):
                    j += 1
                if j > i + 1:
                    out.append(s[i + 1:j])
                i = j
                continue
            if c in '"\'':
                e = s.find(c, i + 1)
                if e < 0:
                    break
                out.append(s[i + 1:e])
                i = e + 1
                continue
            if c == '#':
                break
            i += 1
        return out

def collapse(s):
    out = []
    sp = False
    for c in s:
        if c in ' \t\r\n':
            sp = True
            continue
        if sp and out:
            out.append(' ')
        sp = False
        out.append(c)
    return ''.join(out)

def parse(ctx):
    Parser(ctx).parse()
