            names = self.symbols(s, j)
            for nm in names:
                if word in ('attr_reader', 'attr_accessor', 'attr'):
                    self.emit(nm, 'A', push=False)
                if word in ('attr_writer', 'attr_accessor'):
                    self.emit(nm + '=', 'A', push=False)
            return True, n
        if word == 'alias_method':
            names = self.symbols(s, j)
            if names:
                self.emit(names[0], 'a', push=False)
            return True, n
        if word == 'alias' and j < n and s[j] in ' \t':
            k = j
            while k < n and s[k] in ' \t':
                k += 1
            m = k
            if m < n and s[m] == ':':
                m += 1
                k += 1
            while m < n and (is_ident_char(s[m]) or s[m] in '?!='):
                m += 1
            if m > k:
                self.emit(s[k:m], 'a', push=False)
            return True, n
        if word in ('include', 'extend', 'prepend') and j < n and s[j] in ' \t(':
            k = j
            while k < n and s[k] in ' \t(':
                k += 1
            m = k
            while m < n and (is_ident_char(s[m]) or s[m] == ':'):
                m += 1
            mod = s[k:m]
            ct = self.current_class_tag()
            if mod and ct is not None:
                old = ct.get_field('mixin')
                val = '%s:%s' % (word, mod)
                if old:
                    for i, (f, v) in enumerate(ct.pfields):
                        if f.name == 'mixin':
                            ct.pfields[i] = (f, v + ',' + val)
                else:
                    ct.set_field('mixin', val)
            return True, m
        if word in ('require', 'require_relative', 'load'):
            k = j
            while k < n and s[k] in ' \t(':
                k += 1
            if k < n and s[k] in '"\'':
                q = s[k]
                e = s.find(q, k + 1)
                if e > k:
                    nm = s[k + 1:e]
                    idx = self.ctx.make_tag(nm, 'L', line=self.line)
                    self.ctx.cork[idx].add_role({'require': 'required', 'require_relative': 'requiredRel', 'load': 'loaded'}[word])
            return True, n
        if word and (word[0].isupper()) and all(is_ident_char(c) for c in word):
            k = j
            while k < n and s[k] in ' \t':
                k += 1
            if k < n and s[k] == '=' and not s.startswith('=>', k) and not s.startswith('=~', k):
                self.emit(word, 'C', push=False)
                return True, k + 1
        if word and j < n:
            k = j
            while k < n and s[k] in ' \t':
                k += 1
            if k < n and s[k] == '=' and not s.startswith('==', k):
                k += 1
                while k < n and s[k] in ' \t':
                    k += 1
                for cls, kind in (('Class.new', 'c'), ('Module.new', 'm'), ('Struct.new', 'c')):
                    if s.startswith(cls, k):
                        rest = s[k + len(cls):]
                        if ' do' in rest or '{' in rest or rest.strip().startswith('do'):
                            self.emit(word, kind)
                            e = s.find(' do', k)
                            if e >= 0:
                                return True, e + 3
                            return True, n
        return False, cp

    def symbols(self, s, cp):
        out = []
        n = len(s)
        i = cp
        while i < n:
            c = s[i]
            if c == ':':
                j = i + 1
                while j < n and (is_ident_char(s[j]) or s[j] in '?!='):
                    j += 1
                if j > i + 1:
                    out.append(s[i + 1:j])
                i = j
                continue
            if c in '"\'':
                e = s.find(c, i + 1)
                if e < 0:
                    break
                out.append(s[i + 1:e])
                i = e + 1
                continue
            if c == '#':
                break
            i += 1
        return out

def collapse(s):
    out = []
    sp = False
    for c in s:
        if c in ' \t\r\n':
            sp = True
            continue
        if sp and out:
            out.append(' ')
        sp = False
        out.append(c)
    return ''.join(out)

def parse(ctx):
    Parser(ctx).parse()
