"""PHP parser."""
from core import *

class Tok:
    __slots__ = ('t', 'v', 'line', 'pos', 'end')
    def __init__(self, t, v, line, pos, end):
        self.t = t; self.v = v; self.line = line; self.pos = pos; self.end = end
    def __repr__(self):
        return '%s:%s' % (self.t, self.v)

def tokenize(text):
    toks = []
    i = 0
    n = len(text)
    line = 1
    in_php = False
    while i < n:
        if not in_php:
            j = text.find('<?', i)
            if j < 0:
                break
            line += text.count('\n', i, j)
            if text.startswith('<?php', j):
                i = j + 5
            elif text.startswith('<?=', j):
                i = j + 3
            else:
                i = j + 2
            in_php = True
            continue
        c = text[i]
        if c == '\n':
            line += 1; i += 1; continue
        if c in ' \t\r\f':
            i += 1; continue
        if c == '?' and text.startswith('?>', i):
            in_php = False
            toks.append(Tok('op', ';', line, i, i))
            i += 2
            continue
        if c == '#' or (c == '/' and text.startswith('//', i)):
            if c == '#' and text.startswith('#[', i):
                # attribute
                depth = 0
                j = i + 1
                while j < n:
                    if text[j] == '[':
                        depth += 1
                    elif text[j] == ']':
                        depth -= 1
                        if depth == 0:
                            break
                    elif text[j] == '\n':
                        line += 1
                    j += 1
                i = j + 1
                continue
            j = i
            while j < n and text[j] != '\n':
                if text.startswith('?>', j):
                    break
                j += 1
            i = j
            continue
        if c == '/' and text.startswith('/*', i):
            j = text.find('*/', i + 2)
            j = n if j < 0 else j + 2
            line += text.count('\n', i, j)
            i = j
            continue
        start = i
        if c in '"\'`':
            j = i + 1
            while j < n and text[j] != c:
                if text[j] == '\\':
                    j += 1
                j += 1
            j = min(j + 1, n)
            sline = line
            line += text.count('\n', i, j)
            toks.append(Tok('str', text[i:j], sline, i, j))
            i = j
            continue
        if text.startswith('<<<', i):
            j = i + 3
            while j < n and text[j] in ' \t':
                j += 1
            q = None
            if j < n and text[j] in '"\'':
                q = text[j]
                j += 1
            k = j
            while k < n and (isalnum(text[k]) or text[k] == '_'):
                k += 1
            label = text[j:k]
            if label:
                e = k
                # find terminator line
                pos = text.find('\n', e)
                sline = line
                while pos >= 0:
                    ls = pos + 1
                    m = ls
                    while m < n and text[m] in ' \t':
                        m += 1
                    if text.startswith(label, m) and not (m + len(label) < n and (isalnum(text[m + len(label)]) or text[m + len(label)] == '_')):
                        endp = m + len(label)
                        line += text.count('\n', i, endp)
                        toks.append(Tok('str', text[i:endp], sline, i, endp))
                        i = endp
                        break
                    pos = text.find('\n', ls)
                else:
                    i = n
                continue
        if c == '$' and i + 1 < n and (text[i + 1] == '_' or isalpha(text[i + 1]) or ord(text[i + 1]) >= 0x80):
            j = i + 1
            while j < n and (text[j] == '_' or isalnum(text[j]) or ord(text[j]) >= 0x80):
                j += 1
            toks.append(Tok('var', text[i + 1:j], line, i, j))
            i = j
            continue
        if c == '_' or c == '\\' or isalpha(c) or ord(c) >= 0x80:
            j = i + 1
            while j < n and (text[j] == '_' or text[j] == '\\' or isalnum(text[j]) or ord(text[j]) >= 0x80):
                j += 1
            toks.append(Tok('id', text[i:j], line, i, j))
            i = j
            continue
