    return toks

def join_sig(toks):
    out = []
    prev = None
    for t in toks:
        if prev is not None:
            sp = False
            pw = prev.t in ('id', 'var', 'num', 'str')
            cw = t.t in ('id', 'var', 'num', 'str')
            if pw and cw:
                sp = True
            elif prev.t == 'op' and prev.v == ',':
                sp = True
            elif prev.t == 'op' and prev.v in ('=', '&', '=>', '|') or (t.t == 'op' and t.v in ('=', '=>', '|')):
                sp = True
            elif prev.t == 'op' and prev.v == ':' :
                sp = True
            elif prev.t == 'op' and prev.v in ('?',) and False:
                sp = True
            if sp:
                out.append(' ')
        out.append(t.v if t.t != 'var' else '$' + t.v)
        prev = t
    return ''.join(out)

