    def __init__(self, ctx):
        self.ctx = ctx
        self.L = ctx.lang
        self.toks = tokenize(ctx.text)
        self.i = 0
        self.ns = 0

    def peek(self, k=0):
        j = self.i + k
        return self.toks[j] if j < len(self.toks) else self.toks[-1]

    def next(self):
        t = self.toks[self.i]
        if self.i < len(self.toks) - 1:
            self.i += 1
        return t

    def isop(self, t, v):
        return t.t == 'op' and t.v == v

    def isid(self, t, v):
        return t.t == 'id' and t.v.lower() == v

    def skip_group(self, o, c):
        depth = 0
        res = []
        while True:
            t = self.next()
            res.append(t)
            if t.t == 'eof':
                return res
            if self.isop(t, o):
                depth += 1
            elif self.isop(t, c):
                depth -= 1
                if depth == 0:
                    return res

    def make(self, name, kind, line, scope, **kw):
        idx = self.ctx.make_tag(name, kind, line=line, scope=scope)
        t = self.ctx.cork[idx]
        for k, v in kw.items():
            setattr(t, k, v)
        return idx

    def parse(self):
        self.block(0, 'top', False)

    def block(self, scope, ctype, braced, cls_name=None):
        while True:
            t = self.peek()
            if t.t == 'eof':
                return t
            if braced and self.isop(t, '}'):
                self.next()
                return t
            self.statement(scope, ctype, cls_name)

    def skip_statement(self):
        depth = 0
        while True:
            t = self.peek()
            if t.t == 'eof':
                return
            if t.t == 'op':
                if t.v in ('(', '['):
                    depth += 1
                elif t.v in (')', ']'):
                    depth -= 1
                elif t.v == '{':
                    self.skip_group('{', '}')
                    if depth <= 0:
                        return
                    continue
                elif t.v == '}':
                    return
                elif t.v == ';' and depth <= 0:
                    self.next()
                    return
            self.next()

    def statement(self, scope, ctype, cls_name):
        t = self.peek()
        if self.isop(t, ';'):
            self.next()
            return
        if self.isop(t, '{'):
            self.next()
            self.block(scope, ctype, True, cls_name)
            return
