                    self.ns = self.make(nt.v, 'n', nt.line, 0)
                if self.isop(self.peek(), '{'):
                    self.next()
                    self.block(self.ns, 'top', True)
                    self.ns = 0
                elif self.isop(self.peek(), ';'):
                    self.next()
                return
