            v = t.v.lower()
            if v == 'namespace' and ctype == 'top':
                self.next()
                nt = self.peek()
                if nt.t == 'id':
                    self.next()
                    self.ns = self.make(nt.v, 'n', nt.line, 0)
                if self.isop(self.peek(), '{'):
                    self.next()
                    self.block(self.ns, 'top', True)
                    self.ns = 0
                elif self.isop(self.peek(), ';'):
                    self.next()
                return
            if v == 'use' and ctype in ('top',):
                self.next()
                self.use_stmt(scope)
                return
            if v == 'use' and ctype == 'class':
                self.skip_statement()
                return
            mods = []
            k = 0
            while True:
                x = self.peek(k)
                if x.t == 'id' and x.v.lower() in ('abstract', 'final', 'public', 'protected', 'private', 'static', 'readonly', 'var'):
                    mods.append(x.v.lower())
                    k += 1
                    continue
                break
            x = self.peek(k)
            if x.t == 'id' and x.v.lower() in ('class', 'interface', 'trait', 'enum') and self.peek(k + 1).t == 'id' and not self.isop(self.peek(k - 1) if k else self.peek(-1), '::'):
                for _ in range(k + 1):
                    self.next()
                self.class_decl(x.v.lower(), scope, mods)
