        while True:
            t = self.peek()
            if t.t == 'eof':
                return
            if t.t == 'op':
                if t.v in ('(', '['):
                    depth += 1
                elif t.v in (')', ']'):
                    depth -= 1
                elif t.v == '{':
                    self.next()
                    self.block(scope, ctype, True, cls_name)
                    if depth <= 0:
                        return
                    continue
                elif t.v == '}':
                    return
                elif t.v == ';' and depth <= 0:
                    self.next()
                    return
