                    idx = self.make(x.v, 'v', x.line, scope)
                    if acc:
                        self.ctx.cork[idx].access = acc
                if self.isop(nx, '='):
                    self.next()
                    depth = 0
                    while True:
                        y = self.peek()
                        if y.t == 'eof':
                            return
                        if y.t == 'op':
                            if y.v in ('(', '['):
                                depth += 1
                            elif y.v in (')', ']'):
                                depth -= 1
                            elif y.v in (',', ';') and depth <= 0:
                                break
                        self.next()
                if self.isop(self.peek(), ','):
                    self.next()
                    continue
                if self.isop(self.peek(), ';'):
                    self.next()
                return
            if x.t == 'id' or self.isop(x, '?') or self.isop(x, '|'):
                self.next()
                continue
            self.skip_statement()
            return

    def params(self):
        toks = self.skip_group('(', ')')
        return join_sig(toks)

    def return_type(self, cls_name, idx):
        if self.isop(self.peek(), ':'):
            self.next()
            parts = []
            while self.peek().t == 'id' or self.isop(self.peek(), '?') or self.isop(self.peek(), '|'):
                parts.append(self.next())
            if parts:
                tn = ''.join(p.v for p in parts)
                t = self.ctx.cork[idx]
                if tn.lower() in ('self', 'static') and cls_name:
                    t.typeref = ('class', cls_name)
                else:
                    t.typeref = ('unknown', tn)

    def function_decl(self, scope, ctype, mods, cls_name):
        nt = self.next()
        sig = None
        if self.isop(self.peek(), '('):
            sig = self.params()
        idx = self.make(nt.v, 'f', nt.line, scope, signature=sig)
