            self.ctx.cork[idx].access = acc
        self.return_type(cls_name, idx)
        if self.isop(self.peek(), '{'):
            self.next()
            self.block(idx, 'function', True, cls_name)
        else:
            self.skip_statement()

    def class_decl(self, kw, scope, mods):
        nt = self.next()
        kind = {'class': 'c', 'interface': 'i', 'trait': 't', 'enum': None}[kw]
        inherits = []
        while True:
            x = self.peek()
            if x.t == 'id' and x.v.lower() in ('extends', 'implements'):
                self.next()
                while self.peek().t == 'id':
                    inherits.append(self.next().v)
                    if self.isop(self.peek(), ','):
                        self.next()
                        continue
                    break
                continue
            if self.isop(x, ':'):
                self.next()
                if self.peek().t == 'id':
                    self.next()
                continue
            break
        if kind is None:
            # enums not supported: parse body members without scope
            if self.isop(self.peek(), '{'):
                self.next()
                self.block(scope, 'class', True, None)
            return
        idx = self.make(nt.v, kind, nt.line, scope)
        if inherits:
            self.ctx.cork[idx].inherits = ','.join(inherits)
        if self.isop(self.peek(), '{'):
            self.next()
            self.block(idx, 'class', True, nt.v)

def parse(ctx):
    L = ctx.lang
    L.qualified = True
    L.scope_seps = {('n', '*'): '\\'}
    L.default_sep = '::'
    p = Parser(ctx)
    p.parse()
