"""TypeScript parser."""
from core import *
from parsers.javascript import tokenize

ACCESS = ('public', 'private', 'protected')
MODS = set(['public', 'private', 'protected', 'static', 'readonly', 'abstract', 'declare', 'async', 'override', 'export', 'default', 'accessor'])

class Parser:
    def __init__(self, ctx):
        self.ctx = ctx
        self.L = ctx.lang
        self.toks = tokenize(ctx.text)
        self.i = 0

    def peek(self, k=0):
        j = self.i + k
        return self.toks[j] if j < len(self.toks) else self.toks[-1]

    def next(self):
        t = self.toks[self.i]
        if self.i < len(self.toks) - 1:
            self.i += 1
        return t

    def isop(self, t, v):
        return t.t == 'op' and t.v == v

    def isid(self, t, v):
        return t.t == 'id' and t.v == v

    def make(self, name, kind, line, scope, **kw):
        idx = self.ctx.make_tag(name, kind, line=line, scope=scope)
        t = self.ctx.cork[idx]
        for k, v in kw.items():
            setattr(t, k, v)
        return idx

    def skip_group(self, o, c):
        depth = 0
        res = []
        while True:
            t = self.next()
            res.append(t)
            if t.t == 'eof':
                return res
            if self.isop(t, o):
                depth += 1
            elif self.isop(t, c):
                depth -= 1
                if depth == 0:
                    return res

    def skip_angle(self):
        depth = 0
        while True:
            t = self.next()
            if t.t == 'eof':
                return
            if self.isop(t, '<'):
                depth += 1
            elif self.isop(t, '>'):
                depth -= 1
                if depth <= 0:
                    return
            elif self.isop(t, '>>'):
                depth -= 2
                if depth <= 0:
                    return
            elif t.t == 'op' and t.v in ('{', ';'):
                return

    def parse(self):
        self.statements(0, 'top', None)

    def statements(self, scope, ctype, end):
        while True:
            t = self.peek()
            if t.t == 'eof':
                return
            if end and self.isop(t, end):
                self.next()
                return
            self.statement(scope, ctype)

    def skip_expr(self, scope, ctype, stop_comma=False):
        depth = 0
        while True:
            t = self.peek()
            if t.t == 'eof':
                return
            if t.t == 'op':
                if t.v in ('(', '['):
                    depth += 1
                elif t.v in (')', ']'):
                    if depth == 0:
                        return
                    depth -= 1
                elif t.v == '{':
                    self.skip_group('{', '}')
                    continue
                elif t.v == '}':
                    return
                elif t.v == ';' and depth == 0:
                    return
                elif t.v == ',' and depth == 0 and stop_comma:
                    return
            self.next()

    def statement(self, scope, ctype):
        t = self.peek()
        if self.isop(t, ';'):
            self.next()
            return
        if self.isop(t, '{'):
            self.next()
            self.statements(scope, ctype, '}')
            return
        if self.isop(t, '@'):
            self.next()
            self.next()
            if self.isop(self.peek(), '('):
                self.skip_group('(', ')')
            return
        if t.t == 'id':
            k = 0
            while self.peek(k).t == 'id' and self.peek(k).v in ('export', 'default', 'declare', 'abstract', 'async') and self.peek(k + 1).t == 'id':
                k += 1
            x = self.peek(k)
            v = x.v if x.t == 'id' else None
            if v == 'import':
                for _ in range(k):
                    self.next()
                self.skip_expr(scope, ctype)
                if self.isop(self.peek(), ';'):
                    self.next()
                return
            if v == 'function':
                for _ in range(k + 1):
                    self.next()
                gen = False
                if self.isop(self.peek(), '*'):
                    self.next()
                    gen = True
                nt = self.peek()
                if nt.t != 'id':
                    self.skip_function_rest(scope)
                    return
                self.next()
                idx = None
                if not gen:
                    idx = self.make(nt.v, 'f', nt.line, scope)
                self.function_rest(idx if idx is not None else scope, idx is not None)
                return
            if v == 'class' or (v == 'abstract' and self.isid(self.peek(k + 1), 'class')):
                for _ in range(k + 1):
                    self.next()
                if self.isid(self.peek(), 'class'):
                    self.next()
                self.class_decl(scope)
                return
            if v == 'interface' and self.peek(k + 1).t == 'id':
                for _ in range(k + 1):
                    self.next()
                self.interface_decl(scope)
                return
            if v == 'enum' or (v == 'const' and self.isid(self.peek(k + 1), 'enum')):
                for _ in range(k + 1):
                    self.next()
                if self.isid(self.peek(), 'enum'):
                    self.next()
                self.enum_decl(scope)
                return
            if v == 'type' and self.peek(k + 1).t == 'id':
                for _ in range(k + 1):
                    self.next()
                nt = self.next()
                self.make(nt.v, 'a', nt.line, scope)
                self.skip_expr(scope, ctype)
                if self.isop(self.peek(), ';'):
                    self.next()
                return
            if v in ('namespace', 'module') and self.peek(k + 1).t in ('id', 'str'):
                for _ in range(k + 1):
                    self.next()
                nt = self.next()
                if v == 'module':
                    if self.isop(self.peek(), '{'):
                        self.skip_group('{', '}')
                    return
                idx = self.make(nt.v, 'n', nt.line, scope)
                while self.isop(self.peek(), '.') and self.peek(1).t == 'id':
                    self.next()
                    nt = self.next()
                    idx = self.make(nt.v, 'n', nt.line, idx)
                if self.isop(self.peek(), '{'):
                    self.next()
                    self.statements(idx, 'ns', '}')
                return
            if v in ('const', 'let', 'var'):
                for _ in range(k + 1):
                    self.next()
                self.var_decl(v, scope, ctype)
                return
        self.skip_expr(scope, ctype)
        if self.isop(self.peek(), ';'):
            self.next()

    def var_decl(self, kw, scope, ctype):
        kind = 'C' if kw == 'const' else 'v'
        while True:
            nt = self.peek()
            if nt.t == 'id':
                self.next()
                self.make(nt.v, kind, nt.line, scope)
                if self.isop(self.peek(), ':'):
                    self.next()
                    self.skip_type()
                if self.isop(self.peek(), '='):
                    self.next()
                    self.skip_expr(scope, ctype, stop_comma=True)
            elif self.isop(nt, '{') or self.isop(nt, '['):
                self.skip_group(nt.v, '}' if nt.v == '{' else ']')
                if self.isop(self.peek(), '='):
                    self.next()
                    self.skip_expr(scope, ctype, stop_comma=True)
            else:
                break
            if self.isop(self.peek(), ','):
                self.next()
                continue
            break
        if self.isop(self.peek(), ';'):
            self.next()

    def skip_type(self):
        depth = 0
        while True:
            t = self.peek()
            if t.t == 'eof':
                return
            if t.t == 'op':
                if t.v in ('(', '[', '{', '<'):
                    depth += 1
                elif t.v in (')', ']', '}', '>'):
                    if depth == 0:
                        return
                    depth -= 1
                elif t.v == '>>':
                    depth -= 2
                    if depth < 0:
                        return
                elif t.v == '=>':
                    pass
                elif t.v in ('=', ',', ';') and depth == 0:
                    return
            self.next()

    def params(self, fidx, enabled=True, ctor_cls=None):
        """Current '('."""
        self.next()
        depth = 0
        expect = True
        while True:
            t = self.peek()
            if t.t == 'eof':
                return
            if self.isop(t, ')') and depth == 0:
                self.next()
                return
            if t.t == 'op' and t.v in ('(', '[', '{', '<'):
                depth += 1
                self.next()
                continue
            if t.t == 'op' and t.v in (')', ']', '}', '>'):
                depth -= 1
                self.next()
                continue
            if depth == 0 and self.isop(t, ','):
                expect = True
                self.next()
                continue
            if depth == 0 and expect:
                mods = []
                while self.peek().t == 'id' and self.peek().v in ('public', 'private', 'protected', 'readonly', 'override') and self.peek(1).t == 'id':
                    mods.append(self.next().v)
                if self.isop(self.peek(), '...'):
                    self.next()
                nt = self.peek()
                if nt.t == 'id':
                    self.next()
                    if mods and ctor_cls is not None:
                        acc = 'public'
                        for m in mods:
                            if m in ACCESS:
                                acc = m
                        self.make(nt.v, 'p', nt.line, ctor_cls, access=acc)
                    elif enabled and fidx is not None:
                        self.make(nt.v, 'z', nt.line, fidx)
                expect = False
                continue
            self.next()

    def function_rest(self, idx, enabled):
        if self.isop(self.peek(), '<'):
            self.skip_angle()
        if self.isop(self.peek(), '('):
            self.params(idx, enabled)
        if self.isop(self.peek(), ':'):
            self.next()
            self.skip_type_until_body()
        if self.isop(self.peek(), '{'):
            self.next()
            self.statements(idx, 'function', '}')
        elif self.isop(self.peek(), ';'):
            self.next()

    def skip_function_rest(self, scope):
        self.function_rest(None, False)

    def skip_type_until_body(self):
        depth = 0
        while True:
            t = self.peek()
            if t.t == 'eof':
                return
            if t.t == 'op':
                if t.v in ('(', '[', '<'):
                    depth += 1
                elif t.v in (')', ']', '>'):
                    depth -= 1
                elif t.v == '{':
                    if depth == 0:
                        # object type literal vs body: body follows ':' type... assume body
                        prev = self.toks[self.i - 1]
                        if prev.t == 'op' and prev.v == ':':
                            self.skip_group('{', '}')
                            continue
                        return
                elif t.v in (';', '}') and depth <= 0:
                    return
            self.next()

    def class_decl(self, scope):
        nt = self.peek()
        if nt.t != 'id' or nt.v in ('extends', 'implements'):
            name = None
        else:
            self.next()
            name = nt
        while not (self.isop(self.peek(), '{') or self.peek().t == 'eof'):
            if self.isop(self.peek(), '<'):
                self.skip_angle()
                continue
            self.next()
        if name is None:
            self.skip_group('{', '}')
            return
        idx = self.make(name.v, 'c', name.line, scope)
        self.next()
        self.class_body(idx)

    def class_body(self, cidx):
        while True:
            t = self.peek()
            if t.t == 'eof':
                return
            if self.isop(t, '}'):
                self.next()
                return
            if self.isop(t, ';') or self.isop(t, ','):
                self.next()
                continue
            if self.isop(t, '@'):
                self.next()
                self.next()
                while self.isop(self.peek(), '.'):
                    self.next(); self.next()
                if self.isop(self.peek(), '('):
                    self.skip_group('(', ')')
                continue
            mods = []
            while self.peek().t == 'id' and self.peek().v in MODS and (self.peek(1).t == 'id' or self.isop(self.peek(1), '[') or self.isop(self.peek(1), '*') or self.isop(self.peek(1), '#')):
                mods.append(self.next().v)
            for g in ('get', 'set'):
                if self.isid(self.peek(), g) and (self.peek(1).t == 'id' or self.isop(self.peek(1), '[')):
                    self.next()
            if self.isop(self.peek(), '*'):
                self.next()
            nt = self.peek()
            if nt.t == 'id' or nt.t == 'str' or nt.t == 'num':
                self.next()
                name = nt.v if nt.t != 'str' else nt.v[1:-1]
            elif self.isop(nt, '['):
                self.skip_group('[', ']')
                self.skip_member_rest(cidx)
                continue
            else:
                self.next()
                continue
            acc = 'public'
            for m in mods:
                if m in ACCESS:
                    acc = m
            if name.startswith('#'):
                acc = 'private'
            if self.isop(self.peek(), '?') or self.isop(self.peek(), '!'):
                self.next()
            if self.isop(self.peek(), '(') or self.isop(self.peek(), '<'):
                idx = self.make(name, 'm', nt.line, cidx, access=acc)
                if self.isop(self.peek(), '<'):
                    self.skip_angle()
                if self.isop(self.peek(), '('):
                    self.params(idx, True, ctor_cls=cidx if name == 'constructor' else None)
                if self.isop(self.peek(), ':'):
                    self.next()
                    self.skip_type_until_body()
                if self.isop(self.peek(), '{'):
                    self.next()
                    self.statements(idx, 'function', '}')
                elif self.isop(self.peek(), ';'):
                    self.next()
                continue
            # property
            self.make(name, 'p', nt.line, cidx, access=acc)
            if self.isop(self.peek(), ':'):
                self.next()
                self.skip_type()
            if self.isop(self.peek(), '='):
                self.next()
                self.skip_expr(cidx, 'class')
            if self.isop(self.peek(), ';'):
                self.next()

    def skip_member_rest(self, cidx):
        while True:
            t = self.peek()
            if t.t == 'eof' or self.isop(t, '}'):
                return
            if self.isop(t, ';'):
                self.next()
                return
            if self.isop(t, '{'):
                self.skip_group('{', '}')
                return
            if self.isop(t, '('):
                self.skip_group('(', ')')
                continue
            self.next()

    def interface_decl(self, scope):
        nt = self.next()
        while not (self.isop(self.peek(), '{') or self.peek().t == 'eof'):
            if self.isop(self.peek(), '<'):
                self.skip_angle()
                continue
            self.next()
        idx = self.make(nt.v, 'i', nt.line, scope)
        if self.peek().t == 'eof':
            return
        self.next()
        while True:
            t = self.peek()
            if t.t == 'eof':
                return
            if self.isop(t, '}'):
                self.next()
                return
            if t.t == 'op' and t.v in (';', ','):
                self.next()
                continue
            while self.isid(self.peek(), 'readonly') and self.peek(1).t == 'id':
                self.next()
            nt2 = self.peek()
            if nt2.t in ('id', 'str'):
                self.next()
                name = nt2.v if nt2.t == 'id' else nt2.v[1:-1]
                if self.isop(self.peek(), '?'):
                    self.next()
                if self.isop(self.peek(), '(') or self.isop(self.peek(), '<'):
                    self.make(name, 'm', nt2.line, idx, access='public')
                    if self.isop(self.peek(), '<'):
                        self.skip_angle()
                    self.skip_group('(', ')')
                    if self.isop(self.peek(), ':'):
                        self.next()
                        self.skip_type()
                    continue
                self.make(name, 'p', nt2.line, idx, access='public')
                if self.isop(self.peek(), ':'):
                    self.next()
                    self.skip_type()
                continue
            if self.isop(nt2, '['):
                self.skip_group('[', ']')
                if self.isop(self.peek(), ':'):
                    self.next()
                    self.skip_type()
                continue
            if self.isop(nt2, '('):
                self.skip_group('(', ')')
                if self.isop(self.peek(), ':'):
                    self.next()
                    self.skip_type()
                continue
            self.next()

    def enum_decl(self, scope):
        nt = self.next()
        idx = self.make(nt.v, 'g', nt.line, scope)
        if not self.isop(self.peek(), '{'):
            return
        self.next()
        expect = True
        depth = 0
        while True:
            t = self.peek()
            if t.t == 'eof':
                return
            if self.isop(t, '}') and depth == 0:
                self.next()
                return
            if t.t == 'op' and t.v in ('(', '[', '{'):
                depth += 1
            elif t.t == 'op' and t.v in (')', ']', '}'):
                depth -= 1
            elif depth == 0 and self.isop(t, ','):
                expect = True
                self.next()
                continue
            elif depth == 0 and expect and t.t in ('id', 'str'):
                self.make(t.v if t.t == 'id' else t.v[1:-1], 'e', t.line, idx)
                expect = False
            self.next()

def parse(ctx):
    ctx.lang.qualified = True
    Parser(ctx).parse()
