                            if cm:
                                ctx.make_tag(cm.group(1), 'c', line=lineno)
            continue
        if w in HS_KW:
            continue
        if w[0].isupper():
            continue
        if re.match(r'\s*(,\s*[a-z_][\w\']*\s*)*::', rest):
            continue
        if w != last:
            ctx.make_tag(w, 'f', line=lineno)
            last = w

def elixir(ctx):
    stack = []   # (indent, idx)
    for lineno, line in ctx.lines():
        st = line.lstrip()
        ind = len(line) - len(st)
        m = re.match(r'(defmodule|defprotocol|defimpl)\s+([A-Z][\w.]*)', st)
        if m:
            kind = {'defmodule': 'm', 'defprotocol': 'p', 'defimpl': 'i'}[m.group(1)]
            while stack and stack[-1][0] >= ind:
                stack.pop()
            scope = stack[-1][1] if (stack and kind == 'm') else 0
            idx = ctx.make_tag(m.group(2), kind, line=lineno, scope=scope)
            if kind == 'm':
                stack.append((ind, idx))
            continue
        m = re.match(r'(defp?|defmacrop?|defguardp?|defdelegate)\s+([a-z_][\w?!]*)', st)
        if m:
            while stack and stack[-1][0] >= ind:
                stack.pop()
            kind = {'def': 'f', 'defp': 'f', 'defmacro': 'a', 'defmacrop': 'a', 'defguard': 'g', 'defguardp': 'g', 'defdelegate': 'D'}[m.group(1)]
            scope = stack[-1][1] if stack else 0
            ctx.make_tag(m.group(2), kind, line=lineno, scope=scope)

def lisp_generic(ctx, table, upcase_definer=False):
