    text = ctx.text
    func = []
    for m in re.finditer(r'(?im)^[ \t]*([A-Za-z_]\w*)[ \t]*\(\s*([^\s()#]*)', text):
        cmd = m.group(1).lower()
        arg = m.group(2).strip('"')
        line = ctx.line_of(m.start(1))
        if cmd == 'project' and arg:
            ctx.make_tag(arg, 'p', line=line)
        elif cmd == 'set' and arg and not arg.startswith('$'):
            ctx.make_tag(arg, 'v', line=line)
        elif cmd in ('add_executable', 'add_library', 'add_custom_target') and arg:
            ctx.make_tag(arg, 't', line=line)
        elif cmd == 'function' and arg:
            func.append(ctx.make_tag(arg, 'f', line=line))
        elif cmd == 'endfunction' and func:
            ctx.cork[func.pop()].end = line
        elif cmd == 'macro' and arg:
            ctx.make_tag(arg, 'm', line=line)
        elif cmd == 'option' and arg:
            ctx.make_tag(arg, 'D', line=line)

TEX_LEVELS = [('part', 'p'), ('chapter', 'c'), ('section', 's'), ('subsection', 'u'), ('subsubsection', 'b'),
              ('paragraph', 'P'), ('subparagraph', 'G')]

def tex(ctx):
    stack = []
    text = ctx.text
    clean = re.sub(r'(?<!\\)%[^\n]*', lambda m: ' ' * len(m.group(0)), text)
    for m in re.finditer(r'\\(part|chapter|section|subsection|subsubsection|paragraph|subparagraph|label|newcommand|renewcommand|providecommand|newenvironment|renewenvironment|newtheorem|newcounter|def)\b\*?\s*(?:\[[^\]]*\])?\s*\{([^{}]*)\}', clean):
        cmd = m.group(1)
        arg = m.group(2).strip()
        line = ctx.line_of(m.start())
        if not arg:
            continue
        lv = [i for i, (n, k) in enumerate(TEX_LEVELS) if n == cmd]
        if lv:
            level = lv[0]
            while stack and stack[-1][0] >= level:
                stack.pop()
            idx = ctx.make_tag(arg, TEX_LEVELS[level][1], line=line, scope=stack[-1][1] if stack else 0)
            stack.append((level, idx))
        elif cmd == 'label':
            ctx.make_tag(arg, 'l', line=line)
        elif cmd in ('newcommand', 'renewcommand', 'providecommand'):
            ctx.make_tag(arg, 'C', line=line)
        elif cmd in ('newenvironment', 'renewenvironment'):
            ctx.make_tag(arg, 'e', line=line)
        elif cmd == 'newtheorem':
