"""Kotlin parser (simplified)."""
from core import *
from parsers.javascript import tokenize

def parse(ctx):
    L = ctx.lang
    L.qualified = True
    toks = tokenize(ctx.text)
    n = len(toks)
    i = 0
    pkg = 0
    stack = []   # (depth_at_open, idx)
    depth = 0
    pending = None   # tag waiting for its '{'
    def scope():
        return stack[-1][1] if stack else pkg
    def isop(t, v):
        return t.t == 'op' and t.v == v
    while i < n:
        t = toks[i]
        if t.t == 'eof':
            break
        if isop(t, '{'):
            depth += 1
            if pending is not None:
                stack.append((depth, pending))
                pending = None
            i += 1
            continue
        if isop(t, '}'):
            if stack and stack[-1][0] == depth:
                stack.pop()
            depth -= 1
            i += 1
            continue
        if t.t == 'id':
            v = t.v
            if v == 'package' and depth == 0:
                j = i + 1
                parts = []
                while j < n and toks[j].t == 'id':
                    parts.append(toks[j].v)
                    if j + 1 < n and isop(toks[j + 1], '.'):
                        j += 2
                        continue
                    break
                if parts:
                    pkg = ctx.make_tag('.'.join(parts), 'p', line=toks[i + 1].line)
                i = j + 1
                continue
            if v == 'import':
                j = i + 1
                while j < n and toks[j].line == t.line:
                    j += 1
                i = j
                continue
            if v in ('class', 'interface') and i + 1 < n and toks[i + 1].t == 'id':
                nm = toks[i + 1]
                kind = 'c' if v == 'class' else 'i'
                if i > 0 and toks[i - 1].t == 'id' and toks[i - 1].v == 'fun':
                    i += 1
                    continue
                idx = ctx.make_tag(nm.v, kind, line=nm.line, scope=scope())
                pending = idx
                j = i + 2
                if j < n and isop(toks[j], '<'):
                    d = 0
                    while j < n:
                        if isop(toks[j], '<'):
                            d += 1
                        elif isop(toks[j], '>'):
                            d -= 1
                            if d == 0:
                                break
                        j += 1
                    j += 1
                # primary constructor params
                k = j
                while k < n and toks[k].t == 'id' and toks[k].v in ('private', 'protected', 'internal', 'public', 'constructor', 'annotation'):
                    k += 1
                if k < n and isop(toks[k], '('):
                    d = 0
                    m = k
                    while m < n:
                        x = toks[m]
                        if isop(x, '('):
                            d += 1
                        elif isop(x, ')'):
                            d -= 1
                            if d == 0:
                                break
                        elif d == 1 and x.t == 'id' and x.v in ('val', 'var') and m + 1 < n and toks[m + 1].t == 'id':
                            ctx.make_tag(toks[m + 1].v, 'C' if x.v == 'val' else 'v', line=toks[m + 1].line, scope=idx)
                        m += 1
                    j = m + 1
                # if no body follows on this declaration, drop pending at end of statement
                k = j
                while k < n and not isop(toks[k], '{') and toks[k].line == nm.line and not (toks[k].t == 'id' and toks[k].v in ('class', 'fun', 'val', 'var', 'object', 'interface')):
                    k += 1
